-- -------------------------------------------- RLS: evaluate once per query ---
-- Rewrites every public policy's expressions so the tenant/role helpers sit
-- inside (select …): Postgres then runs them once as an InitPlan instead of
-- once per row. Same logic; idempotent (already-wrapped calls are skipped).
do $$
declare
  p record; v_using text; v_check text; v_sql text;
  fns text[] := array['current_salon_id', 'is_manager', 'is_staff', 'my_role', 'my_stylist_id'];
  f text;
begin
  for p in
    select pol.polname, c.relname, pol.polcmd, pol.polpermissive,
           pg_get_expr(pol.polqual, pol.polrelid) as qual,
           pg_get_expr(pol.polwithcheck, pol.polrelid) as wcheck,
           array(select rolname from pg_roles where oid = any(pol.polroles)) as roles
      from pg_policy pol join pg_class c on c.oid = pol.polrelid
     where c.relnamespace = 'public'::regnamespace
  loop
    v_using := p.qual; v_check := p.wcheck;
    foreach f in array fns loop
      -- only bare calls: "f()" not already preceded by "select "
      v_using := regexp_replace(v_using, '(?<!SELECT )(?<!select )\m' || f || '\(\)', '(select public.' || f || '())', 'g');
      v_check := regexp_replace(v_check, '(?<!SELECT )(?<!select )\m' || f || '\(\)', '(select public.' || f || '())', 'g');
    end loop;
    if v_using is not distinct from p.qual and v_check is not distinct from p.wcheck then
      continue;
    end if;
    v_sql := format('alter policy %I on public.%I', p.polname, p.relname);
    if v_using is not null then v_sql := v_sql || format(' using (%s)', v_using); end if;
    if v_check is not null then v_sql := v_sql || format(' with check (%s)', v_check); end if;
    execute v_sql;
  end loop;
end $$;

-- -------------------------------------------------- public slot view -------
-- The booking page only needs occupied slots from yesterday on. Without the
-- date filter it fetched every booking the salon ever had, oldest first —
-- and past 1000 of them the API cut off exactly the upcoming ones, so taken
-- times showed as free.
-- (dropped first: v2.49 adds a column, and re-running this file must not fail)
drop view if exists public.appointments_public_slots;
create view public.appointments_public_slots as
  select staff_id, date, start_min, end_min, buffer_minutes, status
    from public.appointments
   where salon_id = public.current_salon_id()
     and date >= public.salon_today() - 1;
grant select on public.appointments_public_slots to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.43_action_center.sql
-- ============================================================================
-- Migration v2.43 — BI action center (run after v2.42)
-- ============================================================================
-- The BI tab's "اقدام پیشنهادی" grows from a button into a managed process:
--   * bi_actions — every action the manager approves (or snoozes, or
--     dismisses) is recorded per salon, with the numbers it was based on, so
--     the result can be measured later and the same suggestion isn't repeated
--     on another device.
--   * queue_campaign() — one server-side path for a BI campaign. It enforces
--     what must not depend on the browser: opted-out customers are skipped,
--     nobody gets more than one campaign SMS per N days (default 14), and
--     nothing is sent at night (21:00–09:00 → moved to 10:00). Messages are
--     queued and the cron drain sends them through the salon's own account.
--   * bi_action_history() — each action with its measured outcome: SMS sent,
--     customers who booked within 7 days of the SMS, and their revenue.
--   * The drain re-checks opt-out at send time, and a delivered campaign SMS
--     now counts toward campaign_logs.successful_count by itself.
-- ============================================================================

create table if not exists public.bi_actions (
  id               uuid primary key default gen_random_uuid(),
  salon_id         uuid not null default public.current_salon_id() references public.salons(id) on delete cascade,
  insight_key      text not null,
  kind             text not null check (kind in ('campaign', 'automation', 'reminder', 'goto')),
  status           text not null default 'done' check (status in ('done', 'snoozed', 'dismissed')),
  title            text not null default '',
  params           jsonb not null default '{}'::jsonb,
  baseline         jsonb not null default '{}'::jsonb,   -- the metrics the suggestion was based on
  campaign_log_id  text references public.campaign_logs(id) on delete set null,
  until            timestamptz,                          -- snoozed until
  created_by       uuid default auth.uid(),
  created_at       timestamptz not null default now()
);
create index if not exists bi_actions_salon_created_idx on public.bi_actions (salon_id, created_at desc);
create index if not exists bi_actions_salon_key_idx on public.bi_actions (salon_id, insight_key);
alter table public.bi_actions enable row level security;
drop policy if exists p_bi_actions_read on public.bi_actions;
create policy p_bi_actions_read on public.bi_actions for select
  using (salon_id = (select public.current_salon_id()) and (select public.is_manager()));
drop policy if exists p_bi_actions_write on public.bi_actions;
create policy p_bi_actions_write on public.bi_actions for insert
  with check (salon_id = (select public.current_salon_id()) and (select public.is_manager()));
revoke all on public.bi_actions from anon;
grant select, insert on public.bi_actions to authenticated;

-- Frequency-cap lookups ("did this phone get a campaign SMS lately?").
create index if not exists sms_messages_campaign_phone_idx
  on public.sms_messages (salon_id, to_phone, created_at desc) where kind = 'campaign';

-- ------------------------------------------------------------ helpers ------
/** 10:00 the same/next day when p_at falls in quiet hours (salon local time). */
create or replace function public.outside_quiet_hours(p_at timestamptz)
returns timestamptz
language sql stable set search_path = public as $fn$
  with t as (
    select coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran') as tz
  ), l as (
    select (greatest(p_at, now()) at time zone t.tz) as local_ts, t.tz from t
  )
  select case
    when extract(hour from local_ts) < 9  then (date_trunc('day', local_ts) + interval '10 hours') at time zone tz
    when extract(hour from local_ts) >= 21 then (date_trunc('day', local_ts) + interval '1 day 10 hours') at time zone tz
    else greatest(p_at, now())
  end
  from l;
$fn$;

-- ------------------------------------------------------ queue_campaign -----
-- p_recipients: [{ "phone": "09…", "name": "…", "vars": { … } }, …]
-- p_body: template with {{name}}, {{salon}}, {{days}}, … rendered per person.
create or replace function public.queue_campaign(
  p_insight_key text, p_title text, p_segment text, p_body text, p_recipients jsonb,
  p_send_at timestamptz default null, p_cap_days int default 14, p_baseline jsonb default '{}'::jsonb)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_salon uuid := public.current_salon_id();
  v_salon_name text;
  v_send_at timestamptz;
  v_campaign_id text := 'cmp-' || substr(md5(gen_random_uuid()::text), 1, 12);
  v_log_id text;
  v_total int; v_opted int; v_recent int; v_invalid int; v_queued int;
begin
  if v_salon is null or not public.is_manager() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if coalesce(trim(p_body), '') = '' then
    return json_build_object('ok', false, 'error', 'متن پیامک خالی است');
  end if;
  if length(p_body) > 600 then
    return json_build_object('ok', false, 'error', 'متن پیامک خیلی طولانی است');
  end if;
  if jsonb_typeof(p_recipients) is distinct from 'array' or jsonb_array_length(p_recipients) = 0 then
    return json_build_object('ok', false, 'error', 'گیرنده‌ای انتخاب نشده');
  end if;
  if jsonb_array_length(p_recipients) > 5000 then
    return json_build_object('ok', false, 'error', 'حداکثر ۵۰۰۰ گیرنده در هر ارسال');
  end if;
  select name into v_salon_name from public.salons where id = v_salon;
  v_send_at := public.outside_quiet_hours(coalesce(p_send_at, now()));
  if v_send_at > now() + interval '14 days' then
    return json_build_object('ok', false, 'error', 'زمان ارسال حداکثر ۱۴ روز بعد');
  end if;

  drop table if exists _rcpt;
  create temp table _rcpt on commit drop as
  select distinct on (r.phone) r.phone, r.name, r.vars,
         (r.phone !~ '^09[0-9]{9}$') as invalid,
         coalesce(c.sms_opt_out, false) as opted_out,
         exists (select 1 from public.sms_messages m
                  where m.salon_id = v_salon and m.to_phone = r.phone and m.kind = 'campaign'
                    and m.status in ('queued', 'sending', 'sent', 'delivered')
                    and coalesce(m.sent_at, m.scheduled_for, m.created_at) > now() - make_interval(days => greatest(coalesce(p_cap_days, 14), 0))
                    and coalesce(p_cap_days, 14) > 0) as recent
    from (
      select trim(coalesce(e ->> 'phone', '')) as phone,
             nullif(trim(coalesce(e ->> 'name', '')), '') as name,
             coalesce(e -> 'vars', '{}'::jsonb) as vars
        from jsonb_array_elements(p_recipients) e
    ) r
    left join public.customers c on c.salon_id = v_salon and c.phone = r.phone
   order by r.phone;

  select count(*), count(*) filter (where invalid), count(*) filter (where opted_out and not invalid),
         count(*) filter (where recent and not opted_out and not invalid)
    into v_total, v_invalid, v_opted, v_recent from _rcpt;
  v_queued := v_total - v_invalid - v_opted - v_recent;
  if v_queued <= 0 then
    return json_build_object('ok', false, 'error', 'همهٔ گیرنده‌ها کنار گذاشته شدند (انصراف یا پیامک اخیر)',
                             'skipped_opt_out', v_opted, 'skipped_recent', v_recent, 'skipped_invalid', v_invalid);
  end if;

  insert into public.campaigns (id, salon_id, name, status, targeted_count)
  values (v_campaign_id, v_salon, coalesce(nullif(p_title, ''), 'کمپین'), 'sent', v_queued);
  insert into public.campaign_logs (salon_id, template_id, template_label, segment, total_sent, successful_count, created_by, sent_at)
  values (v_salon, coalesce(nullif(p_segment, ''), 'bi_' || p_insight_key), coalesce(nullif(p_title, ''), 'کمپین'),
          nullif(p_segment, ''), v_queued, 0, auth.uid(), v_send_at)
  returning id into v_log_id;
  insert into public.campaign_targets (salon_id, campaign_id, customer_phone)
  select v_salon, v_campaign_id, phone from _rcpt where not (invalid or opted_out or recent)
  on conflict (campaign_id, customer_phone) do nothing;
  insert into public.sms_messages (salon_id, to_phone, body, kind, campaign_id, campaign_log_id, status, scheduled_for)
  select v_salon, phone,
         public.render_sms(p_body, jsonb_build_object('name', coalesce(name, 'مشتری'), 'salon', coalesce(v_salon_name, '')) || vars),
         'campaign', v_campaign_id, v_log_id, 'queued', v_send_at
    from _rcpt where not (invalid or opted_out or recent);

  insert into public.bi_actions (salon_id, insight_key, kind, title, params, baseline, campaign_log_id)
  values (v_salon, p_insight_key, 'campaign', coalesce(p_title, ''),
          jsonb_build_object('segment', p_segment, 'queued', v_queued, 'send_at', v_send_at, 'body', p_body),
          coalesce(p_baseline, '{}'::jsonb), v_log_id);

  return json_build_object('ok', true, 'queued', v_queued, 'send_at', v_send_at, 'campaign_log_id', v_log_id,
                           'skipped_opt_out', v_opted, 'skipped_recent', v_recent, 'skipped_invalid', v_invalid,
                           'deferred', v_send_at > now() + interval '2 minutes');
end;
$fn$;
revoke all on function public.queue_campaign(text, text, text, text, jsonb, timestamptz, int, jsonb) from public, anon;
grant execute on function public.queue_campaign(text, text, text, text, jsonb, timestamptz, int, jsonb) to authenticated;

-- Phones that got a campaign SMS from this salon in the last p_days — the
-- action wizard shows them as "recently contacted" before sending.
create or replace function public.recent_campaign_phones(p_days int default 14)
returns table (phone text)
language sql stable security definer set search_path = public as $fn$
  select distinct m.to_phone
    from public.sms_messages m
   where public.is_manager()
     and m.salon_id = public.current_salon_id()
     and m.kind = 'campaign'
     and m.status in ('queued', 'sending', 'sent', 'delivered')
     and coalesce(m.sent_at, m.scheduled_for, m.created_at) > now() - make_interval(days => greatest(p_days, 0));
$fn$;
revoke all on function public.recent_campaign_phones(int) from public, anon;
grant execute on function public.recent_campaign_phones(int) to authenticated;

-- ------------------------------------------------- record / snooze ---------
create or replace function public.record_bi_action(p_insight_key text, p_kind text, p_status text,
                                                   p_title text default '', p_params jsonb default '{}'::jsonb,
                                                   p_baseline jsonb default '{}'::jsonb, p_snooze_days int default 7)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id(); v_id uuid;
begin
  if v_salon is null or not public.is_manager() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if p_status not in ('done', 'snoozed', 'dismissed') or p_kind not in ('campaign', 'automation', 'reminder', 'goto') then
    return json_build_object('ok', false, 'error', 'درخواست نامعتبر');
  end if;
  insert into public.bi_actions (salon_id, insight_key, kind, status, title, params, baseline, until)
  values (v_salon, left(p_insight_key, 120), p_kind, p_status, left(coalesce(p_title, ''), 200),
          coalesce(p_params, '{}'::jsonb), coalesce(p_baseline, '{}'::jsonb),
          case when p_status = 'snoozed' then now() + make_interval(days => least(greatest(coalesce(p_snooze_days, 7), 1), 90)) end)
  returning id into v_id;
  return json_build_object('ok', true, 'id', v_id);
end;
$fn$;
revoke all on function public.record_bi_action(text, text, text, text, jsonb, jsonb, int) from public, anon;
grant execute on function public.record_bi_action(text, text, text, text, jsonb, jsonb, int) to authenticated;

-- ------------------------------------------------------ history + results --
-- Conversions come from campaign_conversions (a booking made within 7 days of
-- the customer's campaign SMS, see track_campaign_conversion); revenue counts
-- only those bookings that were completed.
create or replace function public.bi_action_history(p_limit int default 50)
returns table (
  id uuid, insight_key text, kind text, status text, title text, params jsonb, baseline jsonb,
  until timestamptz, created_at timestamptz, campaign_log_id text,
  sms_queued int, sms_sent int, sms_failed int, conversions int, revenue bigint, measure_until timestamptz
)
language sql stable security definer set search_path = public as $fn$
  select a.id, a.insight_key, a.kind, a.status, a.title, a.params, a.baseline, a.until, a.created_at, a.campaign_log_id,
         coalesce(s.queued, 0), coalesce(s.sent, 0), coalesce(s.failed, 0),
         coalesce(cv.n, 0), coalesce(cv.revenue, 0),
         case when a.campaign_log_id is not null then coalesce(cl.sent_at, a.created_at) + interval '7 days' end
    from public.bi_actions a
    left join public.campaign_logs cl on cl.id = a.campaign_log_id
    left join lateral (
      select count(*) filter (where m.status in ('queued', 'sending'))::int as queued,
             count(*) filter (where m.status in ('sent', 'delivered'))::int as sent,
             count(*) filter (where m.status = 'failed')::int as failed
        from public.sms_messages m where m.campaign_log_id = a.campaign_log_id and m.salon_id = a.salon_id
    ) s on a.campaign_log_id is not null
    left join lateral (
      select count(distinct c.customer_phone)::int as n,
             coalesce(sum(ap.final_price) filter (where ap.status = 'completed'), 0)::bigint as revenue
        from public.campaign_conversions c
        left join public.appointments ap on ap.id = c.appointment_id
       where c.campaign_log_id = a.campaign_log_id and c.salon_id = a.salon_id
    ) cv on a.campaign_log_id is not null
   where public.is_manager() and a.salon_id = public.current_salon_id()
   order by a.created_at desc
   limit least(greatest(coalesce(p_limit, 50), 1), 200);
$fn$;
revoke all on function public.bi_action_history(int) from public, anon;
grant execute on function public.bi_action_history(int) to authenticated;

-- --------------------------------------- delivered campaign SMS counted ----
create or replace function public.count_campaign_delivery()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if new.campaign_log_id is not null and new.status in ('sent', 'delivered')
     and old.status not in ('sent', 'delivered') then
    update public.campaign_logs set successful_count = successful_count + 1 where id = new.campaign_log_id;
  end if;
  return new;
end;
$fn$;
revoke all on function public.count_campaign_delivery() from public, anon, authenticated;
drop trigger if exists trg_count_campaign_delivery on public.sms_messages;
create trigger trg_count_campaign_delivery after update of status on public.sms_messages
  for each row execute function public.count_campaign_delivery();

-- ------------------------------------------------ fair, prioritised queue ---
-- With campaigns queued server-side, one salon's 5000-SMS campaign used to
-- sit in front of every salon's booking confirmations and reminders (the
-- claim took the oldest due rows first). Now: transactional messages first,
-- then campaigns interleaved across salons (each salon's 1st, then each
-- salon's 2nd, …). Exactly-once is kept: candidates are locked with SKIP
-- LOCKED and re-checked before being marked 'sending'.
create or replace function public.claim_due_sms(p_limit integer default 200)
returns setof public.sms_messages
language plpgsql security definer set search_path = public as $fn$
begin
  return query
  with due as (
    select q.id,
           (q.kind = 'campaign') as is_campaign,
           row_number() over (partition by q.salon_id, (q.kind = 'campaign') order by q.scheduled_for, q.id) as turn,
           q.scheduled_for
      from public.sms_messages q
      join public.salons s on s.id = q.salon_id and s.active
     where q.scheduled_for <= now()
       and (q.status = 'queued' or (q.status = 'sending' and q.claimed_at < now() - interval '10 minutes'))
  ), picked as (
    select d.id from due d
     order by d.is_campaign, d.turn, d.scheduled_for
     limit greatest(p_limit, 1)
  ), locked as (
    select m.id from public.sms_messages m
     where m.id in (select id from picked)
       for update skip locked
  )
  update public.sms_messages m
     set status = 'sending', claimed_at = now()
   where m.id in (select id from locked)
     and (m.status = 'queued' or (m.status = 'sending' and m.claimed_at < now() - interval '10 minutes'))
  returning m.*;
end;
$fn$;
revoke all on function public.claim_due_sms(int) from public, anon, authenticated;
grant execute on function public.claim_due_sms(int) to service_role;


-- >>>>>>>>>> supabase/migrations/v2.44_pet_grooming.sql
-- ============================================================================
-- Migration v2.44 — pet grooming salons (run after v2.43)
-- ============================================================================
--  A salon is now one of two kinds, set by the platform admin:
--    beauty — as before: female / male sections.
--    pet    — a dog & cat grooming salon: dog / cat sections.
--  The existing "section" column (services.gender, appointments.
--  customer_gender, stylists.gender) carries the new values, so the booking,
--  scheduling, waitlist and reporting machinery works unchanged. Groomers
--  can be dog-only, cat-only, or "pet" (both).
--
--  1. salons.business_type; section helpers.
--  2. pets — one profile per animal (owner phone, species, breed, size,
--     weight, temperament, vaccination, notes for and from the groomer).
--  3. services.size_pricing — price and duration per size (small … giant);
--     anything not set falls back to the service's base price/duration.
--  4. appointments.pet_id / pet_name / pet_size — the animal and the size
--     the booking was priced for.
--  5. create_public_booking takes the pet (p_pet jsonb): validates it,
--     upserts the profile, prices and times the booking for its size, and
--     enforces the salon's "valid vaccination required" setting.
--     Reschedule and salon-sent booking links keep the size-based duration.
--  6. SMS: {{pet}} variable, pet wording for the default texts, and the
--     groomer's new-booking SMS names the animal and flags an aggressive one.
--  7. Admin: create a pet salon (with starter dog/cat services), type in
--     the salon list, change type while the salon has no bookings.
-- ============================================================================

-- ------------------------------------------------------ 1. salon type ------
alter table public.salons add column if not exists business_type text not null default 'beauty';
alter table public.salons drop constraint if exists salons_business_type_check;
alter table public.salons add constraint salons_business_type_check check (business_type in ('beauty', 'pet'));
grant select (business_type) on public.salons to anon, authenticated;

-- Sections are stored in the existing gender columns.
alter table public.services drop constraint if exists services_gender_check;
alter table public.services add constraint services_gender_check check (gender in ('female', 'male', 'dog', 'cat'));
alter table public.appointments drop constraint if exists appointments_customer_gender_check;
alter table public.appointments add constraint appointments_customer_gender_check check (customer_gender in ('female', 'male', 'dog', 'cat'));
alter table public.customers drop constraint if exists customers_gender_check;
alter table public.customers add constraint customers_gender_check check (gender in ('female', 'male', 'dog', 'cat'));
alter table public.stylists drop constraint if exists stylists_gender_check;
alter table public.stylists add constraint stylists_gender_check check (gender in ('female', 'male', 'dog', 'cat', 'pet'));

create or replace function public.salon_sections(p_salon uuid)
returns text[]
language sql stable security definer set search_path = public as $fn$
  select case when business_type = 'pet' then array['dog', 'cat'] else array['female', 'male'] end
    from public.salons where id = p_salon;
$fn$;
revoke all on function public.salon_sections(uuid) from public, anon, authenticated;

alter table public.app_settings add column if not exists pet_require_vaccination boolean not null default false;

-- --------------------------------------------------------- 2. pets ---------
create table if not exists public.pets (
  id                  uuid primary key default gen_random_uuid(),
  salon_id            uuid not null default public.current_salon_id() references public.salons (id) on delete cascade,
  owner_phone         text not null check (owner_phone ~ '^09[0-9]{9}$'),
  name                text not null check (length(trim(name)) between 1 and 40),
  species             text not null check (species in ('dog', 'cat')),
  breed               text not null default '' check (length(breed) <= 40),
  size                text not null default 'medium' check (size in ('small', 'medium', 'large', 'giant')),
  weight_kg           numeric(5, 1) check (weight_kg is null or (weight_kg > 0 and weight_kg <= 150)),
  temperament         text not null default 'calm' check (temperament in ('calm', 'nervous', 'aggressive')),
  vaccine_valid_until date,
  owner_notes         text not null default '' check (length(owner_notes) <= 300),
  grooming_notes      text not null default '' check (length(grooming_notes) <= 1000),
  last_visit_date     date,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create unique index if not exists pets_owner_name_uidx on public.pets (salon_id, owner_phone, species, lower(name));
create index if not exists pets_salon_owner_idx on public.pets (salon_id, owner_phone);

alter table public.pets enable row level security;
revoke all on public.pets from anon;
grant select, insert, update, delete on public.pets to authenticated;

drop policy if exists p_pets_mgr on public.pets;
create policy p_pets_mgr on public.pets for all
  using ((select public.is_manager()) and salon_id = (select public.current_salon_id()))
  with check ((select public.is_manager()) and salon_id = (select public.current_salon_id()));
-- A groomer sees, and can add notes to, the animals of customers they serve.
drop policy if exists p_pets_staff_read on public.pets;
create policy p_pets_staff_read on public.pets for select
  using (salon_id = (select public.current_salon_id())
         and exists (select 1 from public.appointments a
                      where a.salon_id = pets.salon_id and a.customer_phone = pets.owner_phone
                        and a.staff_id = (select public.my_stylist_id())));
drop policy if exists p_pets_staff_update on public.pets;
create policy p_pets_staff_update on public.pets for update
  using (salon_id = (select public.current_salon_id())
         and exists (select 1 from public.appointments a
                      where a.salon_id = pets.salon_id and a.customer_phone = pets.owner_phone
                        and a.staff_id = (select public.my_stylist_id())))
  with check (salon_id = (select public.current_salon_id()));

create or replace function public.touch_pet()
returns trigger
language plpgsql as $fn$
begin
  new.updated_at := now();
  new.name := trim(new.name);
  new.breed := trim(new.breed);
  return new;
end;
$fn$;
drop trigger if exists trg_touch_pet on public.pets;
create trigger trg_touch_pet before insert or update on public.pets
  for each row execute function public.touch_pet();

-- ------------------------------------------------- 3. size pricing ---------
alter table public.services add column if not exists size_pricing jsonb not null default '{}'::jsonb;
alter table public.services drop constraint if exists services_size_pricing_check;
alter table public.services add constraint services_size_pricing_check check (jsonb_typeof(size_pricing) = 'object');

-- The service as booked for an animal of this size: price and duration
-- from size_pricing when set there, otherwise the service's own.
create or replace function public.service_at_size(p_svc public.services, p_size text)
returns public.services
language plpgsql immutable as $fn$
declare v_tier jsonb;
begin
  if p_size is null or p_svc.size_pricing is null then
    return p_svc;
  end if;
  v_tier := p_svc.size_pricing -> p_size;
  if jsonb_typeof(v_tier) = 'object' then
    if jsonb_typeof(v_tier -> 'price') = 'number' and (v_tier ->> 'price')::numeric >= 0 then
      p_svc.price := round((v_tier ->> 'price')::numeric)::bigint;
    end if;
    if jsonb_typeof(v_tier -> 'duration') = 'number' and (v_tier ->> 'duration')::numeric between 5 and 600 then
      p_svc.duration_minutes := round((v_tier ->> 'duration')::numeric)::int;
    end if;
  end if;
  return p_svc;
end;
$fn$;

-- ------------------------------------------- 4. pet on the booking ---------
alter table public.appointments add column if not exists pet_id uuid references public.pets (id) on delete set null;
alter table public.appointments add column if not exists pet_name text;
alter table public.appointments add column if not exists pet_size text;
alter table public.appointments drop constraint if exists appointments_pet_size_check;
alter table public.appointments add constraint appointments_pet_size_check check (pet_size is null or pet_size in ('small', 'medium', 'large', 'giant'));
create index if not exists appointments_pet_idx on public.appointments (pet_id) where pet_id is not null;

-- The pet must belong to the booking's salon; name/size are snapshotted so
-- the booking keeps what it was priced for if the profile changes later.
create or replace function public.appointment_pet_snapshot()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_pet record;
begin
  if new.pet_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.pet_id is not distinct from old.pet_id then
    return new;
  end if;
  select name, size, salon_id into v_pet from public.pets where id = new.pet_id;
  if v_pet.salon_id is distinct from new.salon_id then
    raise exception 'pet does not belong to this salon' using errcode = '42501';
  end if;
  new.pet_name := coalesce(new.pet_name, v_pet.name);
  new.pet_size := coalesce(new.pet_size, v_pet.size);
  return new;
end;
$fn$;
drop trigger if exists trg_appointment_pet_snapshot on public.appointments;
create trigger trg_appointment_pet_snapshot before insert or update of pet_id on public.appointments
  for each row execute function public.appointment_pet_snapshot();

create or replace function public.pet_last_visit()
returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if new.pet_id is not null and new.status = 'completed' and old.status is distinct from 'completed' then
    update public.pets set last_visit_date = greatest(coalesce(last_visit_date, new.date), new.date) where id = new.pet_id;
  end if;
  return new;
end;
$fn$;
drop trigger if exists trg_pet_last_visit on public.appointments;
create trigger trg_pet_last_visit after update of status on public.appointments
  for each row execute function public.pet_last_visit();

create or replace function public.try_date(p text)
returns date
language plpgsql immutable as $fn$
begin
  if p is null or p !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    return null;
  end if;
  return p::date;
exception when others then
  return null;
end;
$fn$;

-- Creates or refreshes the profile a public booking names. Fields the form
-- left empty keep what is on file; the groomer's notes are never touched.
create or replace function public.upsert_pet(p_salon uuid, p_phone text, p_species text, p_pet jsonb)
returns uuid
language plpgsql security definer set search_path = public as $fn$
declare v_id uuid; v_weight numeric;
begin
  if coalesce(p_pet ->> 'weight_kg', '') ~ '^[0-9]{1,3}(\.[0-9]+)?$' then
    v_weight := (p_pet ->> 'weight_kg')::numeric;
    if v_weight <= 0 or v_weight > 150 then v_weight := null; end if;
  end if;
  insert into public.pets as p (salon_id, owner_phone, name, species, breed, size, weight_kg, temperament, vaccine_valid_until, owner_notes)
  values (p_salon, p_phone, trim(p_pet ->> 'name'), p_species,
          left(trim(coalesce(p_pet ->> 'breed', '')), 40),
          p_pet ->> 'size', v_weight,
          coalesce(nullif(p_pet ->> 'temperament', ''), 'calm'),
          public.try_date(p_pet ->> 'vaccine_valid_until'),
          left(trim(coalesce(p_pet ->> 'notes', '')), 300))
  on conflict (salon_id, owner_phone, species, lower(name)) do update
     set breed               = coalesce(nullif(excluded.breed, ''), p.breed),
         size                = excluded.size,
         weight_kg           = coalesce(excluded.weight_kg, p.weight_kg),
         temperament         = case when p_pet ? 'temperament' then excluded.temperament else p.temperament end,
         vaccine_valid_until = coalesce(excluded.vaccine_valid_until, p.vaccine_valid_until),
         owner_notes         = coalesce(nullif(excluded.owner_notes, ''), p.owner_notes)
  returning id into v_id;
  return v_id;
end;
$fn$;
revoke all on function public.upsert_pet(uuid, text, text, jsonb) from public, anon, authenticated;

-- -------------------------------------------- 5. booking functions ---------
drop function if exists public.create_public_booking(text, text, date, int, text, text, text, text);

create or replace function public.create_public_booking(
  p_service_id text, p_staff_id text, p_date date, p_start_min int,
  p_customer_name text, p_customer_phone text, p_customer_gender text,
  p_referral_code text default null,
  p_pet jsonb default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_svc public.services; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_salon_id uuid;
  v_status text; v_deposit bigint;
  v_type text; v_pet_id uuid; v_pet_name text; v_size text; v_vacc date; v_require_vacc boolean;
begin
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if p_customer_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  -- v2.32: a returning customer's name is no longer sent to the browser
  -- (customer_loyalty is PII-free for anonymous callers), so an empty name
  -- falls back to the one already on file for this phone.
  if coalesce(trim(p_customer_name), '') = '' then
    select name into p_customer_name from public.customers where salon_id = v_salon_id and phone = p_customer_phone;
  end if;
  if coalesce(trim(p_customer_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  -- v2.44: the sections depend on the salon's type (female/male or dog/cat).
  select business_type into v_type from public.salons where id = v_salon_id;
  if p_customer_gender is null or not (p_customer_gender = any (public.salon_sections(v_salon_id))) then
    return json_build_object('ok', false, 'error', case when v_type = 'pet' then 'نوع حیوان نامعتبر است' else 'جنسیت نامعتبر است' end);
  end if;
  if v_type = 'pet' then
    v_pet_name := nullif(trim(coalesce(p_pet ->> 'name', '')), '');
    v_size := p_pet ->> 'size';
    if v_pet_name is null or length(v_pet_name) > 40 then
      return json_build_object('ok', false, 'error', 'نام حیوان را وارد کنید');
    end if;
    if v_size is null or v_size not in ('small', 'medium', 'large', 'giant') then
      return json_build_object('ok', false, 'error', 'جثهٔ حیوان را انتخاب کنید');
    end if;
    if coalesce(p_pet ->> 'temperament', 'calm') not in ('calm', 'nervous', 'aggressive') then
      return json_build_object('ok', false, 'error', 'رفتار حیوان نامعتبر است');
    end if;
    v_vacc := public.try_date(p_pet ->> 'vaccine_valid_until');
  end if;
  if not public.check_rate_limit('create_booking:' || v_salon_id || ':' || p_customer_phone, 10, 30) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — کمی بعد دوباره امتحان کنید');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  select * into v_svc from public.services where id = p_service_id and salon_id = v_salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_svc.gender <> p_customer_gender then
    return json_build_object('ok', false, 'error', case when v_type = 'pet' then 'این خدمت برای این حیوان نیست' else 'این خدمت با جنسیت انتخابی مطابقت ندارد' end);
  end if;
  v_svc := public.service_at_size(v_svc, v_size); -- price and duration for the animal's size
  if v_type = 'pet' then
    select pet_require_vaccination into v_require_vacc from public.app_settings where salon_id = v_salon_id;
    if coalesce(v_require_vacc, false) and (v_vacc is null or v_vacc < p_date) then
      return json_build_object('ok', false, 'error', 'این سالن کارت واکسن معتبر تا روز نوبت را لازم می‌داند — تاریخ اعتبار واکسن را وارد کنید');
    end if;
  end if;

  if p_staff_id is not null and not exists (select 1 from public.stylists where id = p_staff_id and salon_id = v_salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = p_staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(p_customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  if v_type = 'pet' then
    v_pet_id := public.upsert_pet(v_salon_id, p_customer_phone, p_customer_gender, p_pet);
  end if;

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price,
      pet_id, pet_name, pet_size
    ) values (
      v_id, v_salon_id, trim(p_customer_name), p_customer_phone, p_customer_gender, p_service_id, p_staff_id,
      coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'pending',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final,
      v_pet_id, v_pet_name, v_size
    )
    returning status, deposit_amount into v_status, v_deposit; -- after the auto-confirm / deposit triggers
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  if p_referral_code is not null and length(trim(p_referral_code)) > 0 then
    perform public.apply_referral(p_customer_phone, p_referral_code);
  end if;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
    'status', v_status, 'deposit_amount', v_deposit
  );
end;
$fn$;
grant execute on function public.create_public_booking(text, text, date, int, text, text, text, text, jsonb) to anon, authenticated;

create or replace function public.reschedule_my_booking_with_token(
  p_token text, p_appointment_id text, p_new_date date, p_new_start_min int
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_phone text; v_salon_id uuid; v_appt record; v_svc public.services;
  v_new_end int; v_app_dow int; v_wh record; v_wh_start int; v_wh_end int;
begin
  select r.phone, r.salon_id into v_phone, v_salon_id from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;

  select * into v_appt from public.appointments where id = p_appointment_id;
  if v_appt is null or v_appt.customer_phone <> v_phone or v_appt.salon_id <> v_salon_id then
    return json_build_object('ok', false, 'error', 'این نوبت متعلق به شما نیست');
  end if;
  -- v2.38: only a live booking can move. Without this, a customer could
  -- "reschedule" a cancelled / completed / no-show booking back to life, or
  -- an unpaid deposit hold into a normal booking without paying.
  if v_appt.status not in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed') then
    return json_build_object('ok', false, 'error', 'این نوبت دیگر قابل تغییر نیست');
  end if;
  if p_new_date < public.salon_today() then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_new_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;

  select * into v_svc from public.services where id = v_appt.service_id and salon_id = v_salon_id;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت مرتبط با این نوبت یافت نشد');
  end if;
  v_svc := public.service_at_size(v_svc, v_appt.pet_size); -- v2.44: pet bookings keep their size's duration
  v_new_end := p_new_start_min + v_svc.duration_minutes;

  v_app_dow := (extract(dow from p_new_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_appt.staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  if p_new_start_min < v_wh_start or v_new_end > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  begin
    update public.appointments
       set date = p_new_date, start_min = p_new_start_min, end_min = v_new_end,
           status = 'rescheduled', pending_date = null, pending_start_min = null, pending_end_min = null
     where id = p_appointment_id;
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.reschedule_my_booking_with_token(text, text, date, int) to anon, authenticated;

create or replace function public.create_booking_from_rebooking_token(
  p_token text, p_date date, p_start_min int, p_staff_id text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_rt record; v_svc public.services; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_staff_id text;
  v_pet_id uuid; v_pet_name text; v_pet_size text;
begin
  select * into v_rt from public.rebooking_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
  if v_rt is null then
    return json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است');
  end if;
  if v_rt.service_id is null then
    return json_build_object('ok', false, 'error', 'این لینک برای خدمت مشخصی نیست');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_rt.salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_rt.salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  -- Staff can be the one the customer originally had, or a different one
  -- the customer actively chooses on the booking page — either way it's
  -- just "who performs the service", not an identity field, so it's safe
  -- to accept as a direct parameter (validated against this same salon).
  v_staff_id := coalesce(p_staff_id, v_rt.staff_id);
  select * into v_svc from public.services where id = v_rt.service_id and salon_id = v_rt.salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  -- v2.44: a pet salon's link books the customer's animal of that species
  -- (most recently groomed first), priced and timed for its size.
  if v_svc.gender in ('dog', 'cat') then
    select p.id, p.name, p.size into v_pet_id, v_pet_name, v_pet_size
      from public.pets p
     where p.salon_id = v_rt.salon_id and p.owner_phone = v_rt.customer_phone and p.species = v_svc.gender
     order by p.last_visit_date desc nulls last, p.created_at desc
     limit 1;
    v_svc := public.service_at_size(v_svc, v_pet_size);
  end if;
  if v_staff_id is not null and not exists (select 1 from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_staff_id and salon_id = v_rt.salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_rt.salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(v_rt.customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  -- v2.38: links the salon itself sent (closure rebooking, waitlist offer,
  -- predictive invitation) never wait for an online deposit — the page
  -- behind them has no payment step. Transaction-local flag read by
  -- hold_for_deposit().
  perform set_config('app.skip_deposit', 'on', true);

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price,
      pet_id, pet_name, pet_size
    ) values (
      v_id, v_rt.salon_id,
      coalesce(nullif(v_rt.customer_name, ''), (select name from public.customers where salon_id = v_rt.salon_id and phone = v_rt.customer_phone), ''),
      v_rt.customer_phone, v_svc.gender, v_rt.service_id, v_staff_id,
      coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'confirmed',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final,
      v_pet_id, v_pet_name, v_pet_size
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  update public.rebooking_tokens set used_at = now() where id = v_rt.id;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), '')
  );
end;
$fn$;
grant execute on function public.create_booking_from_rebooking_token(text, date, int, text) to anon, authenticated;

-- ---------------------------------------------------------- 6. SMS ---------
create or replace function public.pet_size_label(p_size text)
returns text
language sql immutable as $fn$
  select case p_size when 'small' then 'کوچک' when 'medium' then 'متوسط' when 'large' then 'بزرگ' when 'giant' then 'خیلی بزرگ' else '' end;
$fn$;

create or replace function public.booking_sms_text(p_appt public.appointments, p_kind text)
returns text
language plpgsql stable security definer set search_path = public as $fn$
declare v_tpl text; v_service text; v_salon text; v_pet boolean := coalesce(p_appt.pet_name, '') <> '';
begin
  select body into v_tpl from public.sms_templates
   where salon_id = p_appt.salon_id and kind = p_kind and body <> ''
   order by is_default desc, created_at limit 1;
  v_tpl := coalesce(v_tpl, case
    when p_kind = 'confirmation' and v_pet then E'{{name}} عزیز، نوبت {{pet}} در {{salon}} ثبت شد.\nخدمت: {{service}}\nتاریخ: {{date}} ساعت {{time}}\nکد پیگیری: {{code}}'
    when p_kind = 'reminder' and v_pet     then E'{{name}} عزیز، یادآوری نوبت {{pet}} در {{salon}}:\n{{service}} — {{date}} ساعت {{time}}\nمنتظر شما و {{pet}} هستیم.'
    when p_kind = 'confirmation'           then E'{{name}} عزیز، نوبت شما در {{salon}} ثبت شد.\nخدمت: {{service}}\nتاریخ: {{date}} ساعت {{time}}\nکد پیگیری: {{code}}'
    when p_kind = 'reminder'               then E'{{name}} عزیز، یادآوری نوبت شما در {{salon}}:\n{{service}} — {{date}} ساعت {{time}}\nمنتظر شما هستیم.'
  end);
  select name into v_service from public.services where id = p_appt.service_id and salon_id = p_appt.salon_id;
  select name into v_salon from public.salons where id = p_appt.salon_id;
  return public.render_sms(v_tpl, jsonb_build_object(
    'name',    coalesce(nullif(trim(p_appt.customer_name), ''), 'مشتری'),
    'pet',     coalesce(nullif(trim(p_appt.pet_name), ''), case when p_appt.customer_gender = 'cat' then 'گربهٔ شما' when p_appt.customer_gender = 'dog' then 'سگ شما' else '' end),
    'service', coalesce(v_service, 'خدمت'),
    'date',    public.jalali_label(p_appt.date),
    'time',    public.fa_clock(p_appt.start_min),
    'stylist', coalesce(nullif(p_appt.staff_name, ''), 'بدون آرایشگر مشخص'),
    'code',    coalesce(p_appt.tracking_code, ''),
    'salon',   coalesce(v_salon, 'سالن')
  ));
end;
$fn$;
revoke all on function public.booking_sms_text(public.appointments, text) from public, anon, authenticated;

create or replace function public.send_new_booking_messages(p_appt public.appointments)
returns void
language plpgsql security definer set search_path = public as $fn$
declare v_staff_phone text; v_digest boolean; v_service text; v_pet record; v_who text;
begin
  if p_appt.customer_phone ~ '^09[0-9]{9}$' then
    insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
    values (p_appt.salon_id, p_appt.customer_phone, public.booking_sms_text(p_appt, 'confirmation'),
            'confirmation', p_appt.id, 'queued', now());
  end if;

  if p_appt.staff_id is not null then
    select phone into v_staff_phone from public.stylists where id = p_appt.staff_id and salon_id = p_appt.salon_id;
    select staff_daily_digest into v_digest from public.app_settings where salon_id = p_appt.salon_id;
    if v_staff_phone ~ '^09[0-9]{9}$' and (not coalesce(v_digest, false) or p_appt.date = public.salon_today()) then
      select name into v_service from public.services where id = p_appt.service_id and salon_id = p_appt.salon_id;
      v_who := coalesce(nullif(trim(p_appt.customer_name), ''), 'مشتری');
      if p_appt.pet_id is not null then
        select species, breed, temperament into v_pet from public.pets where id = p_appt.pet_id;
        v_who := coalesce(p_appt.pet_name, '') || ' ('
          || case v_pet.species when 'cat' then 'گربه' else 'سگ' end
          || case when coalesce(v_pet.breed, '') <> '' then '، ' || v_pet.breed else '' end
          || '، ' || public.pet_size_label(p_appt.pet_size) || ') — صاحب: ' || v_who
          || case v_pet.temperament when 'aggressive' then E'\n⚠ پرخاشگر — با احتیاط' when 'nervous' then E'\nمضطرب — آرام برخورد شود' else '' end;
      end if;
      insert into public.sms_messages (salon_id, to_phone, body, kind, appointment_id, status, scheduled_for)
      values (p_appt.salon_id, v_staff_phone,
              'نوبت جدید: ' || v_who || ' — ' || coalesce(v_service, 'خدمت')
                || E'\n' || public.jalali_label(p_appt.date) || ' ساعت ' || public.fa_clock(p_appt.start_min),
              'staff_new_booking', p_appt.id, 'queued', now());
    end if;
  end if;
end;
$fn$;
revoke all on function public.send_new_booking_messages(public.appointments) from public, anon, authenticated;

-- --------------------------------------------------------- 7. admin --------
-- Starter dog & cat menu for a new pet salon, priced per size. The manager
-- edits prices and durations in the services tab.
create or replace function public.seed_pet_services(p_salon uuid)
returns void
language plpgsql security definer set search_path = public as $fn$
begin
  if exists (select 1 from public.services where salon_id = p_salon) then
    return;
  end if;
  insert into public.services (id, salon_id, name, gender, category, duration_minutes, price, size_pricing)
  select 'svc-' || encode(gen_random_bytes(6), 'hex'), p_salon, s.name, s.species, s.category, s.duration, s.price, s.tiers::jsonb
    from (values
      ('حمام و سشوار', 'dog', 'bath', 60, 450000,
       '{"small":{"price":350000,"duration":45},"medium":{"price":450000,"duration":60},"large":{"price":600000,"duration":90},"giant":{"price":800000,"duration":120}}'),
      ('اصلاح کامل (حمام + کوتاهی + ناخن)', 'dog', 'grooming', 120, 900000,
       '{"small":{"price":700000,"duration":90},"medium":{"price":900000,"duration":120},"large":{"price":1200000,"duration":150},"giant":{"price":1500000,"duration":180}}'),
      ('کوتاهی ناخن', 'dog', 'nails_pet', 15, 150000, '{}'),
      ('تمیز کردن گوش و دندان', 'dog', 'hygiene', 20, 200000, '{}'),
      ('حمام گربه', 'cat', 'bath', 60, 500000,
       '{"small":{"price":450000,"duration":45},"medium":{"price":500000,"duration":60},"large":{"price":600000,"duration":75}}'),
      ('اصلاح کامل گربه', 'cat', 'grooming', 90, 900000,
       '{"small":{"price":800000,"duration":75},"medium":{"price":900000,"duration":90},"large":{"price":1100000,"duration":105}}'),
      ('کوتاهی ناخن گربه', 'cat', 'nails_pet', 15, 150000, '{}')
    ) as s(name, species, category, duration, price, tiers);
end;
$fn$;
revoke all on function public.seed_pet_services(uuid) from public, anon, authenticated;

drop function if exists public.admin_create_salon(text, text, text);
create or replace function public.admin_create_salon(p_slug text, p_name text, p_owner_phone text, p_business_type text default 'beauty')
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_slug text := lower(trim(coalesce(p_slug, ''))); v_id uuid; v_type text := coalesce(nullif(p_business_type, ''), 'beauty');
begin
  if not public.is_platform_admin() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if v_type not in ('beauty', 'pet') then
    return json_build_object('ok', false, 'error', 'نوع سالن نامعتبر است');
  end if;
  if v_slug !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$' then
    return json_build_object('ok', false, 'error', 'آدرس فقط حروف کوچک انگلیسی، عدد و خط تیره');
  end if;
  if v_slug in ('admin', 'feedback', 'book', 'confirm', 'payment', 'reconcile', 'api', 'assets', 'default-new') then
    return json_build_object('ok', false, 'error', 'این آدرس رزرو شده است');
  end if;
  if coalesce(trim(p_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام سالن لازم است');
  end if;
  if coalesce(p_owner_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شمارهٔ موبایل مدیر نامعتبر است');
  end if;
  if exists (select 1 from public.salons where slug = v_slug) then
    return json_build_object('ok', false, 'error', 'این آدرس قبلاً استفاده شده');
  end if;

  insert into public.salons (slug, name, owner_phone, business_type) values (v_slug, trim(p_name), p_owner_phone, v_type)
  returning id into v_id;
  if v_type = 'pet' then
    perform public.seed_pet_services(v_id);
  end if;
  return json_build_object('ok', true, 'id', v_id, 'slug', v_slug);
end;
$fn$;
revoke all on function public.admin_create_salon(text, text, text, text) from public, anon;
grant execute on function public.admin_create_salon(text, text, text, text) to authenticated;

drop function if exists public.admin_update_salon(uuid, text, text, boolean);
create or replace function public.admin_update_salon(p_id uuid, p_name text default null, p_owner_phone text default null,
                                                     p_active boolean default null, p_business_type text default null)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_old text;
begin
  if not public.is_platform_admin() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  if p_owner_phone is not null and p_owner_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شمارهٔ موبایل مدیر نامعتبر است');
  end if;
  select business_type into v_old from public.salons where id = p_id;
  if not found then
    return json_build_object('ok', false, 'error', 'سالن پیدا نشد');
  end if;
  if p_business_type is not null and p_business_type <> v_old then
    if p_business_type not in ('beauty', 'pet') then
      return json_build_object('ok', false, 'error', 'نوع سالن نامعتبر است');
    end if;
    -- Services, staff and bookings are all keyed to the sections of the
    -- type; switching is only safe before the salon is in use.
    if exists (select 1 from public.appointments where salon_id = p_id) then
      return json_build_object('ok', false, 'error', 'این سالن نوبت ثبت‌شده دارد؛ نوع آن قابل تغییر نیست');
    end if;
    delete from public.services where salon_id = p_id and gender <> all (case when p_business_type = 'pet' then array['dog', 'cat'] else array['female', 'male'] end);
  end if;
  update public.salons
     set name = coalesce(nullif(trim(p_name), ''), name),
         owner_phone = coalesce(p_owner_phone, owner_phone),
         active = coalesce(p_active, active),
         business_type = coalesce(p_business_type, business_type)
   where id = p_id;
  if p_business_type = 'pet' and v_old <> 'pet' then
    perform public.seed_pet_services(p_id);
  end if;
  return json_build_object('ok', true);
end;
$fn$;
revoke all on function public.admin_update_salon(uuid, text, text, boolean, text) from public, anon;
grant execute on function public.admin_update_salon(uuid, text, text, boolean, text) to authenticated;

drop function if exists public.admin_list_salons();
create or replace function public.admin_list_salons()
returns table (
  id uuid, slug text, name text, active boolean, owner_phone text, created_at timestamptz, business_type text,
  owner_registered boolean, stylists int, services int,
  bookings_30d int, completed_30d int, last_booking_date date,
  sms_configured boolean, sms_sent_30d int, sms_failed_30d int
)
language sql stable security definer set search_path = public as $fn$
  select s.id, s.slug, s.name, s.active, s.owner_phone, s.created_at, s.business_type,
         exists (select 1 from public.users u where u.salon_id = s.id and u.role in ('owner', 'manager')),
         (select count(*)::int from public.stylists t where t.salon_id = s.id and t.active),
         (select count(*)::int from public.services v where v.salon_id = s.id and v.is_active),
         (select count(*)::int from public.appointments a where a.salon_id = s.id and a.date >= current_date - 30),
         (select count(*)::int from public.appointments a where a.salon_id = s.id and a.date >= current_date - 30 and a.status = 'completed'),
         (select max(a.date) from public.appointments a where a.salon_id = s.id),
         exists (select 1 from public.salon_sms_settings x where x.salon_id = s.id),
         (select count(*)::int from public.sms_messages m where m.salon_id = s.id and m.created_at >= now() - interval '30 days' and m.status in ('sent', 'delivered')),
         (select count(*)::int from public.sms_messages m where m.salon_id = s.id and m.created_at >= now() - interval '30 days' and m.status = 'failed')
    from public.salons s
   where public.is_platform_admin()
   order by s.created_at desc;
$fn$;
revoke all on function public.admin_list_salons() from public, anon;
grant execute on function public.admin_list_salons() to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.45_pet_pricing_rules.sql
-- ============================================================================
-- Migration v2.45 — pet salon pricing rules (run after v2.44)
-- ============================================================================
--  Shaped by a real groomer's price list:
--  1. Breed prices — services.breed_pricing {"چاو چاو": {"price":…, "duration":…}}
--     overrides the size price for that breed (spacing, ZWNJ and Arabic ی/ک
--     don't matter when matching). A service with no base price and only
--     breed prices reads "price announced in salon" for other breeds.
--  2. Size thresholds per salon — app_settings.pet_size_limits (kg upper
--     bounds of small / medium / large; default 5 / 15 / 30).
--  3. Aggression surcharge — app_settings.pet_aggressive_surcharge_percent;
--     a booking for an aggressive animal gets it as an extra charge.
--  4. Extra charges — appointments.extra_charges [{label, amount}], included
--     in final_price. Services marked is_addon (e.g. detangling per half
--     hour) can't be booked online; staff add them when completing a visit.
--  5. New starter menu for pet salons, modelled on that price list.
-- ============================================================================

alter table public.services add column if not exists breed_pricing jsonb not null default '{}'::jsonb;
alter table public.services drop constraint if exists services_breed_pricing_check;
alter table public.services add constraint services_breed_pricing_check check (jsonb_typeof(breed_pricing) = 'object');
alter table public.services add column if not exists is_addon boolean not null default false;

alter table public.app_settings add column if not exists pet_size_limits int[] not null default '{5,15,30}';
alter table public.app_settings drop constraint if exists app_settings_pet_size_limits_check;
alter table public.app_settings add constraint app_settings_pet_size_limits_check check (
  array_length(pet_size_limits, 1) = 3 and pet_size_limits[1] > 0
  and pet_size_limits[1] < pet_size_limits[2] and pet_size_limits[2] < pet_size_limits[3] and pet_size_limits[3] <= 150);
alter table public.app_settings add column if not exists pet_aggressive_surcharge_percent int not null default 0;
alter table public.app_settings drop constraint if exists app_settings_pet_aggressive_surcharge_percent_check;
alter table public.app_settings add constraint app_settings_pet_aggressive_surcharge_percent_check check (pet_aggressive_surcharge_percent between 0 and 100);

alter table public.appointments add column if not exists extra_charges jsonb not null default '[]'::jsonb;
alter table public.appointments drop constraint if exists appointments_extra_charges_check;
alter table public.appointments add constraint appointments_extra_charges_check check (jsonb_typeof(extra_charges) = 'array');

-- "چاو چاو" = "چاوچاو" = "چاو‌چاو"; Arabic ي/ك typed on some keyboards = Persian ی/ک.
create or replace function public.norm_breed(p text)
returns text
language sql immutable as $fn$
  select regexp_replace(translate(lower(coalesce(p, '')), 'يكۀة', 'یکهه'), E'[[:space:]‌‍_-]+', '', 'g');
$fn$;

-- Size price/duration, then the breed's own price/duration on top.
create or replace function public.service_for_pet(p_svc public.services, p_size text, p_breed text)
returns public.services
language plpgsql stable as $fn$
declare v public.services := public.service_at_size(p_svc, p_size); v_key text; v_tier jsonb; v_norm text := public.norm_breed(p_breed);
begin
  if v_norm = '' or p_svc.breed_pricing is null then
    return v;
  end if;
  for v_key, v_tier in select key, value from jsonb_each(p_svc.breed_pricing) loop
    if public.norm_breed(v_key) = v_norm and jsonb_typeof(v_tier) = 'object' then
      if jsonb_typeof(v_tier -> 'price') = 'number' and (v_tier ->> 'price')::numeric >= 0 then
        v.price := round((v_tier ->> 'price')::numeric)::bigint;
      end if;
      if jsonb_typeof(v_tier -> 'duration') = 'number' and (v_tier ->> 'duration')::numeric between 5 and 600 then
        v.duration_minutes := round((v_tier ->> 'duration')::numeric)::int;
      end if;
      exit;
    end if;
  end loop;
  return v;
end;
$fn$;

-- The aggression surcharge for a price (after the service's own discount), or 0.
create or replace function public.pet_surcharge(p_salon uuid, p_temperament text, p_price bigint)
returns bigint
language sql stable security definer set search_path = public as $fn$
  select case when p_temperament = 'aggressive' and p_price is not null and p_price > 0
              then round(p_price * coalesce((select pet_aggressive_surcharge_percent from public.app_settings where salon_id = p_salon), 0) / 100.0)::bigint
              else 0 end;
$fn$;
revoke all on function public.pet_surcharge(uuid, text, bigint) from public, anon, authenticated;

create or replace function public.create_public_booking(
  p_service_id text, p_staff_id text, p_date date, p_start_min int,
  p_customer_name text, p_customer_phone text, p_customer_gender text,
  p_referral_code text default null,
  p_pet jsonb default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_svc public.services; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_salon_id uuid;
  v_status text; v_deposit bigint;
  v_extra bigint := 0; v_extras jsonb := '[]'::jsonb;
  v_type text; v_pet_id uuid; v_pet_name text; v_size text; v_vacc date; v_require_vacc boolean;
begin
  v_salon_id := public.current_salon_id();
  if v_salon_id is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  if p_customer_phone !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  -- v2.32: a returning customer's name is no longer sent to the browser
  -- (customer_loyalty is PII-free for anonymous callers), so an empty name
  -- falls back to the one already on file for this phone.
  if coalesce(trim(p_customer_name), '') = '' then
    select name into p_customer_name from public.customers where salon_id = v_salon_id and phone = p_customer_phone;
  end if;
  if coalesce(trim(p_customer_name), '') = '' then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  -- v2.44: the sections depend on the salon's type (female/male or dog/cat).
  select business_type into v_type from public.salons where id = v_salon_id;
  if p_customer_gender is null or not (p_customer_gender = any (public.salon_sections(v_salon_id))) then
    return json_build_object('ok', false, 'error', case when v_type = 'pet' then 'نوع حیوان نامعتبر است' else 'جنسیت نامعتبر است' end);
  end if;
  if v_type = 'pet' then
    v_pet_name := nullif(trim(coalesce(p_pet ->> 'name', '')), '');
    v_size := p_pet ->> 'size';
    if v_pet_name is null or length(v_pet_name) > 40 then
      return json_build_object('ok', false, 'error', 'نام حیوان را وارد کنید');
    end if;
    if v_size is null or v_size not in ('small', 'medium', 'large', 'giant') then
      return json_build_object('ok', false, 'error', 'جثهٔ حیوان را انتخاب کنید');
    end if;
    if coalesce(p_pet ->> 'temperament', 'calm') not in ('calm', 'nervous', 'aggressive') then
      return json_build_object('ok', false, 'error', 'رفتار حیوان نامعتبر است');
    end if;
    v_vacc := public.try_date(p_pet ->> 'vaccine_valid_until');
  end if;
  if not public.check_rate_limit('create_booking:' || v_salon_id || ':' || p_customer_phone, 10, 30) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست بیش از حد مجاز است — کمی بعد دوباره امتحان کنید');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  select * into v_svc from public.services where id = p_service_id and salon_id = v_salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_svc.is_addon then
    return json_build_object('ok', false, 'error', 'این خدمت فقط در سالن اضافه می‌شود');
  end if;
  if v_svc.gender <> p_customer_gender then
    return json_build_object('ok', false, 'error', case when v_type = 'pet' then 'این خدمت برای این حیوان نیست' else 'این خدمت با جنسیت انتخابی مطابقت ندارد' end);
  end if;
  v_svc := public.service_for_pet(v_svc, v_size, p_pet ->> 'breed'); -- v2.45: size, then breed
  if v_type = 'pet' then
    select pet_require_vaccination into v_require_vacc from public.app_settings where salon_id = v_salon_id;
    if coalesce(v_require_vacc, false) and (v_vacc is null or v_vacc < p_date) then
      return json_build_object('ok', false, 'error', 'این سالن کارت واکسن معتبر تا روز نوبت را لازم می‌داند — تاریخ اعتبار واکسن را وارد کنید');
    end if;
  end if;

  if p_staff_id is not null and not exists (select 1 from public.stylists where id = p_staff_id and salon_id = v_salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = p_staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(p_customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;
  -- v2.45: the salon's aggression surcharge, recorded as an extra charge
  if v_final is not null then
    v_extra := public.pet_surcharge(v_salon_id, case when v_type = 'pet' then coalesce(p_pet ->> 'temperament', 'calm') end, v_after_svc);
    if v_extra > 0 then
      v_extras := jsonb_build_array(jsonb_build_object('label', 'حیوان پرخاشگر', 'amount', v_extra));
      v_final := v_final + v_extra;
    end if;
  end if;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  if v_type = 'pet' then
    v_pet_id := public.upsert_pet(v_salon_id, p_customer_phone, p_customer_gender, p_pet);
  end if;

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price,
      pet_id, pet_name, pet_size, extra_charges
    ) values (
      v_id, v_salon_id, trim(p_customer_name), p_customer_phone, p_customer_gender, p_service_id, p_staff_id,
      coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'pending',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final,
      v_pet_id, v_pet_name, v_size, v_extras
    )
    returning status, deposit_amount into v_status, v_deposit; -- after the auto-confirm / deposit triggers
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  if p_referral_code is not null and length(trim(p_referral_code)) > 0 then
    perform public.apply_referral(p_customer_phone, p_referral_code);
  end if;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = p_staff_id and salon_id = v_salon_id), ''),
    'status', v_status, 'deposit_amount', v_deposit, 'extra_charges', v_extras
  );
end;
$fn$;
grant execute on function public.create_public_booking(text, text, date, int, text, text, text, text, jsonb) to anon, authenticated;

create or replace function public.reschedule_my_booking_with_token(
  p_token text, p_appointment_id text, p_new_date date, p_new_start_min int
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_phone text; v_salon_id uuid; v_appt record; v_svc public.services;
  v_new_end int; v_app_dow int; v_wh record; v_wh_start int; v_wh_end int;
begin
  select r.phone, r.salon_id into v_phone, v_salon_id from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;

  select * into v_appt from public.appointments where id = p_appointment_id;
  if v_appt is null or v_appt.customer_phone <> v_phone or v_appt.salon_id <> v_salon_id then
    return json_build_object('ok', false, 'error', 'این نوبت متعلق به شما نیست');
  end if;
  -- v2.38: only a live booking can move. Without this, a customer could
  -- "reschedule" a cancelled / completed / no-show booking back to life, or
  -- an unpaid deposit hold into a normal booking without paying.
  if v_appt.status not in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed') then
    return json_build_object('ok', false, 'error', 'این نوبت دیگر قابل تغییر نیست');
  end if;
  if p_new_date < public.salon_today() then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_new_date and salon_id = v_salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;

  select * into v_svc from public.services where id = v_appt.service_id and salon_id = v_salon_id;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت مرتبط با این نوبت یافت نشد');
  end if;
  v_svc := public.service_for_pet(v_svc, v_appt.pet_size, (select breed from public.pets where id = v_appt.pet_id)); -- v2.44: pet bookings keep their size's duration
  v_new_end := p_new_start_min + v_svc.duration_minutes;

  v_app_dow := (extract(dow from p_new_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_appt.staff_id and salon_id = v_salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  if p_new_start_min < v_wh_start or v_new_end > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  begin
    update public.appointments
       set date = p_new_date, start_min = p_new_start_min, end_min = v_new_end,
           status = 'rescheduled', pending_date = null, pending_start_min = null, pending_end_min = null
     where id = p_appointment_id;
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.reschedule_my_booking_with_token(text, text, date, int) to anon, authenticated;

create or replace function public.create_booking_from_rebooking_token(
  p_token text, p_date date, p_start_min int, p_staff_id text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_rt record; v_svc public.services; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_staff_id text;
  v_pet_id uuid; v_pet_name text; v_pet_size text; v_pet_breed text; v_pet_temper text;
  v_extra bigint := 0; v_extras jsonb := '[]'::jsonb;
begin
  select * into v_rt from public.rebooking_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
  if v_rt is null then
    return json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است');
  end if;
  if v_rt.service_id is null then
    return json_build_object('ok', false, 'error', 'این لینک برای خدمت مشخصی نیست');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_rt.salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_rt.salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  -- Staff can be the one the customer originally had, or a different one
  -- the customer actively chooses on the booking page — either way it's
  -- just "who performs the service", not an identity field, so it's safe
  -- to accept as a direct parameter (validated against this same salon).
  v_staff_id := coalesce(p_staff_id, v_rt.staff_id);
  select * into v_svc from public.services where id = v_rt.service_id and salon_id = v_rt.salon_id and is_active;
  if v_svc is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  -- v2.44: a pet salon's link books the customer's animal of that species
  -- (most recently groomed first), priced and timed for its size.
  if v_svc.gender in ('dog', 'cat') then
    select p.id, p.name, p.size, p.breed, p.temperament into v_pet_id, v_pet_name, v_pet_size, v_pet_breed, v_pet_temper
      from public.pets p
     where p.salon_id = v_rt.salon_id and p.owner_phone = v_rt.customer_phone and p.species = v_svc.gender
     order by p.last_visit_date desc nulls last, p.created_at desc
     limit 1;
    v_svc := public.service_for_pet(v_svc, v_pet_size, v_pet_breed);
  end if;
  if v_staff_id is not null and not exists (select 1 from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_staff_id and salon_id = v_rt.salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_rt.salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null then
    v_loyalty := public.customer_loyalty(v_rt.customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;
  -- v2.45: the salon's aggression surcharge, recorded as an extra charge
  if v_final is not null then
    v_extra := public.pet_surcharge(v_rt.salon_id, v_pet_temper, v_after_svc);
    if v_extra > 0 then
      v_extras := jsonb_build_array(jsonb_build_object('label', 'حیوان پرخاشگر', 'amount', v_extra));
      v_final := v_final + v_extra;
    end if;
  end if;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  -- v2.38: links the salon itself sent (closure rebooking, waitlist offer,
  -- predictive invitation) never wait for an online deposit — the page
  -- behind them has no payment step. Transaction-local flag read by
  -- hold_for_deposit().
  perform set_config('app.skip_deposit', 'on', true);

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price,
      pet_id, pet_name, pet_size, extra_charges
    ) values (
      v_id, v_rt.salon_id,
      coalesce(nullif(v_rt.customer_name, ''), (select name from public.customers where salon_id = v_rt.salon_id and phone = v_rt.customer_phone), ''),
      v_rt.customer_phone, v_svc.gender, v_rt.service_id, v_staff_id,
      coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'confirmed',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final,
      v_pet_id, v_pet_name, v_pet_size, v_extras
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  update public.rebooking_tokens set used_at = now() where id = v_rt.id;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), '')
  );
end;
$fn$;
grant execute on function public.create_booking_from_rebooking_token(text, date, int, text) to anon, authenticated;

-- ------------------------------------------------ starter pet menu ---------
-- Modelled on a working groomer's price list (toman). Sizes follow the
-- salon's thresholds (default: small under 5 kg). "اصلاح کامل" has no base
-- price — other breeds read "price announced in salon" — and breed prices
-- for Pomeranian and Chow Chow. Detangling is an add-on staff add per half
-- hour when completing the visit.
create or replace function public.seed_pet_services(p_salon uuid)
returns void
language plpgsql security definer set search_path = public as $fn$
begin
  if exists (select 1 from public.services where salon_id = p_salon) then
    return;
  end if;
  insert into public.services (id, salon_id, name, gender, category, duration_minutes, price, size_pricing, breed_pricing, is_addon)
  select 'svc-' || encode(gen_random_bytes(6), 'hex'), p_salon, s.name, s.species, s.category, s.duration, s.price, s.tiers::jsonb, s.breeds::jsonb, s.addon
    from (values
      ('کوتاهی ناخن', 'dog', 'nails_pet', 15, 200000::bigint, '{}', '{}', false),
      ('تخلیهٔ کیسهٔ مقعدی', 'dog', 'hygiene', 15, 200000, '{}', '{}', false),
      ('شستشو (حمام)', 'dog', 'bath', 90, 1800000,
       '{"small":{"price":500000,"duration":45},"medium":{"price":700000,"duration":60},"large":{"price":1800000,"duration":90}}', '{}', false),
      ('اصلاح ساده با موزر', 'dog', 'grooming', 90, 1300000,
       '{"small":{"price":900000,"duration":60},"medium":{"price":900000,"duration":75},"large":{"price":1300000,"duration":90}}', '{}', false),
      ('اصلاح ساده با قیچی', 'dog', 'grooming', 90, 1000000,
       '{"medium":{"price":1000000,"duration":90},"large":{"price":1500000,"duration":120}}', '{}', false),
      ('اصلاح کامل + حمام', 'dog', 'grooming', 150, null,
       '{}', '{"پامرانین":{"price":1900000,"duration":120},"پامر":{"price":1900000,"duration":120},"چاو چاو":{"price":3500000,"duration":180}}', false),
      ('گره‌زدایی (هر نیم ساعت)', 'dog', 'addon', 30, 350000, '{}', '{}', true),
      ('کوتاهی ناخن', 'cat', 'nails_pet', 15, 200000, '{}', '{}', false),
      ('تخلیهٔ کیسهٔ مقعدی', 'cat', 'hygiene', 15, 200000, '{}', '{}', false),
      ('شستشو (حمام) گربه', 'cat', 'bath', 60, 800000, '{}', '{}', false),
      ('شیو سادهٔ گربه', 'cat', 'grooming', 60, 900000, '{}', '{}', false),
      ('گره‌زدایی (هر نیم ساعت)', 'cat', 'addon', 30, 350000, '{}', '{}', true)
    ) as s(name, species, category, duration, price, tiers, breeds, addon);
end;
$fn$;
revoke all on function public.seed_pet_services(uuid) from public, anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.46_pet_quotes.sql
-- ============================================================================
-- Migration v2.46 — price quotes for pet salons (run after v2.45)
-- ============================================================================
--  A groomer prices a visit after seeing what it involves. So:
--   1. The customer sends a request: the animal, the services wanted, a
--      note and a preferred time (request_quote). Customer and manager get
--      an SMS.
--   2. Staff answer from the panel with a price, a duration and optionally
--      the groomer (send_quote) — or decline with a reason.
--   3. The customer gets an SMS with a booking link (a rebooking token tied
--      to the quote) and picks a time; the booking is created at the quoted
--      price and duration. The same quote is in "my dashboard", which can
--      issue a fresh link (my_quote_link).
--  app_settings.pet_quote_mode: 'all' (every pet booking goes through a
--  quote), 'unpriced' (only services with no price for the animal),
--  'off' (direct booking as in v2.44/45).
--  Also: get_available_slots_for_rebooking now uses the same duration as
--  the booking (the animal's size/breed, or the quote) — before, a pet
--  link could offer times its own booking then refused.
-- ============================================================================

alter table public.app_settings add column if not exists pet_quote_mode text not null default 'all';
alter table public.app_settings drop constraint if exists app_settings_pet_quote_mode_check;
alter table public.app_settings add constraint app_settings_pet_quote_mode_check check (pet_quote_mode in ('off', 'unpriced', 'all'));
alter table public.app_settings add column if not exists pet_quote_valid_days int not null default 3;
alter table public.app_settings drop constraint if exists app_settings_pet_quote_valid_days_check;
alter table public.app_settings add constraint app_settings_pet_quote_valid_days_check check (pet_quote_valid_days between 1 and 14);

alter table public.sms_messages drop constraint if exists sms_messages_kind_check;
alter table public.sms_messages add constraint sms_messages_kind_check check (kind in (
  'confirmation', 'reminder', 'cancellation', 'reschedule', 'campaign', 'loyalty', 'custom',
  'reconciliation_prompt', 'weekly_summary', 'predictive_rebooking', 'reschedule_proposed',
  'feedback_request', 'feedback_followup', 'staff_new_booking', 'daily_digest', 'waitlist_offer',
  'staff_change', 'quote_request', 'quote')) not valid;

create table if not exists public.quote_requests (
  id              uuid primary key default gen_random_uuid(),
  salon_id        uuid not null references public.salons (id) on delete cascade,
  customer_phone  text not null check (customer_phone ~ '^09[0-9]{9}$'),
  customer_name   text not null default '',
  pet_id          uuid references public.pets (id) on delete set null,
  pet_name        text not null,
  pet_species     text not null check (pet_species in ('dog', 'cat')),
  pet_size        text check (pet_size is null or pet_size in ('small', 'medium', 'large', 'giant')),
  service_ids     text[] not null check (cardinality(service_ids) between 1 and 6),
  services_label  text not null,
  customer_note   text not null default '' check (length(customer_note) <= 500),
  preferred_time  text not null default '' check (length(preferred_time) <= 100),
  status          text not null default 'pending' check (status in ('pending', 'quoted', 'booked', 'declined', 'cancelled')),
  quoted_price    bigint check (quoted_price is null or quoted_price >= 0),
  quoted_duration int check (quoted_duration is null or quoted_duration between 5 and 600),
  quoted_staff_id text,
  quote_note      text not null default '' check (length(quote_note) <= 300),
  quoted_at       timestamptz,
  expires_at      timestamptz,
  appointment_id  text references public.appointments (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists quote_requests_salon_status_idx on public.quote_requests (salon_id, status, created_at desc);
create index if not exists quote_requests_phone_idx on public.quote_requests (salon_id, customer_phone);

alter table public.quote_requests enable row level security;
revoke all on public.quote_requests from anon, authenticated;
grant select on public.quote_requests to authenticated;
drop policy if exists p_quotes_staff_read on public.quote_requests;
create policy p_quotes_staff_read on public.quote_requests for select
  using ((select public.is_staff()) and salon_id = (select public.current_salon_id()));

alter table public.rebooking_tokens drop constraint if exists rebooking_tokens_reason_check;
alter table public.rebooking_tokens add constraint rebooking_tokens_reason_check check (reason in ('closure', 'predictive', 'manual', 'waitlist', 'quote')) not valid;
alter table public.rebooking_tokens add column if not exists quote_id uuid references public.quote_requests (id) on delete cascade;
alter table public.appointments add column if not exists quote_id uuid references public.quote_requests (id) on delete set null;
alter table public.appointments add column if not exists services_label text;

-- What a rebooking token books: the service (as priced and timed for this
-- customer's animal, or as quoted) and the animal. One place, so the slot
-- list and the booking always agree.
create or replace function public.rebooking_plan(p_rt public.rebooking_tokens,
  out svc public.services, out pet_id uuid, out pet_name text, out pet_size text, out pet_temper text,
  out quote public.quote_requests)
language plpgsql stable security definer set search_path = public as $fn$
declare v_breed text;
begin
  if p_rt.quote_id is not null then
    select * into quote from public.quote_requests where id = p_rt.quote_id and salon_id = p_rt.salon_id;
    select * into svc from public.services where id = p_rt.service_id and salon_id = p_rt.salon_id;
    if quote.id is null or svc.id is null then
      svc := null;
      return;
    end if;
    pet_id := quote.pet_id; pet_name := quote.pet_name; pet_size := quote.pet_size;
    svc.price := quote.quoted_price;
    svc.duration_minutes := quote.quoted_duration;
    svc.discount_type := 'none'; svc.discount_value := 0; svc.discount_reason := '';
    return;
  end if;
  select * into svc from public.services where id = p_rt.service_id and salon_id = p_rt.salon_id and is_active;
  if svc.id is null then
    svc := null;
    return;
  end if;
  if svc.gender in ('dog', 'cat') then
    select p.id, p.name, p.size, p.breed, p.temperament into pet_id, pet_name, pet_size, v_breed, pet_temper
      from public.pets p
     where p.salon_id = p_rt.salon_id and p.owner_phone = p_rt.customer_phone and p.species = svc.gender
     order by p.last_visit_date desc nulls last, p.created_at desc
     limit 1;
    svc := public.service_for_pet(svc, pet_size, v_breed);
  end if;
end;
$fn$;
revoke all on function public.rebooking_plan(public.rebooking_tokens) from public, anon, authenticated;

create or replace function public.resolve_rebooking_token(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_rt public.rebooking_tokens; v_plan record;
begin
  select * into v_rt from public.rebooking_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
  if v_rt.id is null then
    return json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است');
  end if;
  select * into v_plan from public.rebooking_plan(v_rt);
  if v_rt.quote_id is not null and ((v_plan.quote).status is distinct from 'quoted' or (v_plan.quote).expires_at <= now()) then
    return json_build_object('ok', false, 'error', 'این پیشنهاد قیمت دیگر معتبر نیست');
  end if;
  return json_build_object(
    'ok', true,
    'salon_id', v_rt.salon_id,
    'salon_name', (select name from public.salons where id = v_rt.salon_id),
    'salon_slug', (select slug from public.salons where id = v_rt.salon_id),
    'customer_name', v_rt.customer_name,
    'service_id', v_rt.service_id,
    'service_name', coalesce((v_plan.quote).services_label, (v_plan.svc).name),
    'staff_id', v_rt.staff_id,
    'staff_name', (select name from public.stylists where id = v_rt.staff_id and salon_id = v_rt.salon_id),
    'reason', v_rt.reason,
    'preferred_date', v_rt.preferred_date,
    -- v2.46: what the booking will cost and take, and the animal
    'price', (v_plan.svc).price,
    'duration', (v_plan.svc).duration_minutes,
    'pet_name', v_plan.pet_name,
    'quote_note', nullif((v_plan.quote).quote_note, ''),
    'quote_expires_at', (v_plan.quote).expires_at,
    'is_quote', v_rt.quote_id is not null
  );
end;
$fn$;
grant execute on function public.resolve_rebooking_token(text) to anon, authenticated;

create or replace function public.get_available_slots_for_rebooking(p_token text, p_date date, p_staff_id text default null)
returns table (start_min int)
language plpgsql stable security definer set search_path = public as $fn$
declare
  v_rt public.rebooking_tokens; v_plan record; v_svc public.services; v_wh record; v_app_dow int;
  v_wh_start int; v_wh_end int; v_staff_id text; v_step int; v_t int;
begin
  select * into v_rt from public.rebooking_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
  if v_rt.id is null or v_rt.service_id is null then
    return;
  end if;
  if p_date < current_date
     or not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_rt.salon_id)
     or exists (select 1 from public.salon_closures where salon_id = v_rt.salon_id and closure_date = p_date and is_active)
  then
    return;
  end if;
  select * into v_plan from public.rebooking_plan(v_rt);
  v_svc := v_plan.svc;
  if v_svc.id is null then
    return;
  end if;

  v_staff_id := coalesce(p_staff_id, v_rt.staff_id);
  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_staff_id and salon_id = v_rt.salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_rt.salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return;
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  -- every half hour (it used to step by the whole service length, so a
  -- two-hour visit could only start at 9, 11, 13 …)
  v_step := least(greatest(15, v_svc.duration_minutes), 30);

  v_t := v_wh_start;
  while v_t + v_svc.duration_minutes <= v_wh_end loop
    if (p_date > public.salon_today() or v_t > extract(hour from (now() at time zone coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran')))::int * 60
                                              + extract(minute from (now() at time zone coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran')))::int)
       and (v_staff_id is null or not exists (
      select 1 from public.appointments ap
      where ap.salon_id = v_rt.salon_id and ap.staff_id = v_staff_id and ap.date = p_date
        and ap.status in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed', 'awaiting_payment')
        and int4range(ap.start_min, ap.end_min + ap.buffer_minutes) && int4range(v_t, v_t + v_svc.duration_minutes + v_svc.buffer_minutes)
    )) then
      start_min := v_t;
      return next;
    end if;
    v_t := v_t + v_step;
  end loop;
end;
$fn$;
grant execute on function public.get_available_slots_for_rebooking(text, date, text) to anon, authenticated;

create or replace function public.create_booking_from_rebooking_token(
  p_token text, p_date date, p_start_min int, p_staff_id text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_rt public.rebooking_tokens; v_plan record; v_quote public.quote_requests; v_svc public.services; v_wh record; v_app_dow int; v_wh_start int; v_wh_end int;
  v_end_min int; v_id text; v_code text; v_original bigint; v_svc_discount bigint;
  v_after_svc bigint; v_loyalty_pct int := 0; v_final bigint; v_loyalty json; v_code_bytes bytea;
  v_staff_id text;
  v_pet_id uuid; v_pet_name text; v_pet_size text; v_pet_breed text; v_pet_temper text;
  v_extra bigint := 0; v_extras jsonb := '[]'::jsonb;
begin
  select * into v_rt from public.rebooking_tokens
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now();
  if v_rt is null then
    return json_build_object('ok', false, 'error', 'این لینک منقضی یا نامعتبر است');
  end if;
  if v_rt.service_id is null then
    return json_build_object('ok', false, 'error', 'این لینک برای خدمت مشخصی نیست');
  end if;
  if p_date < current_date then
    return json_build_object('ok', false, 'error', 'تاریخ گذشته قابل انتخاب نیست');
  end if;
  if not exists (select 1 from public.approved_dates where date = p_date and salon_id = v_rt.salon_id) then
    return json_build_object('ok', false, 'error', 'این روز برای رزرو باز نشده است');
  end if;
  if exists (select 1 from public.salon_closures where salon_id = v_rt.salon_id and closure_date = p_date and is_active) then
    return json_build_object('ok', false, 'error', 'سالن در این روز تعطیل است');
  end if;

  -- Staff can be the one the customer originally had, or a different one
  -- the customer actively chooses on the booking page — either way it's
  -- just "who performs the service", not an identity field, so it's safe
  -- to accept as a direct parameter (validated against this same salon).
  v_staff_id := coalesce(p_staff_id, v_rt.staff_id);
  -- v2.46: the service as priced/timed for the animal, or as quoted
  select * into v_plan from public.rebooking_plan(v_rt);
  v_svc := v_plan.svc;
  v_quote := v_plan.quote;
  if v_svc.id is null then
    return json_build_object('ok', false, 'error', 'خدمت یافت نشد یا غیرفعال است');
  end if;
  if v_rt.quote_id is not null and (v_quote.status is distinct from 'quoted' or v_quote.expires_at <= now()) then
    return json_build_object('ok', false, 'error', 'این پیشنهاد قیمت دیگر معتبر نیست');
  end if;
  v_pet_id := v_plan.pet_id; v_pet_name := v_plan.pet_name; v_pet_size := v_plan.pet_size; v_pet_temper := v_plan.pet_temper;
  if v_staff_id is not null and not exists (select 1 from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر یافت نشد یا غیرفعال است');
  end if;

  v_app_dow := (extract(dow from p_date)::int + 1) % 7;
  select * into v_wh from public.working_hours
   where day_of_week = v_app_dow and staff_id = v_staff_id and salon_id = v_rt.salon_id;
  if v_wh is null then
    select * into v_wh from public.working_hours
     where day_of_week = v_app_dow and staff_id is null and salon_id = v_rt.salon_id;
  end if;
  if v_wh is null or v_wh.is_closed then
    return json_build_object('ok', false, 'error', 'در این روز سالن یا آرایشگر تعطیل است');
  end if;
  v_wh_start := split_part(v_wh.start_time, ':', 1)::int * 60 + split_part(v_wh.start_time, ':', 2)::int;
  v_wh_end := split_part(v_wh.end_time, ':', 1)::int * 60 + split_part(v_wh.end_time, ':', 2)::int;
  v_end_min := p_start_min + v_svc.duration_minutes;
  if p_start_min < v_wh_start or v_end_min > v_wh_end then
    return json_build_object('ok', false, 'error', 'خارج از ساعات کاری است');
  end if;

  v_original := coalesce(v_svc.price, 0);
  v_svc_discount := case
    when v_svc.discount_type = 'percent' then round(v_original * v_svc.discount_value / 100.0)
    when v_svc.discount_type = 'fixed' then v_svc.discount_value
    else 0
  end;
  v_after_svc := greatest(0, v_original - v_svc_discount);
  if v_svc.price is not null and v_rt.quote_id is null then -- a quoted price is final
    v_loyalty := public.customer_loyalty(v_rt.customer_phone);
    if (v_loyalty->>'found')::boolean then
      v_loyalty_pct := coalesce((v_loyalty->>'discount_percent')::int, 0);
    end if;
  end if;
  v_final := case when v_svc.price is null then null
                  else greatest(0, v_after_svc - round(v_after_svc * v_loyalty_pct / 100.0)) end;
  -- v2.45: the salon's aggression surcharge, recorded as an extra charge
  if v_final is not null then
    v_extra := public.pet_surcharge(v_rt.salon_id, v_pet_temper, v_after_svc);
    if v_extra > 0 then
      v_extras := jsonb_build_array(jsonb_build_object('label', 'حیوان پرخاشگر', 'amount', v_extra));
      v_final := v_final + v_extra;
    end if;
  end if;

  v_id := 'apt-' || substr(md5(gen_random_uuid()::text), 1, 16);
  v_code_bytes := gen_random_bytes(4);
  v_code := 'MN-' || lpad((
    ((get_byte(v_code_bytes, 0)::bigint << 24) | (get_byte(v_code_bytes, 1)::bigint << 16)
     | (get_byte(v_code_bytes, 2)::bigint << 8) | get_byte(v_code_bytes, 3)::bigint) % 90000 + 10000
  )::text, 5, '0');

  -- v2.38: links the salon itself sent (closure rebooking, waitlist offer,
  -- predictive invitation) never wait for an online deposit — the page
  -- behind them has no payment step. Transaction-local flag read by
  -- hold_for_deposit().
  perform set_config('app.skip_deposit', 'on', true);

  begin
    insert into public.appointments (
      id, salon_id, customer_name, customer_phone, customer_gender, service_id, staff_id,
      staff_name, date, start_min, end_min, buffer_minutes, status,
      tracking_code, original_price, discount_type, discount_value, discount_reason, final_price,
      pet_id, pet_name, pet_size, extra_charges, quote_id, services_label
    ) values (
      v_id, v_rt.salon_id,
      coalesce(nullif(v_rt.customer_name, ''), (select name from public.customers where salon_id = v_rt.salon_id and phone = v_rt.customer_phone), ''),
      v_rt.customer_phone, v_svc.gender, v_rt.service_id, v_staff_id,
      coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), ''),
      p_date, p_start_min, v_end_min, v_svc.buffer_minutes, 'confirmed',
      v_code, v_original, v_svc.discount_type, v_svc.discount_value,
      case when v_loyalty_pct > 0 then v_svc.discount_reason || case when v_svc.discount_reason <> '' then ' · ' else '' end || v_loyalty_pct || '٪ تخفیف باشگاه مشتریان' else v_svc.discount_reason end,
      v_final,
      v_pet_id, v_pet_name, v_pet_size, v_extras, v_rt.quote_id, v_quote.services_label
    );
  exception when exclusion_violation then
    return json_build_object('ok', false, 'error', 'این زمان قبلاً رزرو شده — زمان دیگری انتخاب کنید');
  end;

  update public.rebooking_tokens set used_at = now() where id = v_rt.id;
  if v_rt.quote_id is not null then
    update public.quote_requests set status = 'booked', appointment_id = v_id, updated_at = now() where id = v_rt.quote_id;
    update public.rebooking_tokens set used_at = now() where quote_id = v_rt.quote_id and used_at is null;
  end if;

  return json_build_object(
    'ok', true, 'id', v_id, 'tracking_code', v_code, 'final_price', v_final,
    'original_price', v_original, 'staff_name', coalesce((select name from public.stylists where id = v_staff_id and salon_id = v_rt.salon_id), '')
  );
end;
$fn$;
grant execute on function public.create_booking_from_rebooking_token(text, date, int, text) to anon, authenticated;

-- ------------------------------------------------------------ helpers ------
create or replace function public.fa_money(p bigint)
returns text
language sql immutable as $fn$
  select translate(to_char(p, 'FM999,999,999,999'), '0123456789', '۰۱۲۳۴۵۶۷۸۹');
$fn$;

-- ------------------------------------------------- 1. customer request ----
create or replace function public.request_quote(
  p_customer_name text, p_customer_phone text, p_species text, p_pet jsonb,
  p_service_ids text[], p_note text default '', p_preferred_time text default ''
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_salon uuid := public.current_salon_id(); v_type text; v_salon_name text;
  v_pet_name text; v_size text; v_label text; v_count int; v_pet_id uuid; v_id uuid;
  v_ids text[]; v_phone text;
begin
  if v_salon is null then
    return json_build_object('ok', false, 'error', 'سالن نامعتبر است');
  end if;
  select business_type, name into v_type, v_salon_name from public.salons where id = v_salon;
  if v_type is distinct from 'pet' then
    return json_build_object('ok', false, 'error', 'این سالن استعلام قیمت ندارد');
  end if;
  if coalesce(p_customer_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  if coalesce(trim(p_customer_name), '') = '' then
    select name into p_customer_name from public.customers where salon_id = v_salon and phone = p_customer_phone;
  end if;
  if coalesce(trim(p_customer_name), '') = '' or length(p_customer_name) > 80 then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  if p_species is null or p_species not in ('dog', 'cat') then
    return json_build_object('ok', false, 'error', 'نوع حیوان نامعتبر است');
  end if;
  v_pet_name := nullif(trim(coalesce(p_pet ->> 'name', '')), '');
  v_size := p_pet ->> 'size';
  if v_pet_name is null or length(v_pet_name) > 40 then
    return json_build_object('ok', false, 'error', 'نام حیوان را وارد کنید');
  end if;
  if v_size is null or v_size not in ('small', 'medium', 'large', 'giant') then
    return json_build_object('ok', false, 'error', 'جثهٔ حیوان را انتخاب کنید');
  end if;
  if coalesce(p_pet ->> 'temperament', 'calm') not in ('calm', 'nervous', 'aggressive') then
    return json_build_object('ok', false, 'error', 'رفتار حیوان نامعتبر است');
  end if;
  select array_agg(distinct x) into v_ids from unnest(coalesce(p_service_ids, '{}')) x where x is not null;
  if coalesce(cardinality(v_ids), 0) not between 1 and 6 then
    return json_build_object('ok', false, 'error', 'یک تا شش خدمت انتخاب کنید');
  end if;
  select count(*), string_agg(s.name, ' + ' order by s.name) into v_count, v_label
    from public.services s
   where s.salon_id = v_salon and s.id = any (v_ids) and s.is_active and not s.is_addon and s.gender = p_species;
  if v_count <> cardinality(v_ids) then
    return json_build_object('ok', false, 'error', 'خدمت انتخابی یافت نشد');
  end if;
  if length(coalesce(p_note, '')) > 500 or length(coalesce(p_preferred_time, '')) > 100 then
    return json_build_object('ok', false, 'error', 'توضیحات طولانی است');
  end if;
  if not public.check_rate_limit('quote:' || v_salon || ':' || p_customer_phone, 5, 60) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست‌ها زیاد است؛ کمی بعد دوباره تلاش کنید');
  end if;
  if (select count(*) from public.quote_requests
       where salon_id = v_salon and customer_phone = p_customer_phone and status = 'pending') >= 3 then
    return json_build_object('ok', false, 'error', 'سه درخواست شما در انتظار پاسخ سالن است');
  end if;

  v_pet_id := public.upsert_pet(v_salon, p_customer_phone, p_species, p_pet);
  insert into public.quote_requests (salon_id, customer_phone, customer_name, pet_id, pet_name, pet_species, pet_size,
                                     service_ids, services_label, customer_note, preferred_time)
  values (v_salon, p_customer_phone, trim(p_customer_name), v_pet_id, v_pet_name, p_species, v_size,
          v_ids, v_label, trim(coalesce(p_note, '')), trim(coalesce(p_preferred_time, '')))
  returning id into v_id;

  insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
  values (v_salon, p_customer_phone,
          trim(p_customer_name) || ' عزیز، درخواست شما برای ' || v_pet_name || ' (' || v_label || ') در ' || v_salon_name
            || E' ثبت شد.\nقیمت و لینک رزرو به‌زودی برایتان پیامک می‌شود.',
          'quote_request', 'queued', now());
  -- the salon's managers hear about it right away
  for v_phone in
    select distinct u.phone from public.users u
     where u.salon_id = v_salon and u.role in ('owner', 'manager') and u.active is not false and u.phone ~ '^09[0-9]{9}$'
  loop
    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (v_salon, v_phone,
            'درخواست قیمت جدید: ' || v_pet_name || ' (' || case p_species when 'cat' then 'گربه' else 'سگ' end
              || '، ' || public.pet_size_label(v_size) || case when coalesce(p_pet ->> 'breed', '') <> '' then '، ' || left(p_pet ->> 'breed', 40) else '' end
              || ') — ' || v_label || E'\nصاحب: ' || trim(p_customer_name) || ' ' || p_customer_phone || E'\nپاسخ از پنل ← استعلام قیمت',
            'quote_request', 'queued', now());
  end loop;
  return json_build_object('ok', true, 'id', v_id);
end;
$fn$;
revoke all on function public.request_quote(text, text, text, jsonb, text[], text, text) from public;
grant execute on function public.request_quote(text, text, text, jsonb, text[], text, text) to anon, authenticated;

-- ------------------------------------------------------ 2. staff answer ----
create or replace function public.send_quote(p_id uuid, p_price bigint, p_duration int, p_staff_id text default null, p_note text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_q public.quote_requests; v_days int; v_token text; v_link text; v_salon_name text; v_body text;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  select * into v_q from public.quote_requests where id = p_id and salon_id = public.current_salon_id() for update;
  if v_q.id is null then
    return json_build_object('ok', false, 'error', 'درخواست پیدا نشد');
  end if;
  if v_q.status not in ('pending', 'quoted') then
    return json_build_object('ok', false, 'error', 'این درخواست بسته شده است');
  end if;
  if p_price is null or p_price < 1000 then
    return json_build_object('ok', false, 'error', 'قیمت را وارد کنید');
  end if;
  if p_duration is null or p_duration not between 5 and 600 then
    return json_build_object('ok', false, 'error', 'مدت باید بین ۵ تا ۶۰۰ دقیقه باشد');
  end if;
  if p_staff_id is not null and not exists (select 1 from public.stylists where id = p_staff_id and salon_id = v_q.salon_id and active) then
    return json_build_object('ok', false, 'error', 'آرایشگر پیدا نشد');
  end if;
  if length(coalesce(p_note, '')) > 300 then
    return json_build_object('ok', false, 'error', 'توضیح طولانی است');
  end if;
  select coalesce(pet_quote_valid_days, 3) into v_days from public.app_settings where salon_id = v_q.salon_id;

  update public.quote_requests
     set status = 'quoted', quoted_price = p_price, quoted_duration = p_duration, quoted_staff_id = p_staff_id,
         quote_note = trim(coalesce(p_note, '')), quoted_at = now(), expires_at = now() + make_interval(days => coalesce(v_days, 3)),
         updated_at = now()
   where id = p_id
  returning * into v_q;

  -- a new price replaces any link sent before
  update public.rebooking_tokens set used_at = now() where quote_id = p_id and used_at is null;
  v_token := public.create_rebooking_token(v_q.salon_id, v_q.customer_phone, v_q.service_ids[1], p_staff_id, 'quote');
  update public.rebooking_tokens set quote_id = p_id, expires_at = v_q.expires_at, customer_name = v_q.customer_name
   where token_hash = encode(digest(v_token, 'sha256'), 'hex');
  v_link := public.public_link('/book?token=' || v_token);

  select name into v_salon_name from public.salons where id = v_q.salon_id;
  v_body := v_q.customer_name || ' عزیز، قیمت ' || v_q.services_label || ' برای ' || v_q.pet_name || ' در ' || v_salon_name || ': '
            || public.fa_money(p_price) || ' تومان (حدود ' || translate(p_duration::text, '0123456789', '۰۱۲۳۴۵۶۷۸۹') || ' دقیقه).'
            || case when coalesce(trim(p_note), '') <> '' then E'\n' || trim(p_note) else '' end
            || E'\n' || case when v_link is not null then 'انتخاب زمان و رزرو: ' || v_link
                             else 'برای رزرو به «داشبورد من» در صفحهٔ سالن بروید.' end
            || E'\nمعتبر تا ' || public.jalali_label((v_q.expires_at at time zone coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran'))::date);
  insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
  values (v_q.salon_id, v_q.customer_phone, v_body, 'quote', 'queued', now());
  return json_build_object('ok', true, 'expires_at', v_q.expires_at, 'link', v_link);
end;
$fn$;
revoke all on function public.send_quote(uuid, bigint, int, text, text) from public, anon;
grant execute on function public.send_quote(uuid, bigint, int, text, text) to authenticated;

create or replace function public.decline_quote(p_id uuid, p_reason text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_q public.quote_requests; v_salon_name text;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی مجاز نیست');
  end if;
  update public.quote_requests set status = 'declined', quote_note = left(trim(coalesce(p_reason, '')), 300), updated_at = now()
   where id = p_id and salon_id = public.current_salon_id() and status in ('pending', 'quoted')
  returning * into v_q;
  if v_q.id is null then
    return json_build_object('ok', false, 'error', 'درخواست باز پیدا نشد');
  end if;
  update public.rebooking_tokens set used_at = now() where quote_id = p_id and used_at is null;
  select name into v_salon_name from public.salons where id = v_q.salon_id;
  insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
  values (v_q.salon_id, v_q.customer_phone,
          v_q.customer_name || ' عزیز، ' || v_salon_name || ': متاسفانه برای درخواست ' || v_q.pet_name || ' امکان پذیرش نیست.'
            || case when v_q.quote_note <> '' then E'\n' || v_q.quote_note else '' end,
          'quote', 'queued', now());
  return json_build_object('ok', true);
end;
$fn$;
revoke all on function public.decline_quote(uuid, text) from public, anon;
grant execute on function public.decline_quote(uuid, text) to authenticated;

-- --------------------------------------------- 3. customer's dashboard ----
create or replace function public.my_quotes_with_token(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_phone text; v_salon uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return '[]'::json;
  end if;
  return coalesce((
    select json_agg(json_build_object(
             'id', q.id, 'pet_name', q.pet_name, 'pet_species', q.pet_species, 'services_label', q.services_label,
             'status', case when q.status = 'quoted' and q.expires_at <= now() then 'expired' else q.status end,
             'price', q.quoted_price, 'duration', q.quoted_duration, 'note', nullif(q.quote_note, ''),
             'expires_at', q.expires_at, 'created_at', q.created_at, 'appointment_id', q.appointment_id)
           order by q.created_at desc)
      from public.quote_requests q
     where q.salon_id = v_salon and q.customer_phone = v_phone and q.created_at > now() - interval '60 days'), '[]'::json);
end;
$fn$;
grant execute on function public.my_quotes_with_token(text) to anon, authenticated;

-- A fresh booking link for a quoted price (the SMS link may be lost).
create or replace function public.my_quote_link(p_token text, p_quote_id uuid)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_phone text; v_salon uuid; v_q public.quote_requests; v_token text;
begin
  select r.phone, r.salon_id into v_phone, v_salon from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;
  select * into v_q from public.quote_requests where id = p_quote_id and salon_id = v_salon and customer_phone = v_phone;
  if v_q.id is null or v_q.status <> 'quoted' or v_q.expires_at <= now() then
    return json_build_object('ok', false, 'error', 'این پیشنهاد قیمت دیگر معتبر نیست');
  end if;
  update public.rebooking_tokens set used_at = now() where quote_id = v_q.id and used_at is null;
  v_token := public.create_rebooking_token(v_q.salon_id, v_q.customer_phone, v_q.service_ids[1], v_q.quoted_staff_id, 'quote');
  update public.rebooking_tokens set quote_id = v_q.id, expires_at = v_q.expires_at, customer_name = v_q.customer_name
   where token_hash = encode(digest(v_token, 'sha256'), 'hex');
  return json_build_object('ok', true, 'token', v_token);
end;
$fn$;
grant execute on function public.my_quote_link(text, uuid) to anon, authenticated;

create or replace function public.cancel_my_quote(p_token text, p_quote_id uuid)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_phone text; v_salon uuid; v_n int;
begin
  select r.phone, r.salon_id into v_phone, v_salon from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;
  update public.quote_requests set status = 'cancelled', updated_at = now()
   where id = p_quote_id and salon_id = v_salon and customer_phone = v_phone and status in ('pending', 'quoted');
  get diagnostics v_n = row_count;
  if v_n = 0 then
    return json_build_object('ok', false, 'error', 'درخواست باز پیدا نشد');
  end if;
  update public.rebooking_tokens set used_at = now() where quote_id = p_quote_id and used_at is null;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.cancel_my_quote(text, uuid) to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.47_quote_photos.sql
-- ============================================================================
-- Migration v2.47 — photos with price-quote requests (run after v2.46)
-- ============================================================================
--  The customer can attach up to 4 photos of the animal to a quote request
--  so the groomer sees the coat, mats and size before pricing.
--   - Private Storage bucket "quote-photos" (3 MB per file, jpeg/png/webp;
--     the app shrinks photos to ~1600 px JPEG before upload).
--   - Path: <salon_id>/<quote_id>/<random>.jpg. Anyone may upload only
--     into a quote that is still pending and less than 2 hours old, at
--     most 4 files — the quote id (a random uuid only the requester gets
--     back) is the capability.
--   - Only that salon's staff can read them (signed URLs in the panel).
--  If Storage isn't installed (plain Postgres), the bucket and policies are
--  skipped and the rest of the app works unchanged.
-- ============================================================================

create or replace function public.quote_photo_upload_ok(p_name text)
returns boolean
language plpgsql stable security definer set search_path = public as $fn$
declare v_salon text := split_part(coalesce(p_name, ''), '/', 1); v_quote text := split_part(coalesce(p_name, ''), '/', 2);
        v_file text := split_part(coalesce(p_name, ''), '/', 3); v_count int;
begin
  if split_part(p_name, '/', 4) <> ''
     or v_file !~ '^[a-z0-9-]{8,64}\.(jpg|jpeg|png|webp)$'
     or v_salon !~ '^[0-9a-f-]{36}$' or v_quote !~ '^[0-9a-f-]{36}$' then
    return false;
  end if;
  if not exists (select 1 from public.quote_requests q
                  where q.id = v_quote::uuid and q.salon_id = v_salon::uuid
                    and q.status = 'pending' and q.created_at > now() - interval '2 hours') then
    return false;
  end if;
  execute 'select count(*) from storage.objects where bucket_id = $1 and name like $2'
     into v_count using 'quote-photos', v_salon || '/' || v_quote || '/%';
  return v_count < 4;
end;
$fn$;
revoke all on function public.quote_photo_upload_ok(text) from public;
grant execute on function public.quote_photo_upload_ok(text) to anon, authenticated;

do $do$
begin
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    raise notice 'Supabase Storage not found — quote photos are disabled on this database';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('quote-photos', 'quote-photos', false, 3145728, array['image/jpeg', 'image/png', 'image/webp'])
  on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

  execute 'drop policy if exists quote_photos_upload on storage.objects';
  execute $p$create policy quote_photos_upload on storage.objects for insert to anon, authenticated
           with check (bucket_id = 'quote-photos' and public.quote_photo_upload_ok(name))$p$;
  execute 'drop policy if exists quote_photos_staff_read on storage.objects';
  execute $p$create policy quote_photos_staff_read on storage.objects for select to authenticated
           using (bucket_id = 'quote-photos' and public.is_staff()
                  and split_part(name, '/', 1) = public.current_salon_id()::text)$p$;
end
$do$;


-- >>>>>>>>>> supabase/migrations/v2.48_online_shop.sql
-- ============================================================================
-- Migration v2.48 — online shop (run after v2.47)
-- ============================================================================
--  Every salon (beauty or pet) can switch on a small shop next to booking:
--   - shop_settings: on/off, pickup at the salon, shipping (fee, free above,
--     area note), and whether pay-at-delivery is allowed. Online payment uses
--     the salon's own Zarinpal merchant (v2.37); without one the shop falls
--     back to paying at pickup / delivery.
--   - products (+ public Storage bucket "shop-photos" for their pictures,
--     path <salon_id>/<file>, only that salon's managers can write).
--   - orders + order_items. Prices, shipping and stock are computed here,
--     never trusted from the browser. Stock is reserved when the order is
--     placed; an online order unpaid after 20 minutes is cancelled and its
--     stock released (expire_unpaid_orders, cron every 5 minutes).
--   - SMS to the customer and the salon's managers (kinds order /
--     order_staff); the customer follows orders from the dashboard.
-- ============================================================================

-- ---------------------------------------------------------------- settings --
create table if not exists public.shop_settings (
  salon_id           uuid primary key references public.salons (id) on delete cascade default public.current_salon_id(),
  enabled            boolean not null default false,
  pickup_enabled     boolean not null default true,
  pickup_address     text    not null default '' check (length(pickup_address) <= 300),
  shipping_enabled   boolean not null default false,
  shipping_fee       bigint  not null default 0 check (shipping_fee between 0 and 100000000),
  free_shipping_over bigint  not null default 0 check (free_shipping_over between 0 and 10000000000),
  shipping_area      text    not null default '' check (length(shipping_area) <= 200),
  cash_enabled       boolean not null default false,
  note               text    not null default '' check (length(note) <= 300),
  updated_at         timestamptz not null default now()
);
alter table public.shop_settings enable row level security;
drop policy if exists p_shop_settings_mgr on public.shop_settings;
create policy p_shop_settings_mgr on public.shop_settings for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
grant select, insert, update on public.shop_settings to authenticated;

-- ---------------------------------------------------------------- products --
create table if not exists public.products (
  id          uuid primary key default gen_random_uuid(),
  salon_id    uuid not null references public.salons (id) on delete cascade default public.current_salon_id(),
  name        text not null check (length(trim(name)) between 1 and 80),
  description text not null default '' check (length(description) <= 600),
  category    text not null default '' check (length(category) <= 30),
  price       bigint not null check (price between 1000 and 10000000000),
  stock       int check (stock is null or stock between 0 and 100000),   -- null = not tracked
  active      boolean not null default true,
  photo_path  text check (photo_path is null or length(photo_path) <= 200),
  sort_order  int not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists products_salon_idx on public.products (salon_id, active, sort_order);
alter table public.products enable row level security;
drop policy if exists p_products_mgr on public.products;
create policy p_products_mgr on public.products for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
drop policy if exists p_products_staff_read on public.products;
create policy p_products_staff_read on public.products for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select, insert, update, delete on public.products to authenticated;

-- ------------------------------------------------------------------ orders --
create table if not exists public.orders (
  id              uuid primary key default gen_random_uuid(),
  salon_id        uuid not null references public.salons (id) on delete cascade,
  code            text not null,
  customer_name   text not null,
  customer_phone  text not null,
  delivery        text not null check (delivery in ('pickup', 'shipping')),
  address         text not null default '',
  postal_code     text not null default '',
  customer_note   text not null default '',
  subtotal        bigint not null,
  shipping_fee    bigint not null default 0,
  total           bigint not null,
  payment_method  text not null check (payment_method in ('online', 'cash')),
  status          text not null default 'pending'
                  check (status in ('awaiting_payment', 'pending', 'confirmed', 'ready', 'shipped', 'delivered', 'cancelled')),
  paid_at         timestamptz,
  payment_ref     text,
  refund_needed   boolean not null default false,
  staff_note      text not null default '',
  cancel_reason   text not null default '',
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (salon_id, code)
);
create index if not exists orders_salon_idx on public.orders (salon_id, created_at desc);
create index if not exists orders_phone_idx on public.orders (salon_id, customer_phone);
create index if not exists orders_unpaid_idx on public.orders (created_at) where status = 'awaiting_payment';
alter table public.orders enable row level security;
drop policy if exists p_orders_staff_read on public.orders;
create policy p_orders_staff_read on public.orders for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select on public.orders to authenticated;

create table if not exists public.order_items (
  id          uuid primary key default gen_random_uuid(),
  order_id    uuid not null references public.orders (id) on delete cascade,
  salon_id    uuid not null references public.salons (id) on delete cascade,
  product_id  uuid references public.products (id) on delete set null,
  name        text not null,
  unit_price  bigint not null,
  qty         int not null check (qty between 1 and 50)
);
create index if not exists order_items_order_idx on public.order_items (order_id);
alter table public.order_items enable row level security;
drop policy if exists p_order_items_staff_read on public.order_items;
create policy p_order_items_staff_read on public.order_items for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select on public.order_items to authenticated;

-- payments now pay for either a booking deposit or a shop order
alter table public.payments add column if not exists order_id uuid references public.orders (id) on delete cascade;
alter table public.payments alter column appointment_id drop not null;
alter table public.payments drop constraint if exists payments_target_check;
alter table public.payments add constraint payments_target_check
  check ((appointment_id is null) <> (order_id is null)) not valid;
create index if not exists payments_order_idx on public.payments (order_id) where order_id is not null;

-- SMS kinds
alter table public.sms_messages drop constraint if exists sms_messages_kind_check;
alter table public.sms_messages add constraint sms_messages_kind_check check (kind in (
  'confirmation', 'reminder', 'cancellation', 'reschedule', 'campaign', 'loyalty', 'custom',
  'reconciliation_prompt', 'weekly_summary', 'predictive_rebooking', 'reschedule_proposed',
  'feedback_request', 'feedback_followup', 'staff_new_booking', 'daily_digest', 'waitlist_offer',
  'staff_change', 'quote_request', 'quote', 'order', 'order_staff')) not valid;

-- ------------------------------------------------------------- the store ----
-- Everything the storefront needs, in one call. The merchant ID stays private.
create or replace function public.get_shop()
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'enabled', coalesce(ss.enabled, false),
    'pickup', coalesce(ss.pickup_enabled, true) or not coalesce(ss.shipping_enabled, false),
    'pickup_address', coalesce(ss.pickup_address, ''),
    'shipping', coalesce(ss.shipping_enabled, false),
    'shipping_fee', coalesce(ss.shipping_fee, 0),
    'free_shipping_over', coalesce(ss.free_shipping_over, 0),
    'shipping_area', coalesce(ss.shipping_area, ''),
    'note', coalesce(ss.note, ''),
    'online', coalesce(pp.zarinpal_merchant_id, '') <> '',
    'cash', coalesce(ss.cash_enabled, false) or coalesce(pp.zarinpal_merchant_id, '') = '',
    'products', case when coalesce(ss.enabled, false) then coalesce((
      select json_agg(json_build_object(
               'id', p.id, 'name', p.name, 'description', p.description, 'category', p.category,
               'price', p.price, 'stock', p.stock, 'photo_path', p.photo_path)
             order by p.sort_order, p.created_at)
        from public.products p where p.salon_id = c.salon_id and p.active), '[]'::json) else '[]'::json end
  )
  from (select public.current_salon_id() as salon_id) c
  left join public.shop_settings ss on ss.salon_id = c.salon_id
  left join public.salon_payment_settings pp on pp.salon_id = c.salon_id
  where c.salon_id is not null;
$fn$;
grant execute on function public.get_shop() to anon, authenticated;

-- Short human-friendly order number, unique per salon.
create or replace function public.new_order_code(p_salon uuid)
returns text
language plpgsql volatile security definer set search_path = public as $fn$
declare v text;
begin
  loop
    v := (100000 + floor(random() * 900000))::int::text;
    exit when not exists (select 1 from public.orders where salon_id = p_salon and code = v);
  end loop;
  return v;
end;
$fn$;
revoke all on function public.new_order_code(uuid) from public, anon, authenticated;

create or replace function public.order_delivery_label(o public.orders)
returns text
language sql immutable as $fn$
  select case when o.delivery = 'shipping' then 'ارسال به آدرس' else 'تحویل در سالن' end;
$fn$;

-- Text messages for a placed order (cash right away, online after payment).
create or replace function public.notify_new_order(p_order uuid)
returns void
language plpgsql security definer set search_path = public as $fn$
declare o public.orders; v_salon_name text; v_items text; v_count int; v_phone text;
begin
  select * into o from public.orders where id = p_order;
  if o.id is null then return; end if;
  select name into v_salon_name from public.salons where id = o.salon_id;
  select string_agg(i.name || case when i.qty > 1 then ' ×' || i.qty else '' end, '، ' order by i.name), sum(i.qty)
    into v_items, v_count from public.order_items i where i.order_id = o.id;
  insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
  values (o.salon_id, o.customer_phone,
          o.customer_name || ' عزیز، سفارش ' || o.code || ' در ' || v_salon_name || ' ثبت شد'
            || case when o.paid_at is not null then ' و پرداخت شد' else '' end || E'.\n'
            || 'مبلغ: ' || public.fa_money(o.total) || ' تومان — ' || public.order_delivery_label(o)
            || case when o.paid_at is null then ' (پرداخت هنگام تحویل)' else '' end
            || E'\nخبر آماده‌شدن یا ارسال را پیامک می‌کنیم.',
          'order', 'queued', now());
  for v_phone in
    select distinct u.phone from public.users u
     where u.salon_id = o.salon_id and u.role in ('owner', 'manager') and u.active is not false and u.phone ~ '^09[0-9]{9}$'
  loop
    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (o.salon_id, v_phone,
            'سفارش جدید ' || o.code || ': ' || left(v_items, 120) || E'\n'
              || public.fa_money(o.total) || ' تومان، ' || case when o.paid_at is not null then 'پرداخت‌شده' else 'پرداخت هنگام تحویل' end
              || '، ' || public.order_delivery_label(o) || E'\n'
              || o.customer_name || ' ' || o.customer_phone || E'\nپنل ← فروشگاه',
            'order_staff', 'queued', now());
  end loop;
end;
$fn$;
revoke all on function public.notify_new_order(uuid) from public, anon, authenticated;

-- Give reserved stock back (cancel / expiry).
create or replace function public.release_order_stock(p_order uuid)
returns void
language sql security definer set search_path = public as $fn$
  update public.products p set stock = p.stock + x.qty, updated_at = now()
    from (select product_id, sum(qty)::int as qty from public.order_items where order_id = p_order and product_id is not null group by product_id) x
   where p.id = x.product_id and p.stock is not null;
$fn$;
revoke all on function public.release_order_stock(uuid) from public, anon, authenticated;

-- Reserve stock for an order's items again; false (nothing changed) if any is short.
create or replace function public.reserve_order_stock(p_order uuid)
returns boolean
language plpgsql security definer set search_path = public as $fn$
declare r record;
begin
  for r in
    select x.product_id, x.qty, p.stock
      from (select product_id, sum(qty)::int as qty from public.order_items where order_id = p_order and product_id is not null group by product_id) x
      join public.products p on p.id = x.product_id
     order by x.product_id
       for update of p
  loop
    if r.stock is not null and r.stock < r.qty then
      return false;
    end if;
  end loop;
  update public.products p set stock = p.stock - x.qty, updated_at = now()
    from (select product_id, sum(qty)::int as qty from public.order_items where order_id = p_order and product_id is not null group by product_id) x
   where p.id = x.product_id and p.stock is not null;
  return true;
end;
$fn$;
revoke all on function public.reserve_order_stock(uuid) from public, anon, authenticated;

-- Online orders not paid within 20 minutes (must match the payment function).
create or replace function public.expire_unpaid_orders(p_salon uuid default null)
returns int
language plpgsql security definer set search_path = public as $fn$
declare r record; v_n int := 0;
begin
  for r in
    select id from public.orders
     where status = 'awaiting_payment' and created_at < now() - interval '20 minutes'
       and (p_salon is null or salon_id = p_salon)
     order by created_at
     limit 500
       for update skip locked
  loop
    update public.orders set status = 'cancelled', cancel_reason = 'expired', updated_at = now() where id = r.id;
    perform public.release_order_stock(r.id);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$fn$;
revoke all on function public.expire_unpaid_orders(uuid) from public, anon, authenticated;
grant execute on function public.expire_unpaid_orders(uuid) to service_role;

-- ------------------------------------------------------------ place order ---
-- p_items: [{"product_id": "...", "qty": 2}, ...]
create or replace function public.place_order(
  p_customer_name text, p_customer_phone text, p_items jsonb,
  p_delivery text, p_payment text,
  p_address text default '', p_postal_code text default '', p_note text default ''
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_salon uuid := public.current_salon_id();
  v_shop json; v_id uuid; v_code text; v_subtotal bigint := 0; v_fee bigint := 0; v_total bigint;
  v_pids uuid[]; v_qtys int[]; r record; v_lines int := 0;
begin
  if v_salon is null then
    return json_build_object('ok', false, 'error', 'سالن پیدا نشد');
  end if;
  v_shop := public.get_shop();
  if not (v_shop ->> 'enabled')::boolean then
    return json_build_object('ok', false, 'error', 'فروشگاه این سالن فعال نیست');
  end if;
  if coalesce(p_customer_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  p_customer_name := trim(coalesce(p_customer_name, ''));
  if p_customer_name = '' or length(p_customer_name) > 80 then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  if p_delivery = 'pickup' and not (v_shop ->> 'pickup')::boolean
     or p_delivery = 'shipping' and not (v_shop ->> 'shipping')::boolean
     or p_delivery is null or p_delivery not in ('pickup', 'shipping') then
    return json_build_object('ok', false, 'error', 'روش تحویل در دسترس نیست');
  end if;
  if p_payment = 'online' and not (v_shop ->> 'online')::boolean
     or p_payment = 'cash' and not (v_shop ->> 'cash')::boolean
     or p_payment is null or p_payment not in ('online', 'cash') then
    return json_build_object('ok', false, 'error', 'روش پرداخت در دسترس نیست');
  end if;
  p_address := trim(coalesce(p_address, ''));
  p_postal_code := translate(trim(coalesce(p_postal_code, '')), '۰۱۲۳۴۵۶۷۸۹', '0123456789');
  if p_delivery = 'shipping' and length(p_address) < 10 then
    return json_build_object('ok', false, 'error', 'آدرس کامل را وارد کنید');
  end if;
  if length(p_address) > 400 or length(coalesce(p_note, '')) > 400 or p_postal_code !~ '^([0-9]{10})?$' then
    return json_build_object('ok', false, 'error', 'آدرس، کد پستی یا توضیحات نامعتبر است');
  end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 30 then
    return json_build_object('ok', false, 'error', 'سبد خرید خالی است');
  end if;
  if not public.check_rate_limit('order:' || v_salon || ':' || p_customer_phone, 6, 60) then
    return json_build_object('ok', false, 'error', 'تعداد سفارش‌ها زیاد است؛ کمی بعد دوباره تلاش کنید');
  end if;

  perform public.expire_unpaid_orders(v_salon);
  if (select count(*) from public.orders
       where salon_id = v_salon and customer_phone = p_customer_phone and status = 'awaiting_payment') >= 3 then
    return json_build_object('ok', false, 'error', 'چند سفارش پرداخت‌نشده دارید — اول آن‌ها را پرداخت یا لغو کنید');
  end if;

  -- validate lines (merge duplicates) before touching anything
  begin
    select array_agg(pid order by pid), array_agg(qty order by pid) into v_pids, v_qtys
      from (select (e ->> 'product_id')::uuid as pid, sum((e ->> 'qty')::int)::int as qty
              from jsonb_array_elements(p_items) e group by 1) x;
  exception when others then
    return json_build_object('ok', false, 'error', 'سبد خرید نامعتبر است');
  end;
  if array_position(v_pids, null) is not null or exists (select 1 from unnest(v_qtys) q where q is null or q < 1) then
    return json_build_object('ok', false, 'error', 'سبد خرید نامعتبر است');
  end if;
  if exists (select 1 from unnest(v_qtys) q where q > 50) then
    return json_build_object('ok', false, 'error', 'حداکثر ۵۰ عدد از هر کالا');
  end if;

  -- lock the products, check availability and stock, price server-side
  for r in
    select p.id, p.name, p.price, p.stock, p.active, l.qty
      from unnest(v_pids, v_qtys) as l(pid, qty)
      join public.products p on p.id = l.pid and p.salon_id = v_salon
     order by p.id
       for update of p
  loop
    if not r.active then
      return json_build_object('ok', false, 'error', 'یکی از کالاها دیگر موجود نیست — سبد را به‌روز کنید', 'refresh', true);
    end if;
    if r.stock is not null and r.stock < r.qty then
      return json_build_object('ok', false,
        'error', case when r.stock = 0 then '«' || r.name || '» تمام شده است'
                      else 'از «' || r.name || '» فقط ' || r.stock || ' عدد موجود است' end,
        'refresh', true);
    end if;
    v_subtotal := v_subtotal + r.price * r.qty;
    v_lines := v_lines + 1;
  end loop;
  if v_lines <> cardinality(v_pids) then
    return json_build_object('ok', false, 'error', 'یکی از کالاها دیگر موجود نیست — سبد را به‌روز کنید', 'refresh', true);
  end if;

  if p_delivery = 'shipping' then
    v_fee := (v_shop ->> 'shipping_fee')::bigint;
    if (v_shop ->> 'free_shipping_over')::bigint > 0 and v_subtotal >= (v_shop ->> 'free_shipping_over')::bigint then
      v_fee := 0;
    end if;
  end if;
  v_total := v_subtotal + v_fee;
  v_code := public.new_order_code(v_salon);

  insert into public.orders (salon_id, code, customer_name, customer_phone, delivery, address, postal_code, customer_note,
                             subtotal, shipping_fee, total, payment_method, status)
  values (v_salon, v_code, p_customer_name, p_customer_phone, p_delivery,
          case when p_delivery = 'shipping' then p_address else '' end,
          case when p_delivery = 'shipping' then p_postal_code else '' end,
          trim(coalesce(p_note, '')), v_subtotal, v_fee, v_total, p_payment,
          case when p_payment = 'online' then 'awaiting_payment' else 'pending' end)
  returning id into v_id;

  insert into public.order_items (order_id, salon_id, product_id, name, unit_price, qty)
  select v_id, v_salon, p.id, p.name, p.price, l.qty
    from unnest(v_pids, v_qtys) as l(pid, qty) join public.products p on p.id = l.pid;
  update public.products p set stock = p.stock - l.qty, updated_at = now()
    from unnest(v_pids, v_qtys) as l(pid, qty) where p.id = l.pid and p.stock is not null;

  if p_payment = 'cash' then
    perform public.notify_new_order(v_id);
  end if;
  return json_build_object('ok', true, 'id', v_id, 'code', v_code, 'subtotal', v_subtotal,
                           'shipping_fee', v_fee, 'total', v_total, 'status',
                           case when p_payment = 'online' then 'awaiting_payment' else 'pending' end);
end;
$fn$;
grant execute on function public.place_order(text, text, jsonb, text, text, text, text, text) to anon, authenticated;

-- Called by the payment Edge Function (service role) after Zarinpal verify.
-- → 'confirmed' | 'already' | 'refund' (paid, but the order expired and the
--   stock is gone — the salon refunds)
create or replace function public.confirm_order_payment(p_order uuid, p_ref text)
returns text
language plpgsql security definer set search_path = public as $fn$
declare o public.orders;
begin
  select * into o from public.orders where id = p_order for update;
  if o.id is null then return 'refund'; end if;
  if o.paid_at is not null then return 'already'; end if;
  if o.status = 'cancelled' then
    if o.cancel_reason <> 'expired' or not public.reserve_order_stock(o.id) then
      update public.orders set paid_at = now(), payment_ref = p_ref, refund_needed = true, updated_at = now() where id = o.id;
      return 'refund';
    end if;
  elsif o.status <> 'awaiting_payment' then
    update public.orders set paid_at = now(), payment_ref = p_ref, updated_at = now() where id = o.id;
    return 'already';
  end if;
  update public.orders set status = 'pending', cancel_reason = '', paid_at = now(), payment_ref = p_ref, updated_at = now()
   where id = o.id;
  perform public.notify_new_order(o.id);
  return 'confirmed';
end;
$fn$;
revoke all on function public.confirm_order_payment(uuid, text) from public, anon, authenticated;
grant execute on function public.confirm_order_payment(uuid, text) to service_role;

-- ------------------------------------------------------------ staff side ----
create or replace function public.set_order_status(p_order uuid, p_status text, p_note text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare o public.orders; v_salon_name text; v_body text; v_note text := trim(coalesce(p_note, ''));
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  select * into o from public.orders where id = p_order and salon_id = public.current_salon_id() for update;
  if o.id is null then
    return json_build_object('ok', false, 'error', 'سفارش پیدا نشد');
  end if;
  if length(v_note) > 300 then
    return json_build_object('ok', false, 'error', 'توضیح طولانی است');
  end if;
  if o.status in ('delivered', 'cancelled') then
    return json_build_object('ok', false, 'error', 'این سفارش بسته شده است');
  end if;
  if o.status = 'awaiting_payment' and p_status <> 'cancelled' then
    return json_build_object('ok', false, 'error', 'این سفارش هنوز پرداخت نشده');
  end if;
  if p_status not in ('confirmed', 'ready', 'shipped', 'delivered', 'cancelled')
     or p_status = 'ready' and o.delivery <> 'pickup'
     or p_status = 'shipped' and o.delivery <> 'shipping' then
    return json_build_object('ok', false, 'error', 'وضعیت نامعتبر است');
  end if;
  if p_status = 'cancelled' and v_note = '' then
    return json_build_object('ok', false, 'error', 'دلیل لغو را بنویسید');
  end if;

  update public.orders
     set status = p_status, updated_at = now(),
         staff_note = case when p_status <> 'cancelled' and v_note <> '' then v_note else staff_note end,
         cancel_reason = case when p_status = 'cancelled' then v_note else cancel_reason end,
         refund_needed = refund_needed or (p_status = 'cancelled' and paid_at is not null)
   where id = o.id;
  if p_status = 'cancelled' then
    perform public.release_order_stock(o.id);
  end if;

  select name into v_salon_name from public.salons where id = o.salon_id;
  v_body := case p_status
    when 'ready' then o.customer_name || ' عزیز، سفارش ' || o.code || ' آمادهٔ تحویل در ' || v_salon_name || ' است.'
                      || case when o.paid_at is null then E'\nمبلغ قابل پرداخت: ' || public.fa_money(o.total) || ' تومان' else '' end
    when 'shipped' then o.customer_name || ' عزیز، سفارش ' || o.code || ' از ' || v_salon_name || ' ارسال شد.'
    when 'cancelled' then o.customer_name || ' عزیز، سفارش ' || o.code || ' در ' || v_salon_name || ' لغو شد.'
                      || E'\nدلیل: ' || v_note
                      || case when o.paid_at is not null then E'\nمبلغ پرداختی به حسابتان برگردانده می‌شود.' else '' end
    else null end;
  if v_body is not null then
    if p_status <> 'cancelled' and v_note <> '' then
      v_body := v_body || E'\n' || v_note;
    end if;
    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (o.salon_id, o.customer_phone, v_body, 'order', 'queued', now());
  end if;
  return json_build_object('ok', true, 'status', p_status);
end;
$fn$;
grant execute on function public.set_order_status(uuid, text, text) to authenticated;

-- The salon refunded a paid, cancelled order from its Zarinpal panel.
create or replace function public.mark_order_refunded(p_order uuid)
returns json
language plpgsql security definer set search_path = public as $fn$
begin
  if not public.is_manager() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  update public.orders set refund_needed = false, staff_note = trim(staff_note || ' (مبلغ بازگردانده شد)'), updated_at = now()
   where id = p_order and salon_id = public.current_salon_id() and refund_needed;
  return json_build_object('ok', found);
end;
$fn$;
grant execute on function public.mark_order_refunded(uuid) to authenticated;

-- --------------------------------------------------------- customer side ----
create or replace function public.order_json(o public.orders)
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'id', o.id, 'code', o.code, 'status', o.status, 'delivery', o.delivery, 'address', o.address,
    'subtotal', o.subtotal, 'shipping_fee', o.shipping_fee, 'total', o.total,
    'payment_method', o.payment_method, 'paid', o.paid_at is not null, 'refund_needed', o.refund_needed,
    'cancel_reason', nullif(o.cancel_reason, ''), 'staff_note', nullif(o.staff_note, ''), 'created_at', o.created_at,
    'items', coalesce((select json_agg(json_build_object('name', i.name, 'qty', i.qty, 'unit_price', i.unit_price) order by i.name)
                         from public.order_items i where i.order_id = o.id), '[]'::json));
$fn$;
revoke all on function public.order_json(public.orders) from public, anon, authenticated;

create or replace function public.my_orders_with_token(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_phone text; v_salon uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return '[]'::json;
  end if;
  return coalesce((
    select json_agg(public.order_json(o) order by o.created_at desc)
      from public.orders o
     where o.salon_id = v_salon and o.customer_phone = v_phone and o.created_at > now() - interval '120 days'
       and not (o.status = 'cancelled' and o.cancel_reason = 'expired' and o.paid_at is null)), '[]'::json);
end;
$fn$;
grant execute on function public.my_orders_with_token(text) to anon, authenticated;

create or replace function public.cancel_my_order(p_token text, p_order uuid)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_phone text; v_salon uuid; o public.orders; v_phone_mgr text;
begin
  select r.phone, r.salon_id into v_phone, v_salon from public.resolve_booking_token(p_token) r;
  if v_phone is null then
    return json_build_object('ok', false, 'error', 'نشست شما منقضی شده — دوباره وارد شوید');
  end if;
  select * into o from public.orders where id = p_order and salon_id = v_salon and customer_phone = v_phone for update;
  if o.id is null or o.status not in ('awaiting_payment', 'pending') or o.paid_at is not null then
    return json_build_object('ok', false, 'error', 'این سفارش دیگر قابل لغو نیست — با سالن تماس بگیرید');
  end if;
  update public.orders set status = 'cancelled', cancel_reason = 'لغو توسط مشتری', updated_at = now() where id = o.id;
  perform public.release_order_stock(o.id);
  if o.status = 'pending' then
    for v_phone_mgr in
      select distinct u.phone from public.users u
       where u.salon_id = o.salon_id and u.role in ('owner', 'manager') and u.active is not false and u.phone ~ '^09[0-9]{9}$'
    loop
      insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
      values (o.salon_id, v_phone_mgr, 'سفارش ' || o.code || ' را مشتری (' || o.customer_name || ') لغو کرد.', 'order_staff', 'queued', now());
    end loop;
  end if;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.cancel_my_order(text, uuid) to anon, authenticated;

-- ------------------------------------------------------- product photos -----
create or replace function public.shop_photo_write_ok(p_name text)
returns boolean
language sql stable security definer set search_path = public as $fn$
  select public.is_manager()
     and split_part(coalesce(p_name, ''), '/', 1) = public.current_salon_id()::text
     and split_part(p_name, '/', 3) = ''
     and split_part(p_name, '/', 2) ~ '^[a-z0-9-]{8,64}\.(jpg|jpeg|png|webp)$';
$fn$;
revoke all on function public.shop_photo_write_ok(text) from public;
grant execute on function public.shop_photo_write_ok(text) to authenticated;

do $do$
begin
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    raise notice 'Supabase Storage not found — product photos are disabled on this database';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('shop-photos', 'shop-photos', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
  on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

  execute 'drop policy if exists shop_photos_insert on storage.objects';
  execute $p$create policy shop_photos_insert on storage.objects for insert to authenticated
           with check (bucket_id = 'shop-photos' and public.shop_photo_write_ok(name))$p$;
  execute 'drop policy if exists shop_photos_delete on storage.objects';
  execute $p$create policy shop_photos_delete on storage.objects for delete to authenticated
           using (bucket_id = 'shop-photos' and public.shop_photo_write_ok(name))$p$;
end
$do$;


-- >>>>>>>>>> supabase/migrations/v2.49_pet_care.sql
-- ============================================================================
-- Migration v2.49 — pet care extras (run after v2.48)
-- ============================================================================
--   1. Live grooming status (arrived → bathing → grooming → ready); "ready"
--      texts the owner.
--   2. Visit report: before/after photos + a health checklist (fleas, ticks,
--      skin, ears, …) + recommended shop products, sent to the owner as a
--      link (/visit?token=…) and kept in the pet's history.
--   3. Daily reminders: vaccine about to expire, "time for the next groom"
--      (per-pet cycle), pet birthday. Vaccine-card photo on the pet profile.
--   4. Digital consent for risky pets (aggressive / senior), or for all.
--   5. Pick-up & drop-off service with a flat fee.
--   6. Prepaid packages (e.g. 4 baths) sold at the desk, used visit by visit.
--   7. (client) several pets in one visit, back to back.
--   8. (via 2) product recommendations link to the shop.
--   9. (via 3) birthday greeting with the salon's own offer text.
--  10. Capacity: at most N large/giant dogs at the same time.
-- ============================================================================

-- ------------------------------------------------------------------ columns --
alter table public.appointments add column if not exists groom_stage text;
alter table public.appointments drop constraint if exists appointments_groom_stage_check;
alter table public.appointments add constraint appointments_groom_stage_check
  check (groom_stage is null or groom_stage in ('arrived', 'bathing', 'grooming', 'ready'));
alter table public.appointments add column if not exists groom_stage_at timestamptz;
alter table public.appointments add column if not exists transport_address text;
alter table public.appointments add column if not exists transport_fee bigint;
alter table public.appointments add column if not exists package_purchase_id uuid;

alter table public.pets add column if not exists birth_date date;
alter table public.pets add column if not exists groom_every_days int;
alter table public.pets drop constraint if exists pets_groom_every_days_check;
alter table public.pets add constraint pets_groom_every_days_check check (groom_every_days is null or groom_every_days between 7 and 365);
alter table public.pets add column if not exists vaccine_card_path text;
alter table public.pets add column if not exists vaccine_reminded_for date;
alter table public.pets add column if not exists cycle_reminded_for date;
alter table public.pets add column if not exists birthday_reminded_year int;
alter table public.pets add column if not exists consent_at timestamptz;
alter table public.pets add column if not exists consent_text text;

alter table public.app_settings add column if not exists pet_ready_sms boolean not null default true;
alter table public.app_settings add column if not exists pet_reminders_enabled boolean not null default true;
alter table public.app_settings add column if not exists pet_cycle_days int not null default 42;
alter table public.app_settings drop constraint if exists app_settings_pet_cycle_days_check;
alter table public.app_settings add constraint app_settings_pet_cycle_days_check check (pet_cycle_days between 7 and 365);
alter table public.app_settings add column if not exists pet_birthday_message text not null default '';
alter table public.app_settings add column if not exists pet_consent_mode text not null default 'risky';
alter table public.app_settings drop constraint if exists app_settings_pet_consent_mode_check;
alter table public.app_settings add constraint app_settings_pet_consent_mode_check check (pet_consent_mode in ('off', 'risky', 'always'));
alter table public.app_settings add column if not exists pet_consent_text text not null default
  'صحت اطلاعات حیوان را تایید می‌کنم. در صورت گره‌خوردگی شدید، تراشیدن موها و در صورت لزوم استفاده از پوزه‌بند را می‌پذیرم. مسئولیت بیماری‌های پنهان یا حساسیت‌هایی که اعلام نشده‌اند با سالن نیست.';
alter table public.app_settings add column if not exists pet_transport_enabled boolean not null default false;
alter table public.app_settings add column if not exists pet_transport_fee bigint not null default 0;
alter table public.app_settings add column if not exists pet_transport_area text not null default '';
alter table public.app_settings add column if not exists pet_large_capacity int;
alter table public.app_settings drop constraint if exists app_settings_pet_large_capacity_check;
alter table public.app_settings add constraint app_settings_pet_large_capacity_check check (pet_large_capacity is null or pet_large_capacity between 1 and 20);

alter table public.sms_messages drop constraint if exists sms_messages_kind_check;
alter table public.sms_messages add constraint sms_messages_kind_check check (kind in (
  'confirmation', 'reminder', 'cancellation', 'reschedule', 'campaign', 'loyalty', 'custom',
  'reconciliation_prompt', 'weekly_summary', 'predictive_rebooking', 'reschedule_proposed',
  'feedback_request', 'feedback_followup', 'staff_new_booking', 'daily_digest', 'waitlist_offer',
  'staff_change', 'quote_request', 'quote', 'order', 'order_staff',
  'pet_update', 'pet_report', 'pet_reminder', 'pet_package')) not valid;

-- the booking page needs sizes to respect the large-dog capacity
create or replace view public.appointments_public_slots as
  select staff_id, date, start_min, end_min, buffer_minutes, status, pet_size
    from public.appointments
   where salon_id = public.current_salon_id()
     and date >= public.salon_today() - 1;
grant select on public.appointments_public_slots to anon, authenticated;

-- What the booking page needs to know (public, no secrets).
create or replace function public.pet_care_settings()
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'consent_mode', coalesce(s.pet_consent_mode, 'risky'),
    'consent_text', coalesce(s.pet_consent_text, ''),
    'transport_enabled', coalesce(s.pet_transport_enabled, false),
    'transport_fee', coalesce(s.pet_transport_fee, 0),
    'transport_area', coalesce(s.pet_transport_area, ''),
    'large_capacity', s.pet_large_capacity)
  from (select public.current_salon_id() as salon_id) c
  left join public.app_settings s on s.salon_id = c.salon_id
  where c.salon_id is not null;
$fn$;
grant execute on function public.pet_care_settings() to anon, authenticated;

-- ----------------------------------------------- 4/9. pets: birthday, consent --
create or replace function public.upsert_pet(p_salon uuid, p_phone text, p_species text, p_pet jsonb)
returns uuid
language plpgsql security definer set search_path = public as $fn$
declare v_id uuid; v_weight numeric; v_birth date; v_consent_text text;
begin
  if coalesce(p_pet ->> 'weight_kg', '') ~ '^[0-9]{1,3}(\.[0-9]+)?$' then
    v_weight := (p_pet ->> 'weight_kg')::numeric;
    if v_weight <= 0 or v_weight > 150 then v_weight := null; end if;
  end if;
  v_birth := public.try_date(p_pet ->> 'birth_date');
  if v_birth is not null and (v_birth > current_date or v_birth < current_date - interval '35 years') then
    v_birth := null;
  end if;
  if coalesce(p_pet ->> 'consent', '') = 'true' then
    select pet_consent_text into v_consent_text from public.app_settings where salon_id = p_salon;
  end if;
  insert into public.pets as p (salon_id, owner_phone, name, species, breed, size, weight_kg, temperament, vaccine_valid_until, owner_notes,
                                birth_date, consent_at, consent_text)
  values (p_salon, p_phone, trim(p_pet ->> 'name'), p_species,
          left(trim(coalesce(p_pet ->> 'breed', '')), 40),
          p_pet ->> 'size', v_weight,
          coalesce(nullif(p_pet ->> 'temperament', ''), 'calm'),
          public.try_date(p_pet ->> 'vaccine_valid_until'),
          left(trim(coalesce(p_pet ->> 'notes', '')), 300),
          v_birth,
          case when v_consent_text is not null then now() end, v_consent_text)
  on conflict (salon_id, owner_phone, species, lower(name)) do update
     set breed               = coalesce(nullif(excluded.breed, ''), p.breed),
         size                = excluded.size,
         weight_kg           = coalesce(excluded.weight_kg, p.weight_kg),
         temperament         = case when p_pet ? 'temperament' then excluded.temperament else p.temperament end,
         vaccine_valid_until = coalesce(excluded.vaccine_valid_until, p.vaccine_valid_until),
         owner_notes         = coalesce(nullif(excluded.owner_notes, ''), p.owner_notes),
         birth_date          = coalesce(excluded.birth_date, p.birth_date),
         consent_at          = coalesce(excluded.consent_at, p.consent_at),
         consent_text        = coalesce(excluded.consent_text, p.consent_text)
  returning id into v_id;
  return v_id;
end;
$fn$;
revoke all on function public.upsert_pet(uuid, text, text, jsonb) from public, anon, authenticated;

-- ------------------------------------------------------ 1. grooming status --
create or replace function public.set_groom_stage(p_appt text, p_stage text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare a public.appointments; v_send boolean; v_salon_name text;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  if p_stage is not null and p_stage not in ('arrived', 'bathing', 'grooming', 'ready') then
    return json_build_object('ok', false, 'error', 'مرحلهٔ نامعتبر');
  end if;
  select * into a from public.appointments where id = p_appt and salon_id = public.current_salon_id() for update;
  if a.id is null or not (public.is_manager() or a.staff_id = public.my_stylist_id()) then
    return json_build_object('ok', false, 'error', 'نوبت پیدا نشد');
  end if;
  if a.status in ('cancelled', 'no_show') then
    return json_build_object('ok', false, 'error', 'این نوبت لغو شده است');
  end if;
  update public.appointments set groom_stage = p_stage, groom_stage_at = now() where id = a.id;
  select coalesce(s.pet_ready_sms, true), sa.name into v_send, v_salon_name
    from public.salons sa left join public.app_settings s on s.salon_id = sa.id where sa.id = a.salon_id;
  if p_stage = 'ready' and a.groom_stage is distinct from 'ready' and v_send and a.customer_phone ~ '^09[0-9]{9}$' then
    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (a.salon_id, a.customer_phone,
            coalesce(nullif(a.pet_name, ''), 'حیوان شما') || ' آمادهٔ تحویل است 🐾' || E'\n' || v_salon_name
              || case when a.transport_address is not null then E'\nبه‌زودی به آدرس شما آورده می‌شود.' else '' end,
            'pet_update', 'queued', now());
  end if;
  return json_build_object('ok', true, 'stage', p_stage);
end;
$fn$;
grant execute on function public.set_groom_stage(text, text) to authenticated;

-- ------------------------------------------- 2/8. visit report + photos --
create table if not exists public.pet_visit_reports (
  appointment_id text primary key references public.appointments (id) on delete cascade,
  salon_id       uuid not null references public.salons (id) on delete cascade,
  pet_id         uuid references public.pets (id) on delete set null,
  checks         jsonb not null default '{}'::jsonb,
  note           text not null default '' check (length(note) <= 600),
  photos         text[] not null default '{}' check (cardinality(photos) <= 8),
  product_ids    uuid[] not null default '{}' check (cardinality(product_ids) <= 4),
  token_hash     text unique,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  sent_at        timestamptz
);
create index if not exists pet_visit_reports_pet_idx on public.pet_visit_reports (pet_id, created_at desc);
alter table public.pet_visit_reports enable row level security;
drop policy if exists p_visit_reports_staff on public.pet_visit_reports;
create policy p_visit_reports_staff on public.pet_visit_reports for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select on public.pet_visit_reports to authenticated;

-- checks: {"fleas": bool, "ticks": bool, "skin": bool, "ears": bool, "eyes": bool,
--          "teeth": bool, "matting": bool, "nails": bool, "behavior": "calm|nervous|aggressive"}
create or replace function public.save_visit_report(
  p_appt text, p_checks jsonb, p_note text default '', p_photos text[] default '{}',
  p_product_ids uuid[] default '{}', p_send boolean default false
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare a public.appointments; v_checks jsonb := '{}'::jsonb; k text; v_token text; v_link text; v_salon_name text;
        v_photos text[]; v_products uuid[]; v_already timestamptz;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  select * into a from public.appointments where id = p_appt and salon_id = public.current_salon_id();
  if a.id is null or not (public.is_manager() or a.staff_id = public.my_stylist_id()) then
    return json_build_object('ok', false, 'error', 'نوبت پیدا نشد');
  end if;
  foreach k in array array['fleas', 'ticks', 'skin', 'ears', 'eyes', 'teeth', 'matting', 'nails'] loop
    if coalesce(p_checks ->> k, '') = 'true' then v_checks := v_checks || jsonb_build_object(k, true); end if;
  end loop;
  if coalesce(p_checks ->> 'behavior', '') in ('calm', 'nervous', 'aggressive') then
    v_checks := v_checks || jsonb_build_object('behavior', p_checks ->> 'behavior');
  end if;
  if length(coalesce(p_note, '')) > 600 then
    return json_build_object('ok', false, 'error', 'یادداشت طولانی است');
  end if;
  -- only photos of this visit, uploaded to this salon's folder
  select coalesce(array_agg(x), '{}') into v_photos
    from unnest(coalesce(p_photos, '{}')) x
   where x ~ ('^' || a.salon_id || '/' || a.id || '/(before|after)-[a-z0-9-]{8,64}\.(jpg|jpeg|png|webp)$');
  if cardinality(v_photos) > 8 then
    return json_build_object('ok', false, 'error', 'حداکثر ۸ عکس');
  end if;
  select coalesce(array_agg(p.id), '{}') into v_products
    from public.products p where p.id = any (coalesce(p_product_ids, '{}')) and p.salon_id = a.salon_id and p.active;
  if cardinality(v_products) > 4 then
    return json_build_object('ok', false, 'error', 'حداکثر ۴ محصول پیشنهادی');
  end if;

  select sent_at into v_already from public.pet_visit_reports where appointment_id = a.id;
  insert into public.pet_visit_reports as r (appointment_id, salon_id, pet_id, checks, note, photos, product_ids)
  values (a.id, a.salon_id, a.pet_id, v_checks, trim(coalesce(p_note, '')), v_photos, v_products)
  on conflict (appointment_id) do update
     set checks = excluded.checks, note = excluded.note, photos = excluded.photos,
         product_ids = excluded.product_ids, updated_at = now();

  -- the groomer's behaviour note keeps the pet profile current
  if a.pet_id is not null and v_checks ? 'behavior' then
    update public.pets set temperament = v_checks ->> 'behavior', updated_at = now() where id = a.pet_id;
  end if;

  if p_send and a.customer_phone ~ '^09[0-9]{9}$' then
    v_token := encode(gen_random_bytes(18), 'hex');
    update public.pet_visit_reports set token_hash = encode(digest(v_token, 'sha256'), 'hex'), sent_at = now()
     where appointment_id = a.id;
    v_link := public.public_link('/visit?token=' || v_token);
    select name into v_salon_name from public.salons where id = a.salon_id;
    if v_link is not null then
      insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
      values (a.salon_id, a.customer_phone,
              'گزارش آرایش ' || coalesce(nullif(a.pet_name, ''), 'حیوان شما') || ' در ' || v_salon_name
                || case when cardinality(v_photos) > 0 then ' (با عکس قبل و بعد)' else '' end || E':\n' || v_link,
              'pet_report', 'queued', now());
    end if;
    return json_build_object('ok', true, 'sent', v_link is not null, 'link', v_link, 'resent', v_already is not null);
  end if;
  return json_build_object('ok', true, 'sent', false);
end;
$fn$;
grant execute on function public.save_visit_report(text, jsonb, text, text[], uuid[], boolean) to authenticated;

-- The owner's report page (anyone holding the link; valid 180 days).
create or replace function public.get_visit_report(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare r public.pet_visit_reports; a public.appointments;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{36}$' then
    return json_build_object('ok', false);
  end if;
  select * into r from public.pet_visit_reports where token_hash = encode(digest(p_token, 'sha256'), 'hex')
     and sent_at > now() - interval '180 days';
  if r.appointment_id is null then
    return json_build_object('ok', false);
  end if;
  select * into a from public.appointments where id = r.appointment_id;
  return json_build_object(
    'ok', true,
    'salon_name', (select name from public.salons where id = r.salon_id),
    'salon_slug', (select slug from public.salons where id = r.salon_id),
    'pet_name', a.pet_name, 'date', a.date, 'services_label', a.services_label,
    'checks', r.checks, 'note', nullif(r.note, ''), 'photos', r.photos,
    'products', coalesce((select json_agg(json_build_object('id', p.id, 'name', p.name, 'price', p.price, 'photo_path', p.photo_path))
                            from public.products p
                            join public.shop_settings ss on ss.salon_id = p.salon_id and ss.enabled
                           where p.id = any (r.product_ids) and p.active), '[]'::json));
end;
$fn$;
grant execute on function public.get_visit_report(text) to anon, authenticated;

-- Customer dashboard: the reports of their pets.
create or replace function public.my_visit_reports_with_token(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_phone text; v_salon uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon from public.resolve_booking_token(p_token) r;
  if v_phone is null then return '[]'::json; end if;
  return coalesce((
    select json_agg(json_build_object('appointment_id', r.appointment_id, 'pet_name', a.pet_name, 'date', a.date,
                                      'checks', r.checks, 'note', nullif(r.note, ''), 'photos', r.photos)
                    order by a.date desc)
      from public.pet_visit_reports r join public.appointments a on a.id = r.appointment_id
     where r.salon_id = v_salon and a.customer_phone = v_phone and r.sent_at is not null
       and r.sent_at > now() - interval '365 days'), '[]'::json);
end;
$fn$;
grant execute on function public.my_visit_reports_with_token(text) to anon, authenticated;

-- Photos: public bucket, unguessable file names, only this salon's staff write.
create or replace function public.pet_photo_write_ok(p_name text)
returns boolean
language plpgsql stable security definer set search_path = public as $fn$
declare v_salon text := split_part(coalesce(p_name, ''), '/', 1); v_folder text := split_part(coalesce(p_name, ''), '/', 2);
        v_file text := split_part(coalesce(p_name, ''), '/', 3);
begin
  if not public.is_staff() or v_salon <> coalesce(public.current_salon_id()::text, '-') or split_part(p_name, '/', 4) <> '' then
    return false;
  end if;
  if v_folder = 'vaccine' then
    return v_file ~ '^[a-z0-9-]{8,64}\.(jpg|jpeg|png|webp)$';
  end if;
  return v_file ~ '^(before|after)-[a-z0-9-]{8,64}\.(jpg|jpeg|png|webp)$'
     and exists (select 1 from public.appointments a
                  where a.id = v_folder and a.salon_id = v_salon::uuid
                    and (public.is_manager() or a.staff_id = public.my_stylist_id()));
end;
$fn$;
revoke all on function public.pet_photo_write_ok(text) from public;
grant execute on function public.pet_photo_write_ok(text) to authenticated;

do $do$
begin
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    raise notice 'Supabase Storage not found — pet photos are disabled on this database';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('pet-photos', 'pet-photos', true, 3145728, array['image/jpeg', 'image/png', 'image/webp'])
  on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  execute 'drop policy if exists pet_photos_insert on storage.objects';
  execute $p$create policy pet_photos_insert on storage.objects for insert to authenticated
           with check (bucket_id = 'pet-photos' and public.pet_photo_write_ok(name))$p$;
  execute 'drop policy if exists pet_photos_delete on storage.objects';
  execute $p$create policy pet_photos_delete on storage.objects for delete to authenticated
           using (bucket_id = 'pet-photos' and public.pet_photo_write_ok(name))$p$;
end
$do$;

-- --------------------------------------------- 3/9. daily care reminders --
create or replace function public.pet_care_reminders()
returns int
language plpgsql security definer set search_path = public as $fn$
declare r record; v_n int := 0; v_today date; v_link text; v_tz text;
begin
  for r in
    select p.*, sa.name as salon_name, sa.slug, coalesce(s.pet_cycle_days, 42) as cycle_days,
           coalesce(s.pet_birthday_message, '') as birthday_message, public.salon_today() as today
      from public.pets p
      join public.salons sa on sa.id = p.salon_id and sa.active and sa.business_type = 'pet'
      left join public.app_settings s on s.salon_id = p.salon_id
     where coalesce(s.pet_reminders_enabled, true)
       and (p.vaccine_valid_until is not null or p.last_visit_date is not null or p.birth_date is not null)
     limit 20000
  loop
    v_today := r.today;
    -- vaccine expires within a week (once per expiry date)
    if r.vaccine_valid_until between v_today and v_today + 7 and r.vaccine_reminded_for is distinct from r.vaccine_valid_until then
      insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
      values (r.salon_id, r.owner_phone,
              'یادآوری ' || r.salon_name || ': اعتبار واکسن ' || r.name || ' تا ' || public.jalali_label(r.vaccine_valid_until)
                || ' است. لطفاً برای تمدید آن اقدام کنید 💉',
              'pet_reminder', 'queued', now());
      update public.pets set vaccine_reminded_for = r.vaccine_valid_until where id = r.id;
      v_n := v_n + 1;
    end if;
    -- next groom due (once per visit), unless already booked or nudged recently
    if r.last_visit_date is not null
       and r.last_visit_date + coalesce(r.groom_every_days, r.cycle_days) between v_today - 6 and v_today
       and r.cycle_reminded_for is distinct from r.last_visit_date
       and not exists (select 1 from public.appointments a
                        where a.salon_id = r.salon_id and a.customer_phone = r.owner_phone and a.date >= v_today
                          and a.status in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed', 'awaiting_payment'))
       and not exists (select 1 from public.sms_messages m
                        where m.salon_id = r.salon_id and m.to_phone = r.owner_phone
                          and m.created_at > now() - interval '5 days'
                          and (m.kind = 'predictive_rebooking' or (m.kind = 'pet_reminder' and m.body like '%وقت آرایش%'))) then
      v_link := public.public_link('/' || r.slug);
      insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
      values (r.salon_id, r.owner_phone,
              'وقت آرایش ' || r.name || ' رسیده 🐾 از آخرین نوبت ' || public.fa_digits((v_today - r.last_visit_date)::text) || ' روز گذشته.'
                || case when v_link is not null then E'\nرزرو: ' || v_link else '' end || E'\n' || r.salon_name,
              'pet_reminder', 'queued', now());
      update public.pets set cycle_reminded_for = r.last_visit_date where id = r.id;
      v_n := v_n + 1;
    end if;
    -- birthday
    if r.birth_date is not null and to_char(r.birth_date, 'MM-DD') = to_char(v_today, 'MM-DD')
       and r.birthday_reminded_year is distinct from extract(year from v_today)::int then
      insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
      values (r.salon_id, r.owner_phone,
              'تولد ' || r.name || ' مبارک! 🎂🐾' || case when r.birthday_message <> '' then E'\n' || left(r.birthday_message, 200) else '' end
                || E'\n' || r.salon_name,
              'pet_reminder', 'queued', now());
      update public.pets set birthday_reminded_year = extract(year from v_today)::int where id = r.id;
      v_n := v_n + 1;
    end if;
  end loop;
  return v_n;
end;
$fn$;
revoke all on function public.pet_care_reminders() from public, anon, authenticated;
grant execute on function public.pet_care_reminders() to service_role;

-- ------------------------------------------------- 5. pick-up & drop-off --
-- The appointment update guard (v2.24) blocks price changes by customers and stylists. A
-- server function that computed the price itself marks its own transaction
-- as trusted (not reachable from the API: set_config isn't exposed).
-- v2.49: at "انجام شد" a groomer may add add-on charges (v2.45) — the price
-- may grow by exactly the charges appended, or be set when it was decided
-- in the salon. Lowering a price stays a manager's job.
create or replace function public.stylist_checkout_ok(o public.appointments, n public.appointments)
returns boolean
language sql immutable as $fn$
  select n.status = 'completed'
     and coalesce(n.extra_charges, '[]'::jsonb) @> coalesce(o.extra_charges, '[]'::jsonb)
     and n.final_price is not null
     and (
       (o.final_price is null and n.final_price >= 0)
       or n.final_price - o.final_price =
            coalesce((select sum((x ->> 'amount')::bigint) from jsonb_array_elements(coalesce(n.extra_charges, '[]'::jsonb)) x), 0)
          - coalesce((select sum((x ->> 'amount')::bigint) from jsonb_array_elements(coalesce(o.extra_charges, '[]'::jsonb)) x), 0)
     )
     and jsonb_array_length(coalesce(n.extra_charges, '[]'::jsonb)) >= jsonb_array_length(coalesce(o.extra_charges, '[]'::jsonb));
$fn$;

create or replace function public.guard_anonymous_appt_update() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  -- v2.49: a server function that computed the change itself marks its own
  -- transaction as trusted (set_config is not reachable from the API).
  if coalesce(current_setting('app.trusted_rpc', true), '') = 'on' then
    return new;
  end if;
  if auth.uid() is null then
    if new.customer_phone is distinct from old.customer_phone
       or new.customer_name is distinct from old.customer_name
       or new.staff_id is distinct from old.staff_id
       or new.service_id is distinct from old.service_id
       or new.final_price is distinct from old.final_price
       or new.original_price is distinct from old.original_price
       or new.discount_type is distinct from old.discount_type
       or new.discount_value is distinct from old.discount_value
       or new.referral_verified is distinct from old.referral_verified then
      raise exception 'این تغییر برای مشتری مجاز نیست — فقط لغو یا جابه‌جایی زمان مجاز است';
    end if;
    insert into public.audit_log (salon_id, event, actor, detail) values (
      new.salon_id, 'appointment_self_update', null,
      jsonb_build_object('appointment_id', new.id, 'from_status', old.status, 'to_status', new.status)
    );
  elsif public.my_role() = 'stylist' and not public.is_manager() then
    if new.customer_phone is distinct from old.customer_phone
       or new.customer_name is distinct from old.customer_name
       or new.staff_id is distinct from old.staff_id
       or new.service_id is distinct from old.service_id
       or (new.final_price is distinct from old.final_price and not public.stylist_checkout_ok(old, new))
       or new.original_price is distinct from old.original_price
       or new.discount_type is distinct from old.discount_type
       or new.discount_value is distinct from old.discount_value then
      raise exception 'این تغییر خارج از اختیار آرایشگر است';
    end if;
  end if;
  return new;
end;
$fn$;

-- Called right after booking by the same browser: the booking id (random,
-- only returned to the booker) plus the phone prove it is theirs.
create or replace function public.request_pet_transport(p_appt text, p_phone text, p_address text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare a public.appointments; v_enabled boolean; v_fee bigint;
begin
  select coalesce(pet_transport_enabled, false), coalesce(pet_transport_fee, 0) into v_enabled, v_fee
    from public.app_settings where salon_id = public.current_salon_id();
  if not coalesce(v_enabled, false) then
    return json_build_object('ok', false, 'error', 'سرویس رفت‌وبرگشت فعال نیست');
  end if;
  if length(trim(coalesce(p_address, ''))) < 10 or length(p_address) > 300 then
    return json_build_object('ok', false, 'error', 'آدرس کامل را وارد کنید');
  end if;
  select * into a from public.appointments
   where id = p_appt and salon_id = public.current_salon_id() and customer_phone = p_phone for update;
  if a.id is null or a.created_at < now() - interval '30 minutes' or a.transport_address is not null
     or a.status in ('cancelled', 'no_show') or a.pet_id is null then
    return json_build_object('ok', false, 'error', 'امکان افزودن سرویس به این نوبت نیست');
  end if;
  perform set_config('app.trusted_rpc', 'on', true);
  update public.appointments
     set transport_address = trim(p_address), transport_fee = v_fee,
         extra_charges = case when v_fee > 0 then coalesce(extra_charges, '[]'::jsonb)
                                 || jsonb_build_array(jsonb_build_object('label', 'سرویس رفت‌وبرگشت', 'amount', v_fee))
                              else extra_charges end,
         final_price = case when final_price is not null then final_price + v_fee else final_price end
   where id = a.id;
  perform set_config('app.trusted_rpc', '', true);
  return json_build_object('ok', true, 'fee', v_fee);
end;
$fn$;
grant execute on function public.request_pet_transport(text, text, text) to anon, authenticated;

-- ----------------------------------------------------------- 6. packages --
create table if not exists public.pet_packages (
  id          uuid primary key default gen_random_uuid(),
  salon_id    uuid not null default public.current_salon_id() references public.salons (id) on delete cascade,
  name        text not null check (length(trim(name)) between 1 and 60),
  service_id  text not null references public.services (id) on delete cascade,
  sessions    int not null check (sessions between 2 and 50),
  price       bigint not null check (price between 1000 and 10000000000),
  valid_days  int not null default 180 check (valid_days between 14 and 730),
  active      boolean not null default true,
  created_at  timestamptz not null default now()
);
alter table public.pet_packages enable row level security;
drop policy if exists p_pet_packages_mgr on public.pet_packages;
create policy p_pet_packages_mgr on public.pet_packages for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
drop policy if exists p_pet_packages_staff_read on public.pet_packages;
create policy p_pet_packages_staff_read on public.pet_packages for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select, insert, update, delete on public.pet_packages to authenticated;

create table if not exists public.package_purchases (
  id              uuid primary key default gen_random_uuid(),
  salon_id        uuid not null references public.salons (id) on delete cascade,
  package_id      uuid references public.pet_packages (id) on delete set null,
  package_name    text not null,
  service_id      text not null,
  customer_phone  text not null check (customer_phone ~ '^09[0-9]{9}$'),
  customer_name   text not null default '',
  sessions_total  int not null,
  sessions_left   int not null check (sessions_left >= 0),
  price_paid      bigint not null,
  expires_at      date not null,
  created_at      timestamptz not null default now()
);
create index if not exists package_purchases_phone_idx on public.package_purchases (salon_id, customer_phone);
alter table public.package_purchases enable row level security;
drop policy if exists p_package_purchases_staff on public.package_purchases;
create policy p_package_purchases_staff on public.package_purchases for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select on public.package_purchases to authenticated;
alter table public.appointments drop constraint if exists appointments_package_purchase_fk;
alter table public.appointments add constraint appointments_package_purchase_fk
  foreign key (package_purchase_id) references public.package_purchases (id) on delete set null;

-- Public: packages on offer (shown on the booking page).
create or replace function public.get_pet_packages()
returns json
language sql stable security definer set search_path = public as $fn$
  select coalesce(json_agg(json_build_object('id', k.id, 'name', k.name, 'service_name', s.name, 'sessions', k.sessions,
                                             'price', k.price, 'valid_days', k.valid_days, 'single_price', s.price)
                           order by k.price), '[]'::json)
    from public.pet_packages k join public.services s on s.id = k.service_id
   where k.salon_id = public.current_salon_id() and k.active;
$fn$;
grant execute on function public.get_pet_packages() to anon, authenticated;

create or replace function public.sell_package(p_package uuid, p_phone text, p_name text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare k public.pet_packages; v_id uuid; v_salon_name text; v_exp date;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  if coalesce(p_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  select * into k from public.pet_packages where id = p_package and salon_id = public.current_salon_id() and active;
  if k.id is null then
    return json_build_object('ok', false, 'error', 'بسته پیدا نشد');
  end if;
  v_exp := public.salon_today() + k.valid_days;
  insert into public.package_purchases (salon_id, package_id, package_name, service_id, customer_phone, customer_name,
                                        sessions_total, sessions_left, price_paid, expires_at)
  values (k.salon_id, k.id, k.name, k.service_id, p_phone, left(trim(coalesce(p_name, '')), 80), k.sessions, k.sessions, k.price, v_exp)
  returning id into v_id;
  select name into v_salon_name from public.salons where id = k.salon_id;
  insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
  values (k.salon_id, p_phone,
          'بستهٔ «' || k.name || '» (' || public.fa_digits((k.sessions)::text) || ' جلسه) در ' || v_salon_name || ' برای شما فعال شد.'
            || E'\nاعتبار تا ' || public.jalali_label(v_exp),
          'pet_package', 'queued', now());
  return json_build_object('ok', true, 'id', v_id);
end;
$fn$;
grant execute on function public.sell_package(uuid, text, text) to authenticated;

-- Use one session for a visit: the service itself is covered, add-ons are not.
create or replace function public.use_package_session(p_purchase uuid, p_appt text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare pu public.package_purchases; a public.appointments; v_extras bigint;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  select * into a from public.appointments where id = p_appt and salon_id = public.current_salon_id() for update;
  if a.id is null or not (public.is_manager() or a.staff_id = public.my_stylist_id()) then
    return json_build_object('ok', false, 'error', 'نوبت پیدا نشد');
  end if;
  if a.package_purchase_id is not null then
    return json_build_object('ok', false, 'error', 'برای این نوبت قبلاً از بسته استفاده شده');
  end if;
  select * into pu from public.package_purchases where id = p_purchase and salon_id = a.salon_id for update;
  if pu.id is null or pu.customer_phone <> a.customer_phone or pu.service_id <> a.service_id then
    return json_build_object('ok', false, 'error', 'این بسته برای این نوبت نیست');
  end if;
  if pu.sessions_left <= 0 or pu.expires_at < public.salon_today() then
    return json_build_object('ok', false, 'error', 'بسته تمام یا منقضی شده');
  end if;
  update public.package_purchases set sessions_left = sessions_left - 1 where id = pu.id;
  select coalesce(sum((x ->> 'amount')::bigint), 0) into v_extras from jsonb_array_elements(coalesce(a.extra_charges, '[]'::jsonb)) x;
  perform set_config('app.trusted_rpc', 'on', true);
  update public.appointments set package_purchase_id = pu.id, final_price = v_extras where id = a.id;
  perform set_config('app.trusted_rpc', '', true);
  return json_build_object('ok', true, 'left', pu.sessions_left - 1, 'final_price', v_extras);
end;
$fn$;
grant execute on function public.use_package_session(uuid, text) to authenticated;

create or replace function public.my_packages_with_token(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_phone text; v_salon uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon from public.resolve_booking_token(p_token) r;
  if v_phone is null then return '[]'::json; end if;
  return coalesce((
    select json_agg(json_build_object('id', p.id, 'name', p.package_name, 'left', p.sessions_left, 'total', p.sessions_total,
                                      'expires_at', p.expires_at) order by p.expires_at)
      from public.package_purchases p
     where p.salon_id = v_salon and p.customer_phone = v_phone and p.expires_at >= public.salon_today() - 30), '[]'::json);
end;
$fn$;
grant execute on function public.my_packages_with_token(text) to anon, authenticated;

-- ----------------------------------------------- 10. large-dog capacity --
create or replace function public.check_pet_capacity()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_cap int; v_busy int;
begin
  if new.pet_size is null or new.pet_size not in ('large', 'giant')
     or new.status not in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed', 'awaiting_payment') then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.date = new.date and old.start_min = new.start_min and old.end_min = new.end_min
     and old.pet_size is not distinct from new.pet_size
     and old.status in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed', 'awaiting_payment') then
    return new;
  end if;
  select pet_large_capacity into v_cap from public.app_settings where salon_id = new.salon_id;
  if v_cap is null then
    return new;
  end if;
  select count(*) into v_busy
    from public.appointments a
   where a.salon_id = new.salon_id and a.date = new.date and a.id <> new.id
     and a.pet_size in ('large', 'giant')
     and a.status in ('pending', 'confirmed', 'rescheduled', 'reschedule_proposed', 'awaiting_payment')
     and a.start_min < new.end_min and a.end_min > new.start_min;
  if v_busy >= v_cap then
    raise exception 'ظرفیت سگ‌های بزرگ در این ساعت پر است' using errcode = 'P0001';
  end if;
  return new;
end;
$fn$;
drop trigger if exists trg_check_pet_capacity on public.appointments;
create trigger trg_check_pet_capacity before insert or update of date, start_min, end_min, status, pet_size on public.appointments
  for each row execute function public.check_pet_capacity();


-- >>>>>>>>>> supabase/migrations/v2.50_business_tools.sql
-- ============================================================================
-- Migration v2.50 — business tools (run after v2.49)
-- ============================================================================
--   1. Revenue beyond bookings: shop sales, packages and gift cards in one
--      report (top products, low stock) — revenue_extras().
--   2. Public salon profile: about, address, map, Instagram, gallery
--      (public bucket "salon-gallery"), hours, rating and reviews.
--   3. Discount codes (booking and/or shop) and gift cards (bought online
--      with the salon's Zarinpal, or sold at the desk; redeemed at checkout).
--   4. Staff commission: % of services, % of packages they sold.
--   6. Packages can be bought online.
--   7. Smart deposit: ask only customers with a recent no-show.
-- ============================================================================

-- ------------------------------------------------------------ 1. revenue --
alter table public.products add column if not exists low_stock_at int not null default 3;
alter table public.products drop constraint if exists products_low_stock_at_check;
alter table public.products add constraint products_low_stock_at_check check (low_stock_at between 0 and 1000);

-- ------------------------------------------------------- 6. packages online --
alter table public.package_purchases add column if not exists status text not null default 'active';
alter table public.package_purchases drop constraint if exists package_purchases_status_check;
alter table public.package_purchases add constraint package_purchases_status_check check (status in ('active', 'awaiting_payment', 'cancelled'));
alter table public.package_purchases add column if not exists sold_by text references public.stylists (id) on delete set null;
alter table public.package_purchases add column if not exists paid_online boolean not null default false;
alter table public.package_purchases add column if not exists payment_ref text;

-- ------------------------------------------------------- 3. coupons/gifts --
create table if not exists public.coupons (
  id            uuid primary key default gen_random_uuid(),
  salon_id      uuid not null default public.current_salon_id() references public.salons (id) on delete cascade,
  code          text not null check (code ~ '^[A-Z0-9آ-ی]{3,20}$'),
  percent       int check (percent is null or percent between 1 and 100),
  amount        bigint check (amount is null or amount between 1000 and 100000000),
  scope         text not null default 'both' check (scope in ('booking', 'shop', 'both')),
  min_total     bigint not null default 0 check (min_total >= 0),
  max_uses      int check (max_uses is null or max_uses between 1 and 100000),
  used_count    int not null default 0,
  valid_until   date,
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  check ((percent is null) <> (amount is null)),
  unique (salon_id, code)
);
alter table public.coupons enable row level security;
drop policy if exists p_coupons_mgr on public.coupons;
create policy p_coupons_mgr on public.coupons for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
grant select, insert, update, delete on public.coupons to authenticated;

create table if not exists public.coupon_uses (
  coupon_id  uuid not null references public.coupons (id) on delete cascade,
  salon_id   uuid not null references public.salons (id) on delete cascade,
