  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
grant select, insert, update on public.salon_profiles to authenticated;

-- ============================================================================
-- Functions
-- ============================================================================

-- --------------------------------------------------------------- revenue --
create or replace function public.revenue_extras(p_from date, p_to date)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id();
begin
  if not public.is_manager() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  return json_build_object(
    'ok', true,
    'shop_revenue', coalesce((select sum(total) from public.orders o
                               where o.salon_id = v_salon and o.created_at::date between p_from and p_to
                                 and o.status in ('pending', 'confirmed', 'ready', 'shipped', 'delivered')), 0),
    'shop_orders', (select count(*) from public.orders o
                     where o.salon_id = v_salon and o.created_at::date between p_from and p_to
                       and o.status in ('pending', 'confirmed', 'ready', 'shipped', 'delivered')),
    'packages_revenue', coalesce((select sum(price_paid) from public.package_purchases p
                                   where p.salon_id = v_salon and p.status = 'active' and p.created_at::date between p_from and p_to), 0),
    'packages_count', (select count(*) from public.package_purchases p
                        where p.salon_id = v_salon and p.status = 'active' and p.created_at::date between p_from and p_to),
    'gift_cards_revenue', coalesce((select sum(amount) from public.gift_cards g
                                     where g.salon_id = v_salon and g.status = 'active' and g.created_at::date between p_from and p_to), 0),
    'gift_cards_outstanding', coalesce((select sum(balance) from public.gift_cards g
                                         where g.salon_id = v_salon and g.status = 'active' and g.expires_at >= public.salon_today()), 0),
    'top_products', coalesce((
      select json_agg(t order by t.revenue desc) from (
        select i.name, sum(i.qty)::int as qty, sum(i.qty * i.unit_price) as revenue
          from public.order_items i join public.orders o on o.id = i.order_id
         where o.salon_id = v_salon and o.created_at::date between p_from and p_to
           and o.status in ('pending', 'confirmed', 'ready', 'shipped', 'delivered')
         group by i.name order by 3 desc limit 8) t), '[]'::json),
    'low_stock', coalesce((
      select json_agg(json_build_object('id', p.id, 'name', p.name, 'stock', p.stock) order by p.stock)
        from public.products p
       where p.salon_id = v_salon and p.active and p.stock is not null and p.stock <= p.low_stock_at), '[]'::json));
end;
$fn$;
grant execute on function public.revenue_extras(date, date) to authenticated;

-- --------------------------------------------------------------- profile --
create or replace function public.get_salon_profile()
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'name', s.name, 'slug', s.slug, 'business_type', s.business_type,
    'about', coalesce(p.about, ''), 'address', coalesce(p.address, ''), 'phone', coalesce(p.phone, ''),
    'instagram', coalesce(p.instagram, ''), 'map_url', coalesce(p.map_url, ''), 'gallery', coalesce(p.gallery, '{}'),
    'hours', coalesce((select json_agg(json_build_object('day', w.day_of_week, 'start', w.start_time, 'end', w.end_time, 'closed', w.is_closed)
                                       order by w.day_of_week)
                         from public.working_hours w where w.salon_id = s.id and w.staff_id is null), '[]'::json),
    'rating', (select json_build_object('avg', round(avg(f.rating)::numeric, 1), 'count', count(*))
                 from public.feedbacks f where f.salon_id = s.id),
    'reviews', case when coalesce(p.show_reviews, true) then coalesce((
       select json_agg(r) from (
         select f.rating, left(f.comment, 300) as comment, f.created_at::date as date,
                split_part(coalesce(nullif(trim(a.customer_name), ''), 'مشتری'), ' ', 1) as name
           from public.feedbacks f left join public.appointments a on a.id = f.booking_id
          where f.salon_id = s.id and f.rating >= 4 and length(trim(f.comment)) >= 5
          order by f.created_at desc limit 12) r), '[]'::json) else '[]'::json end,
    'shop', coalesce((select enabled from public.shop_settings where salon_id = s.id), false))
  from public.salons s
  left join public.salon_profiles p on p.salon_id = s.id
  where s.id = public.current_salon_id() and s.active;
$fn$;
grant execute on function public.get_salon_profile() to anon, authenticated;

create or replace function public.gallery_write_ok(p_name text)
returns boolean
language sql stable security definer set search_path = public as $fn$
  select public.is_manager()
     and split_part(coalesce(p_name, ''), '/', 1) = public.current_salon_id()::text
     and split_part(p_name, '/', 3) = ''
     and split_part(p_name, '/', 2) ~ '^[a-z0-9-]{8,64}\.(jpg|jpeg|png|webp)$';
$fn$;
revoke all on function public.gallery_write_ok(text) from public;
grant execute on function public.gallery_write_ok(text) to authenticated;

do $do$
begin
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    raise notice 'Supabase Storage not found — the salon gallery is disabled on this database';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('salon-gallery', 'salon-gallery', true, 3145728, array['image/jpeg', 'image/png', 'image/webp'])
  on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  execute 'drop policy if exists salon_gallery_insert on storage.objects';
  execute $p$create policy salon_gallery_insert on storage.objects for insert to authenticated
           with check (bucket_id = 'salon-gallery' and public.gallery_write_ok(name))$p$;
  execute 'drop policy if exists salon_gallery_delete on storage.objects';
  execute $p$create policy salon_gallery_delete on storage.objects for delete to authenticated
           using (bucket_id = 'salon-gallery' and public.gallery_write_ok(name))$p$;
end
$do$;

-- --------------------------------------------------------------- coupons --
-- What a code is worth on a given total (no side effects).
create or replace function public.coupon_value(p_salon uuid, p_code text, p_scope text, p_total bigint, p_phone text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare c public.coupons; v bigint;
begin
  select * into c from public.coupons
   where salon_id = p_salon and code = upper(trim(coalesce(p_code, ''))) and active;
  if c.id is null or (c.valid_until is not null and c.valid_until < public.salon_today()) then
    return json_build_object('ok', false, 'error', 'کد تخفیف معتبر نیست');
  end if;
  if c.scope <> 'both' and c.scope <> p_scope then
    return json_build_object('ok', false, 'error', case when p_scope = 'shop' then 'این کد برای فروشگاه نیست' else 'این کد برای نوبت نیست' end);
  end if;
  if c.max_uses is not null and c.used_count >= c.max_uses then
    return json_build_object('ok', false, 'error', 'ظرفیت این کد تمام شده است');
  end if;
  if coalesce(p_total, 0) < c.min_total then
    return json_build_object('ok', false, 'error', 'این کد برای خرید بالای ' || public.fa_money(c.min_total) || ' تومان است');
  end if;
  if p_phone is not null and exists (select 1 from public.coupon_uses u where u.coupon_id = c.id and u.phone = p_phone) then
    return json_build_object('ok', false, 'error', 'این کد را قبلاً استفاده کرده‌اید');
  end if;
  v := case when c.percent is not null then round(p_total * c.percent / 100.0) else least(c.amount, p_total) end;
  return json_build_object('ok', true, 'id', c.id, 'code', c.code, 'discount', v, 'percent', c.percent, 'amount', c.amount);
end;
$fn$;
revoke all on function public.coupon_value(uuid, text, text, bigint, text) from public, anon, authenticated;

-- Preview for the booking page / checkout.
create or replace function public.check_coupon(p_code text, p_scope text, p_total bigint, p_phone text default null)
returns json
language plpgsql security definer set search_path = public as $fn$
begin
  if not public.check_rate_limit('coupon:' || coalesce(public.current_salon_id()::text, '') || ':' || coalesce(p_phone, ''), 20, 10) then
    return json_build_object('ok', false, 'error', 'تعداد تلاش زیاد است؛ کمی بعد دوباره امتحان کنید');
  end if;
  return public.coupon_value(public.current_salon_id(), p_code, p_scope, p_total, nullif(p_phone, ''));
end;
$fn$;
grant execute on function public.check_coupon(text, text, bigint, text) to anon, authenticated;

-- Records a use (call inside the transaction that applies it).
create or replace function public.consume_coupon(p_coupon uuid, p_phone text, p_ref text, p_discount bigint)
returns boolean
language plpgsql security definer set search_path = public as $fn$
declare n int;
begin
  -- the use first, so a repeat attempt never bumps the counter
  insert into public.coupon_uses (coupon_id, salon_id, phone, ref, discount)
  select p_coupon, salon_id, p_phone, p_ref, p_discount from public.coupons where id = p_coupon
  on conflict do nothing;
  get diagnostics n = row_count;
  if n = 0 then return false; end if;
  update public.coupons set used_count = used_count + 1
   where id = p_coupon and (max_uses is null or used_count < max_uses);
  get diagnostics n = row_count;
  if n = 0 then
    delete from public.coupon_uses where coupon_id = p_coupon and phone = p_phone;
    return false;
  end if;
  return true;
end;
$fn$;
revoke all on function public.consume_coupon(uuid, text, text, bigint) from public, anon, authenticated;

-- A cancelled (or expired unpaid) order or booking gives the code back.
create or replace function public.release_coupon_use()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare r record;
begin
  if new.status = 'cancelled' and old.status is distinct from 'cancelled' and new.coupon_code is not null then
    for r in delete from public.coupon_uses where salon_id = new.salon_id and ref = new.id::text returning coupon_id loop
      update public.coupons set used_count = greatest(0, used_count - 1) where id = r.coupon_id;
    end loop;
  end if;
  return new;
end;
$fn$;
revoke all on function public.release_coupon_use() from public, anon, authenticated;
drop trigger if exists trg_orders_release_coupon on public.orders;
create trigger trg_orders_release_coupon after update of status on public.orders
  for each row execute function public.release_coupon_use();
drop trigger if exists trg_appts_release_coupon on public.appointments;
create trigger trg_appts_release_coupon after update of status on public.appointments
  for each row execute function public.release_coupon_use();

-- A code on a fresh booking (same browser, within 30 minutes; as transport in v2.49).
create or replace function public.apply_booking_coupon(p_appt text, p_phone text, p_code text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare a public.appointments; v json; v_disc bigint; v_base bigint;
begin
  select * into a from public.appointments
   where id = p_appt and salon_id = public.current_salon_id() and customer_phone = p_phone for update;
  if a.id is null or a.created_at < now() - interval '30 minutes' or a.coupon_code is not null
     or a.status in ('cancelled', 'no_show', 'completed') or a.final_price is null then
    return json_build_object('ok', false, 'error', 'کد تخفیف روی این نوبت قابل استفاده نیست');
  end if;
  -- the pick-up & drop-off fee (v2.49) is not discounted
  v_base := greatest(0, a.final_price - coalesce(a.transport_fee, 0));
  v := public.coupon_value(a.salon_id, p_code, 'booking', v_base, p_phone);
  if not (v ->> 'ok')::boolean then return v; end if;
  v_disc := least((v ->> 'discount')::bigint, v_base);
  if not public.consume_coupon((v ->> 'id')::uuid, p_phone, a.id, v_disc) then
    return json_build_object('ok', false, 'error', 'این کد را قبلاً استفاده کرده‌اید');
  end if;
  perform set_config('app.trusted_rpc', 'on', true);
  update public.appointments
     set coupon_code = v ->> 'code', coupon_discount = v_disc, final_price = final_price - v_disc,
         deposit_amount = case when deposit_amount is not null then least(deposit_amount, greatest(1000, final_price - v_disc)) end
   where id = a.id;
  perform set_config('app.trusted_rpc', '', true);
  return json_build_object('ok', true, 'discount', v_disc, 'final_price', a.final_price - v_disc);
end;
$fn$;
grant execute on function public.apply_booking_coupon(text, text, text) to anon, authenticated;

-- place_order with an optional discount code (replaces the 8-argument version)
drop function if exists public.place_order(text, text, jsonb, text, text, text, text, text);
create or replace function public.place_order(
  p_customer_name text, p_customer_phone text, p_items jsonb,
  p_delivery text, p_payment text,
  p_address text default '', p_postal_code text default '', p_note text default '',
  p_coupon text default null
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare
  v_salon uuid := public.current_salon_id();
  v_shop json; v_id uuid; v_code text; v_subtotal bigint := 0; v_fee bigint := 0; v_total bigint;
  v_pids uuid[]; v_qtys int[]; r record; v_lines int := 0; v_cp json; v_disc bigint := 0;
begin
  if v_salon is null then
    return json_build_object('ok', false, 'error', 'سالن پیدا نشد');
  end if;
  v_shop := public.get_shop();
  if not (v_shop ->> 'enabled')::boolean then
    return json_build_object('ok', false, 'error', 'فروشگاه این سالن فعال نیست');
  end if;
  if coalesce(p_customer_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  p_customer_name := trim(coalesce(p_customer_name, ''));
  if p_customer_name = '' or length(p_customer_name) > 80 then
    return json_build_object('ok', false, 'error', 'نام لازم است');
  end if;
  if p_delivery = 'pickup' and not (v_shop ->> 'pickup')::boolean
     or p_delivery = 'shipping' and not (v_shop ->> 'shipping')::boolean
     or p_delivery is null or p_delivery not in ('pickup', 'shipping') then
    return json_build_object('ok', false, 'error', 'روش تحویل در دسترس نیست');
  end if;
  if p_payment = 'online' and not (v_shop ->> 'online')::boolean
     or p_payment = 'cash' and not (v_shop ->> 'cash')::boolean
     or p_payment is null or p_payment not in ('online', 'cash') then
    return json_build_object('ok', false, 'error', 'روش پرداخت در دسترس نیست');
  end if;
  p_address := trim(coalesce(p_address, ''));
  p_postal_code := translate(trim(coalesce(p_postal_code, '')), '۰۱۲۳۴۵۶۷۸۹', '0123456789');
  if p_delivery = 'shipping' and length(p_address) < 10 then
    return json_build_object('ok', false, 'error', 'آدرس کامل را وارد کنید');
  end if;
  if length(p_address) > 400 or length(coalesce(p_note, '')) > 400 or p_postal_code !~ '^([0-9]{10})?$' then
    return json_build_object('ok', false, 'error', 'آدرس، کد پستی یا توضیحات نامعتبر است');
  end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 30 then
    return json_build_object('ok', false, 'error', 'سبد خرید خالی است');
  end if;
  if not public.check_rate_limit('order:' || v_salon || ':' || p_customer_phone, 6, 60) then
    return json_build_object('ok', false, 'error', 'تعداد سفارش‌ها زیاد است؛ کمی بعد دوباره تلاش کنید');
  end if;

  perform public.expire_unpaid_orders(v_salon);
  if (select count(*) from public.orders
       where salon_id = v_salon and customer_phone = p_customer_phone and status = 'awaiting_payment') >= 3 then
    return json_build_object('ok', false, 'error', 'چند سفارش پرداخت‌نشده دارید — اول آن‌ها را پرداخت یا لغو کنید');
  end if;

  begin
    select array_agg(pid order by pid), array_agg(qty order by pid) into v_pids, v_qtys
      from (select (e ->> 'product_id')::uuid as pid, sum((e ->> 'qty')::int)::int as qty
              from jsonb_array_elements(p_items) e group by 1) x;
  exception when others then
    return json_build_object('ok', false, 'error', 'سبد خرید نامعتبر است');
  end;
  if array_position(v_pids, null) is not null or exists (select 1 from unnest(v_qtys) q where q is null or q < 1) then
    return json_build_object('ok', false, 'error', 'سبد خرید نامعتبر است');
  end if;
  if exists (select 1 from unnest(v_qtys) q where q > 50) then
    return json_build_object('ok', false, 'error', 'حداکثر ۵۰ عدد از هر کالا');
  end if;

  for r in
    select p.id, p.name, p.price, p.stock, p.active, l.qty
      from unnest(v_pids, v_qtys) as l(pid, qty)
      join public.products p on p.id = l.pid and p.salon_id = v_salon
     order by p.id
       for update of p
  loop
    if not r.active then
      return json_build_object('ok', false, 'error', 'یکی از کالاها دیگر موجود نیست — سبد را به‌روز کنید', 'refresh', true);
    end if;
    if r.stock is not null and r.stock < r.qty then
      return json_build_object('ok', false,
        'error', case when r.stock = 0 then '«' || r.name || '» تمام شده است'
                      else 'از «' || r.name || '» فقط ' || public.fa_digits(r.stock::text) || ' عدد موجود است' end,
        'refresh', true);
    end if;
    v_subtotal := v_subtotal + r.price * r.qty;
    v_lines := v_lines + 1;
  end loop;
  if v_lines <> cardinality(v_pids) then
    return json_build_object('ok', false, 'error', 'یکی از کالاها دیگر موجود نیست — سبد را به‌روز کنید', 'refresh', true);
  end if;

  if nullif(trim(coalesce(p_coupon, '')), '') is not null then
    v_cp := public.coupon_value(v_salon, p_coupon, 'shop', v_subtotal, p_customer_phone);
    if not (v_cp ->> 'ok')::boolean then return v_cp; end if;
    v_disc := least((v_cp ->> 'discount')::bigint, v_subtotal);
  end if;

  if p_delivery = 'shipping' then
    v_fee := (v_shop ->> 'shipping_fee')::bigint;
    if (v_shop ->> 'free_shipping_over')::bigint > 0 and v_subtotal >= (v_shop ->> 'free_shipping_over')::bigint then
      v_fee := 0;
    end if;
  end if;
  v_total := v_subtotal - v_disc + v_fee;
  if p_payment = 'online' and v_total < 1000 then
    return json_build_object('ok', false, 'error', 'مبلغ برای پرداخت آنلاین خیلی کم است');
  end if;
  v_code := public.new_order_code(v_salon);

  insert into public.orders (salon_id, code, customer_name, customer_phone, delivery, address, postal_code, customer_note,
                             subtotal, shipping_fee, total, payment_method, status, coupon_code, coupon_discount)
  values (v_salon, v_code, p_customer_name, p_customer_phone, p_delivery,
          case when p_delivery = 'shipping' then p_address else '' end,
          case when p_delivery = 'shipping' then p_postal_code else '' end,
          trim(coalesce(p_note, '')), v_subtotal, v_fee, v_total, p_payment,
          case when p_payment = 'online' then 'awaiting_payment' else 'pending' end,
          v_cp ->> 'code', v_disc)
  returning id into v_id;

  if v_disc > 0 and not public.consume_coupon((v_cp ->> 'id')::uuid, p_customer_phone, v_id::text, v_disc) then
    raise exception 'coupon race' using errcode = 'P0001';
  end if;

  insert into public.order_items (order_id, salon_id, product_id, name, unit_price, qty)
  select v_id, v_salon, p.id, p.name, p.price, l.qty
    from unnest(v_pids, v_qtys) as l(pid, qty) join public.products p on p.id = l.pid;
  update public.products p set stock = p.stock - l.qty, updated_at = now()
    from unnest(v_pids, v_qtys) as l(pid, qty) where p.id = l.pid and p.stock is not null;

  if p_payment = 'cash' then
    perform public.notify_new_order(v_id);
  end if;
  return json_build_object('ok', true, 'id', v_id, 'code', v_code, 'subtotal', v_subtotal, 'discount', v_disc,
                           'shipping_fee', v_fee, 'total', v_total, 'status',
                           case when p_payment = 'online' then 'awaiting_payment' else 'pending' end);
end;
$fn$;
grant execute on function public.place_order(text, text, jsonb, text, text, text, text, text, text) to anon, authenticated;

-- ------------------------------------------------------------ gift cards --
create or replace function public.new_gift_code(p_salon uuid)
returns text
language plpgsql volatile security definer set search_path = public as $fn$
declare v text; alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
begin
  loop
    v := 'G';
    for i in 1..8 loop
      v := v || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from public.gift_cards where salon_id = p_salon and code = v);
  end loop;
  return v;
end;
$fn$;
revoke all on function public.new_gift_code(uuid) from public, anon, authenticated;

create or replace function public.gift_card_activated(p_id uuid)
returns void
language plpgsql security definer set search_path = public as $fn$
declare g public.gift_cards; v_salon_name text; v_link text;
begin
  select * into g from public.gift_cards where id = p_id;
  select name into v_salon_name from public.salons where id = g.salon_id;
  v_link := public.public_link('/' || (select slug from public.salons where id = g.salon_id));
  insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
  values (g.salon_id, g.recipient_phone,
          coalesce(nullif(g.recipient_name, ''), 'دوست عزیز') || '، ' || coalesce(nullif(g.buyer_name, ''), 'یکی از دوستانتان')
            || ' برایتان کارت هدیهٔ ' || public.fa_money(g.amount) || ' تومانی ' || v_salon_name || ' فرستاده 🎁'
            || case when g.message <> '' then E'\n«' || g.message || '»' else '' end
            || E'\nکد: ' || g.code || ' — اعتبار تا ' || public.jalali_label(g.expires_at)
            || case when v_link is not null then E'\n' || v_link else '' end,
          'gift_card', 'queued', now());
  if g.buyer_phone ~ '^09[0-9]{9}$' and g.buyer_phone <> g.recipient_phone then
    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (g.salon_id, g.buyer_phone, 'کارت هدیهٔ شما برای ' || coalesce(nullif(g.recipient_name, ''), g.recipient_phone)
              || ' ارسال شد. ' || v_salon_name, 'gift_card', 'queued', now());
  end if;
end;
$fn$;
revoke all on function public.gift_card_activated(uuid) from public, anon, authenticated;

-- Customer buys a gift card online (pays through the payment function).
create or replace function public.create_gift_card(
  p_amount bigint, p_buyer_name text, p_buyer_phone text, p_recipient_name text, p_recipient_phone text, p_message text default ''
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id(); v_id uuid;
begin
  if v_salon is null then return json_build_object('ok', false, 'error', 'سالن پیدا نشد'); end if;
  if coalesce((select zarinpal_merchant_id from public.salon_payment_settings where salon_id = v_salon), '') = '' then
    return json_build_object('ok', false, 'error', 'خرید آنلاین کارت هدیه در این سالن فعال نیست');
  end if;
  if coalesce(p_amount, 0) not between 50000 and 50000000 then
    return json_build_object('ok', false, 'error', 'مبلغ کارت هدیه بین ۵۰ هزار تا ۵۰ میلیون تومان است');
  end if;
  if coalesce(p_buyer_phone, '') !~ '^09[0-9]{9}$' or coalesce(p_recipient_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  if length(coalesce(p_message, '')) > 200 or length(coalesce(p_buyer_name, '')) > 80 or length(coalesce(p_recipient_name, '')) > 80 then
    return json_build_object('ok', false, 'error', 'متن طولانی است');
  end if;
  if not public.check_rate_limit('gift:' || v_salon || ':' || p_buyer_phone, 5, 60) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست‌ها زیاد است');
  end if;
  insert into public.gift_cards (salon_id, code, amount, balance, buyer_name, buyer_phone, recipient_name, recipient_phone, message, status, expires_at)
  values (v_salon, public.new_gift_code(v_salon), p_amount, p_amount, trim(coalesce(p_buyer_name, '')), p_buyer_phone,
          trim(coalesce(p_recipient_name, '')), p_recipient_phone, trim(coalesce(p_message, '')), 'awaiting_payment',
          public.salon_today() + 365)
  returning id into v_id;
  return json_build_object('ok', true, 'id', v_id, 'amount', p_amount);
end;
$fn$;
grant execute on function public.create_gift_card(bigint, text, text, text, text, text) to anon, authenticated;

-- Staff sell one at the desk (paid in cash/card there).
create or replace function public.issue_gift_card(p_amount bigint, p_recipient_phone text, p_recipient_name text default '', p_buyer_name text default '', p_message text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id(); v_id uuid; v_code text;
begin
  if not public.is_staff() then return json_build_object('ok', false, 'error', 'دسترسی ندارید'); end if;
  if coalesce(p_amount, 0) not between 10000 and 100000000 then
    return json_build_object('ok', false, 'error', 'مبلغ نامعتبر است');
  end if;
  if coalesce(p_recipient_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  v_code := public.new_gift_code(v_salon);
  insert into public.gift_cards (salon_id, code, amount, balance, buyer_name, recipient_name, recipient_phone, message, status, sold_at_desk, expires_at)
  values (v_salon, v_code, p_amount, p_amount, left(trim(coalesce(p_buyer_name, '')), 80), left(trim(coalesce(p_recipient_name, '')), 80),
          p_recipient_phone, left(trim(coalesce(p_message, '')), 200), 'active', true, public.salon_today() + 365)
  returning id into v_id;
  perform public.gift_card_activated(v_id);
  return json_build_object('ok', true, 'id', v_id, 'code', v_code);
end;
$fn$;
grant execute on function public.issue_gift_card(bigint, text, text, text, text) to authenticated;

create or replace function public.confirm_gift_card_payment(p_id uuid, p_ref text)
returns text
language plpgsql security definer set search_path = public as $fn$
declare g public.gift_cards;
begin
  select * into g from public.gift_cards where id = p_id for update;
  if g.id is null then return 'missing'; end if;
  if g.status = 'active' then return 'already'; end if;
  update public.gift_cards set status = 'active', payment_ref = p_ref where id = g.id;
  perform public.gift_card_activated(g.id);
  return 'confirmed';
end;
$fn$;
revoke all on function public.confirm_gift_card_payment(uuid, text) from public, anon, authenticated;
grant execute on function public.confirm_gift_card_payment(uuid, text) to service_role;

-- Balance check (anyone holding the code).
create or replace function public.gift_card_balance(p_code text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare g public.gift_cards;
begin
  if not public.check_rate_limit('giftbal:' || coalesce(public.current_salon_id()::text, ''), 60, 10) then
    return json_build_object('ok', false, 'error', 'تعداد تلاش زیاد است');
  end if;
  select * into g from public.gift_cards
   where salon_id = public.current_salon_id() and code = upper(trim(coalesce(p_code, ''))) and status = 'active';
  if g.id is null then return json_build_object('ok', false, 'error', 'کارت هدیه پیدا نشد'); end if;
  return json_build_object('ok', true, 'balance', g.balance, 'expires_at', g.expires_at, 'expired', g.expires_at < public.salon_today());
end;
$fn$;
grant execute on function public.gift_card_balance(text) to anon, authenticated;

-- Staff pay (part of) a visit with a gift card.
create or replace function public.redeem_gift_card(p_code text, p_appt text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare g public.gift_cards; a public.appointments; v_amt bigint;
begin
  if not public.is_staff() then return json_build_object('ok', false, 'error', 'دسترسی ندارید'); end if;
  select * into a from public.appointments where id = p_appt and salon_id = public.current_salon_id() for update;
  if a.id is null or not (public.is_manager() or a.staff_id = public.my_stylist_id()) then
    return json_build_object('ok', false, 'error', 'نوبت پیدا نشد');
  end if;
  if a.gift_card_amount is not null then return json_build_object('ok', false, 'error', 'برای این نوبت قبلاً کارت هدیه استفاده شده'); end if;
  if coalesce(a.final_price, 0) <= 0 then return json_build_object('ok', false, 'error', 'مبلغی برای پرداخت نیست'); end if;
  select * into g from public.gift_cards
   where salon_id = a.salon_id and code = upper(trim(coalesce(p_code, ''))) and status = 'active' for update;
  if g.id is null or g.expires_at < public.salon_today() or g.balance <= 0 then
    return json_build_object('ok', false, 'error', 'کارت هدیه معتبر نیست یا اعتبارش تمام شده');
  end if;
  v_amt := least(g.balance, a.final_price);
  update public.gift_cards set balance = balance - v_amt where id = g.id;
  perform set_config('app.trusted_rpc', 'on', true);
  update public.appointments set gift_card_amount = v_amt, final_price = final_price - v_amt where id = a.id;
  perform set_config('app.trusted_rpc', '', true);
  return json_build_object('ok', true, 'used', v_amt, 'balance', g.balance - v_amt, 'final_price', a.final_price - v_amt);
end;
$fn$;
grant execute on function public.redeem_gift_card(text, text) to authenticated;

-- ----------------------------------------------------- packages online --
create or replace function public.buy_package_online(p_package uuid, p_phone text, p_name text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare k public.pet_packages; v_id uuid; v_salon uuid := public.current_salon_id();
begin
  if coalesce((select zarinpal_merchant_id from public.salon_payment_settings where salon_id = v_salon), '') = '' then
    return json_build_object('ok', false, 'error', 'خرید آنلاین بسته فعال نیست — در سالن بخرید');
  end if;
  if coalesce(p_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  select * into k from public.pet_packages where id = p_package and salon_id = v_salon and active;
  if k.id is null then return json_build_object('ok', false, 'error', 'بسته پیدا نشد'); end if;
  if not public.check_rate_limit('pkg:' || v_salon || ':' || p_phone, 5, 60) then
    return json_build_object('ok', false, 'error', 'تعداد درخواست‌ها زیاد است');
  end if;
  insert into public.package_purchases (salon_id, package_id, package_name, service_id, customer_phone, customer_name,
                                        sessions_total, sessions_left, price_paid, expires_at, status, paid_online)
  values (v_salon, k.id, k.name, k.service_id, p_phone, left(trim(coalesce(p_name, '')), 80), k.sessions, k.sessions, k.price,
          public.salon_today() + k.valid_days, 'awaiting_payment', true)
  returning id into v_id;
  return json_build_object('ok', true, 'id', v_id, 'price', k.price);
end;
$fn$;
grant execute on function public.buy_package_online(uuid, text, text) to anon, authenticated;

create or replace function public.confirm_package_payment(p_id uuid, p_ref text)
returns text
language plpgsql security definer set search_path = public as $fn$
declare p public.package_purchases; v_salon_name text; v_k public.pet_packages;
begin
  select * into p from public.package_purchases where id = p_id for update;
  if p.id is null then return 'missing'; end if;
  if p.status = 'active' then return 'already'; end if;
  select * into v_k from public.pet_packages where id = p.package_id;
  update public.package_purchases
     set status = 'active', payment_ref = p_ref,
         expires_at = public.salon_today() + coalesce(v_k.valid_days, (p.expires_at - p.created_at::date))
   where id = p.id;
  select name into v_salon_name from public.salons where id = p.salon_id;
  insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
  values (p.salon_id, p.customer_phone,
          'بستهٔ «' || p.package_name || '» (' || public.fa_digits(p.sessions_total::text) || ' جلسه) در ' || v_salon_name || ' فعال شد.',
          'pet_package', 'queued', now());
  return 'confirmed';
end;
$fn$;
revoke all on function public.confirm_package_payment(uuid, text) from public, anon, authenticated;
grant execute on function public.confirm_package_payment(uuid, text) to service_role;

-- sold_by for desk sales + only active purchases count
create or replace function public.sell_package(p_package uuid, p_phone text, p_name text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare k public.pet_packages; v_id uuid; v_salon_name text; v_exp date;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  if coalesce(p_phone, '') !~ '^09[0-9]{9}$' then
    return json_build_object('ok', false, 'error', 'شماره موبایل نامعتبر است');
  end if;
  select * into k from public.pet_packages where id = p_package and salon_id = public.current_salon_id() and active;
  if k.id is null then
    return json_build_object('ok', false, 'error', 'بسته پیدا نشد');
  end if;
  v_exp := public.salon_today() + k.valid_days;
  insert into public.package_purchases (salon_id, package_id, package_name, service_id, customer_phone, customer_name,
                                        sessions_total, sessions_left, price_paid, expires_at, sold_by)
  values (k.salon_id, k.id, k.name, k.service_id, p_phone, left(trim(coalesce(p_name, '')), 80), k.sessions, k.sessions, k.price, v_exp,
          public.my_stylist_id())
  returning id into v_id;
  select name into v_salon_name from public.salons where id = k.salon_id;
  insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
  values (k.salon_id, p_phone,
          'بستهٔ «' || k.name || '» (' || public.fa_digits(k.sessions::text) || ' جلسه) در ' || v_salon_name || ' برای شما فعال شد.'
            || E'\nاعتبار تا ' || public.jalali_label(v_exp),
          'pet_package', 'queued', now());
  return json_build_object('ok', true, 'id', v_id);
end;
$fn$;
grant execute on function public.sell_package(uuid, text, text) to authenticated;

create or replace function public.use_package_session(p_purchase uuid, p_appt text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare pu public.package_purchases; a public.appointments; v_extras bigint;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  select * into a from public.appointments where id = p_appt and salon_id = public.current_salon_id() for update;
  if a.id is null or not (public.is_manager() or a.staff_id = public.my_stylist_id()) then
    return json_build_object('ok', false, 'error', 'نوبت پیدا نشد');
  end if;
  if a.package_purchase_id is not null then
    return json_build_object('ok', false, 'error', 'برای این نوبت قبلاً از بسته استفاده شده');
  end if;
  select * into pu from public.package_purchases where id = p_purchase and salon_id = a.salon_id for update;
  if pu.id is null or pu.status <> 'active' or pu.customer_phone <> a.customer_phone or pu.service_id <> a.service_id then
    return json_build_object('ok', false, 'error', 'این بسته برای این نوبت نیست');
  end if;
  if pu.sessions_left <= 0 or pu.expires_at < public.salon_today() then
    return json_build_object('ok', false, 'error', 'بسته تمام یا منقضی شده');
  end if;
  update public.package_purchases set sessions_left = sessions_left - 1 where id = pu.id;
  select coalesce(sum((x ->> 'amount')::bigint), 0) into v_extras from jsonb_array_elements(coalesce(a.extra_charges, '[]'::jsonb)) x;
  perform set_config('app.trusted_rpc', 'on', true);
  update public.appointments set package_purchase_id = pu.id, final_price = v_extras where id = a.id;
  perform set_config('app.trusted_rpc', '', true);
  return json_build_object('ok', true, 'left', pu.sessions_left - 1, 'final_price', v_extras);
end;
$fn$;
grant execute on function public.use_package_session(uuid, text) to authenticated;

create or replace function public.my_packages_with_token(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_phone text; v_salon uuid;
begin
  select r.phone, r.salon_id into v_phone, v_salon from public.resolve_booking_token(p_token) r;
  if v_phone is null then return '[]'::json; end if;
  return coalesce((
    select json_agg(json_build_object('id', p.id, 'name', p.package_name, 'left', p.sessions_left, 'total', p.sessions_total,
                                      'expires_at', p.expires_at) order by p.expires_at)
      from public.package_purchases p
     where p.salon_id = v_salon and p.customer_phone = v_phone and p.status = 'active'
       and p.expires_at >= public.salon_today() - 30), '[]'::json);
end;
$fn$;
grant execute on function public.my_packages_with_token(text) to anon, authenticated;

-- unpaid online purchases (gift cards, packages) are dropped after a day
create or replace function public.expire_unpaid_purchases()
returns int
language plpgsql security definer set search_path = public as $fn$
declare n1 int; n2 int;
begin
  update public.gift_cards set status = 'cancelled' where status = 'awaiting_payment' and created_at < now() - interval '1 day';
  get diagnostics n1 = row_count;
  update public.package_purchases set status = 'cancelled' where status = 'awaiting_payment' and created_at < now() - interval '1 day';
  get diagnostics n2 = row_count;
  return n1 + n2;
end;
$fn$;
revoke all on function public.expire_unpaid_purchases() from public, anon, authenticated;
grant execute on function public.expire_unpaid_purchases() to service_role;

-- ------------------------------------------------------------ commission --
create or replace function public.commission_report(p_from date, p_to date)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id(); v_me text := public.my_stylist_id();
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  return json_build_object('ok', true, 'rows', coalesce((
    select json_agg(x order by x.total_commission desc) from (
      select s.id, s.name, s.commission_pct, s.package_commission_pct,
             coalesce(a.cnt, 0) as services_count,
             coalesce(a.revenue, 0) as services_revenue,
             round(coalesce(a.revenue, 0) * s.commission_pct / 100.0)::bigint as services_commission,
             coalesce(k.cnt, 0) as packages_count,
             coalesce(k.revenue, 0) as packages_revenue,
             round(coalesce(k.revenue, 0) * s.package_commission_pct / 100.0)::bigint as packages_commission,
             round(coalesce(a.revenue, 0) * s.commission_pct / 100.0)::bigint
               + round(coalesce(k.revenue, 0) * s.package_commission_pct / 100.0)::bigint as total_commission
        from public.stylists s
        left join lateral (
          select count(*) as cnt,
                 -- the service itself: pick-up fees are not the groomer's work
                 sum(coalesce(ap.final_price, 0) - coalesce(ap.transport_fee, 0)) as revenue
            from public.appointments ap
           where ap.salon_id = v_salon and ap.staff_id = s.id and ap.status = 'completed'
             and ap.date between p_from and p_to) a on true
        left join lateral (
          select count(*) as cnt, sum(pp.price_paid) as revenue
            from public.package_purchases pp
           where pp.salon_id = v_salon and pp.sold_by = s.id and pp.status = 'active'
             and pp.created_at::date between p_from and p_to) k on true
       where s.salon_id = v_salon and (public.is_manager() or s.id = v_me)) x), '[]'::json));
end;
$fn$;
grant execute on function public.commission_report(date, date) to authenticated;

-- --------------------------------------------------------- smart deposit --
create or replace function public.hold_for_deposit()
returns trigger
language plpgsql security definer set search_path = public as $fn$
declare v_set record; v_merchant text;
begin
  if new.status not in ('pending', 'confirmed') or new.final_price is null or new.final_price <= 0 then
    return new;
  end if;
  if public.is_staff() then
    return new; -- bookings entered by staff never wait for an online payment
  end if;
  if current_setting('app.skip_deposit', true) = 'on' then
    return new; -- booked from a link the salon sent (see create_booking_from_rebooking_token)
  end if;
  select deposit_percent, deposit_min_price, deposit_mode into v_set from public.app_settings where salon_id = new.salon_id;
  if coalesce(v_set.deposit_percent, 0) = 0 or new.final_price < coalesce(v_set.deposit_min_price, 0) then
    return new;
  end if;
  -- v2.50: 'risky' — only customers who missed a visit in the last year
  if coalesce(v_set.deposit_mode, 'all') = 'risky' and not exists (
       select 1 from public.appointments a
        where a.salon_id = new.salon_id and a.customer_phone = new.customer_phone and a.status = 'no_show'
          and a.date >= public.salon_today() - 365) then
    return new;
  end if;
  select zarinpal_merchant_id into v_merchant from public.salon_payment_settings where salon_id = new.salon_id;
  if coalesce(v_merchant, '') = '' then
    return new;
  end if;
  new.deposit_amount := greatest(1000, round(new.final_price * v_set.deposit_percent / 100.0)); -- Zarinpal minimum is 1,000 toman
  new.status := 'awaiting_payment';
  return new;
end;
$fn$;

drop function if exists public.deposit_terms();
create or replace function public.deposit_terms()
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'enabled', coalesce(s.deposit_percent, 0) > 0 and coalesce(p.zarinpal_merchant_id, '') <> '',
    'percent', coalesce(s.deposit_percent, 0),
    'min_price', coalesce(s.deposit_min_price, 0),
    'mode', coalesce(s.deposit_mode, 'all'),
    'online', coalesce(p.zarinpal_merchant_id, '') <> ''
  )
  from (select public.current_salon_id() as salon_id) c
  left join public.app_settings s on s.salon_id = c.salon_id
  left join public.salon_payment_settings p on p.salon_id = c.salon_id;
$fn$;
grant execute on function public.deposit_terms() to anon, authenticated;


-- >>>>>>>>>> supabase/migrations/v2.51_operations.sql
-- ============================================================================
-- Migration v2.51 — operations (run after v2.50)
-- ============================================================================
--   8. Pet health record: allergies, medications, vet; weight history;
--      the salon's partner vet suggested in a report with findings.
--   9. Shop: product variants (same group, different size/weight) and a
--      shipment tracking code + carrier.
--  10. Supplies inventory (shampoo, colour, …) with low-stock alerts;
--      purchases are booked as expenses.
--  11. Check-in: staff scan the customer's QR (tracking code).
--  12. Branches: one owner, several salons, switch from the panel and a
--      combined summary.
--  13. Security: two-step login (TOTP via Supabase Auth) is honoured by the
--      role checks; daily backups of each salon's data (last 7 kept).
-- ============================================================================

-- ---------------------------------------------------------- 8. pet health --
alter table public.pets add column if not exists allergies   text not null default '';
alter table public.pets add column if not exists medications text not null default '';
alter table public.pets add column if not exists vet_name    text not null default '';
alter table public.pets add column if not exists vet_phone   text not null default '';
alter table public.pets drop constraint if exists pets_health_len_check;
alter table public.pets add constraint pets_health_len_check
  check (length(allergies) <= 300 and length(medications) <= 300 and length(vet_name) <= 80 and length(vet_phone) <= 20);
alter table public.app_settings add column if not exists pet_vet_partner text not null default '';

create table if not exists public.pet_weights (
  id         uuid primary key default gen_random_uuid(),
  salon_id   uuid not null references public.salons (id) on delete cascade,
  pet_id     uuid not null references public.pets (id) on delete cascade,
  date       date not null,
  kg         numeric(5, 1) not null check (kg > 0 and kg <= 150),
  created_at timestamptz not null default now(),
  unique (pet_id, date)
);
alter table public.pet_weights enable row level security;
drop policy if exists p_pet_weights_staff on public.pet_weights;
create policy p_pet_weights_staff on public.pet_weights for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select on public.pet_weights to authenticated;

create or replace function public.record_pet_weight(p_pet uuid, p_kg numeric)
returns json
language plpgsql security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id();
begin
  if not public.is_staff() then return json_build_object('ok', false, 'error', 'دسترسی ندارید'); end if;
  if p_kg is null or p_kg <= 0 or p_kg > 150 then return json_build_object('ok', false, 'error', 'وزن نامعتبر است'); end if;
  if not exists (select 1 from public.pets where id = p_pet and salon_id = v_salon) then
    return json_build_object('ok', false, 'error', 'حیوان پیدا نشد');
  end if;
  insert into public.pet_weights (salon_id, pet_id, date, kg) values (v_salon, p_pet, public.salon_today(), round(p_kg, 1))
  on conflict (pet_id, date) do update set kg = excluded.kg;
  update public.pets set weight_kg = round(p_kg, 1), updated_at = now() where id = p_pet;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.record_pet_weight(uuid, numeric) to authenticated;

-- the owner's report shows the partner vet when something was found
create or replace function public.get_visit_report(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare r public.pet_visit_reports; a public.appointments; v_found boolean;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{36}$' then
    return json_build_object('ok', false);
  end if;
  select * into r from public.pet_visit_reports where token_hash = encode(digest(p_token, 'sha256'), 'hex')
     and sent_at > now() - interval '180 days';
  if r.appointment_id is null then
    return json_build_object('ok', false);
  end if;
  select * into a from public.appointments where id = r.appointment_id;
  v_found := exists (select 1 from jsonb_object_keys(r.checks) k where k <> 'behavior');
  return json_build_object(
    'ok', true,
    'salon_name', (select name from public.salons where id = r.salon_id),
    'salon_slug', (select slug from public.salons where id = r.salon_id),
    'pet_name', a.pet_name, 'date', a.date, 'services_label', a.services_label,
    'checks', r.checks, 'note', nullif(r.note, ''), 'photos', r.photos,
    'vet_partner', case when v_found then nullif((select pet_vet_partner from public.app_settings where salon_id = r.salon_id), '') end,
    'products', coalesce((select json_agg(json_build_object('id', p.id, 'name', p.name, 'price', p.price, 'photo_path', p.photo_path))
                            from public.products p
                            join public.shop_settings ss on ss.salon_id = p.salon_id and ss.enabled
                           where p.id = any (r.product_ids) and p.active), '[]'::json));
end;
$fn$;
grant execute on function public.get_visit_report(text) to anon, authenticated;

-- ------------------------------------------------- 9. variants + tracking --
alter table public.products add column if not exists variant_group text not null default '';
alter table public.products add column if not exists variant_label text not null default '';
alter table public.products drop constraint if exists products_variant_len_check;
alter table public.products add constraint products_variant_len_check check (length(variant_group) <= 80 and length(variant_label) <= 40);
alter table public.orders add column if not exists tracking_code text not null default '';
alter table public.orders add column if not exists carrier text not null default '';

create or replace function public.get_shop()
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'enabled', coalesce(ss.enabled, false),
    'pickup', coalesce(ss.pickup_enabled, true) or not coalesce(ss.shipping_enabled, false),
    'pickup_address', coalesce(ss.pickup_address, ''),
    'shipping', coalesce(ss.shipping_enabled, false),
    'shipping_fee', coalesce(ss.shipping_fee, 0),
    'free_shipping_over', coalesce(ss.free_shipping_over, 0),
    'shipping_area', coalesce(ss.shipping_area, ''),
    'note', coalesce(ss.note, ''),
    'online', coalesce(pp.zarinpal_merchant_id, '') <> '',
    'cash', coalesce(ss.cash_enabled, false) or coalesce(pp.zarinpal_merchant_id, '') = '',
    'products', case when coalesce(ss.enabled, false) then coalesce((
      select json_agg(json_build_object(
               'id', p.id, 'name', p.name, 'description', p.description, 'category', p.category,
               'price', p.price, 'stock', p.stock, 'photo_path', p.photo_path,
               'variant_group', p.variant_group, 'variant_label', p.variant_label)
             order by p.sort_order, p.created_at)
        from public.products p where p.salon_id = c.salon_id and p.active), '[]'::json) else '[]'::json end
  )
  from (select public.current_salon_id() as salon_id) c
  left join public.shop_settings ss on ss.salon_id = c.salon_id
  left join public.salon_payment_settings pp on pp.salon_id = c.salon_id
  where c.salon_id is not null;
$fn$;
grant execute on function public.get_shop() to anon, authenticated;

-- set_order_status with a tracking code (replaces the 3-argument version)
drop function if exists public.set_order_status(uuid, text, text);
create or replace function public.set_order_status(p_order uuid, p_status text, p_note text default '',
                                                   p_tracking_code text default '', p_carrier text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare o public.orders; v_salon_name text; v_body text; v_note text := trim(coalesce(p_note, ''));
        v_track text := trim(coalesce(p_tracking_code, '')); v_carrier text := trim(coalesce(p_carrier, ''));
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  select * into o from public.orders where id = p_order and salon_id = public.current_salon_id() for update;
  if o.id is null then
    return json_build_object('ok', false, 'error', 'سفارش پیدا نشد');
  end if;
  if length(v_note) > 300 or length(v_track) > 40 or length(v_carrier) > 40 then
    return json_build_object('ok', false, 'error', 'توضیح طولانی است');
  end if;
  if o.status in ('delivered', 'cancelled') then
    return json_build_object('ok', false, 'error', 'این سفارش بسته شده است');
  end if;
  if o.status = 'awaiting_payment' and p_status <> 'cancelled' then
    return json_build_object('ok', false, 'error', 'این سفارش هنوز پرداخت نشده');
  end if;
  if p_status not in ('confirmed', 'ready', 'shipped', 'delivered', 'cancelled')
     or p_status = 'ready' and o.delivery <> 'pickup'
     or p_status = 'shipped' and o.delivery <> 'shipping' then
    return json_build_object('ok', false, 'error', 'وضعیت نامعتبر است');
  end if;
  if p_status = 'cancelled' and v_note = '' then
    return json_build_object('ok', false, 'error', 'دلیل لغو را بنویسید');
  end if;

  update public.orders
     set status = p_status, updated_at = now(),
         staff_note = case when p_status <> 'cancelled' and v_note <> '' then v_note else staff_note end,
         cancel_reason = case when p_status = 'cancelled' then v_note else cancel_reason end,
         refund_needed = refund_needed or (p_status = 'cancelled' and paid_at is not null),
         tracking_code = case when p_status = 'shipped' and v_track <> '' then v_track else tracking_code end,
         carrier = case when p_status = 'shipped' and v_carrier <> '' then v_carrier else carrier end
   where id = o.id;
  if p_status = 'cancelled' then
    perform public.release_order_stock(o.id);
  end if;

  select name into v_salon_name from public.salons where id = o.salon_id;
  v_body := case p_status
    when 'ready' then o.customer_name || ' عزیز، سفارش ' || o.code || ' آمادهٔ تحویل در ' || v_salon_name || ' است.'
                      || case when o.paid_at is null then E'\nمبلغ قابل پرداخت: ' || public.fa_money(o.total) || ' تومان' else '' end
    when 'shipped' then o.customer_name || ' عزیز، سفارش ' || o.code || ' از ' || v_salon_name || ' ارسال شد.'
                      || case when v_track <> '' then E'\nکد رهگیری' || case when v_carrier <> '' then ' (' || v_carrier || ')' else '' end || ': ' || v_track else '' end
    when 'cancelled' then o.customer_name || ' عزیز، سفارش ' || o.code || ' در ' || v_salon_name || ' لغو شد.'
                      || E'\nدلیل: ' || v_note
                      || case when o.paid_at is not null then E'\nمبلغ پرداختی به حسابتان برگردانده می‌شود.' else '' end
    else null end;
  if v_body is not null then
    if p_status <> 'cancelled' and v_note <> '' then
      v_body := v_body || E'\n' || v_note;
    end if;
    insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
    values (o.salon_id, o.customer_phone, v_body, 'order', 'queued', now());
  end if;
  return json_build_object('ok', true, 'status', p_status);
end;
$fn$;
grant execute on function public.set_order_status(uuid, text, text, text, text) to authenticated;

create or replace function public.order_json(o public.orders)
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'id', o.id, 'code', o.code, 'status', o.status, 'delivery', o.delivery, 'address', o.address,
    'subtotal', o.subtotal, 'shipping_fee', o.shipping_fee, 'total', o.total, 'discount', o.coupon_discount,
    'payment_method', o.payment_method, 'paid', o.paid_at is not null, 'refund_needed', o.refund_needed,
    'cancel_reason', nullif(o.cancel_reason, ''), 'staff_note', nullif(o.staff_note, ''), 'created_at', o.created_at,
    'tracking_code', nullif(o.tracking_code, ''), 'carrier', nullif(o.carrier, ''),
    'items', coalesce((select json_agg(json_build_object('name', i.name, 'qty', i.qty, 'unit_price', i.unit_price) order by i.name)
                         from public.order_items i where i.order_id = o.id), '[]'::json));
$fn$;
revoke all on function public.order_json(public.orders) from public, anon, authenticated;

-- ----------------------------------------------------------- 10. supplies --
create table if not exists public.supplies (
  id         uuid primary key default gen_random_uuid(),
  salon_id   uuid not null default public.current_salon_id() references public.salons (id) on delete cascade,
  name       text not null check (length(trim(name)) between 1 and 60),
  unit       text not null default 'عدد' check (length(unit) <= 15),
  qty        numeric(10, 2) not null default 0,
  low_at     numeric(10, 2) not null default 1 check (low_at >= 0),
  active     boolean not null default true,
  updated_at timestamptz not null default now(),
  unique (salon_id, name)
);
alter table public.supplies enable row level security;
drop policy if exists p_supplies_mgr on public.supplies;
create policy p_supplies_mgr on public.supplies for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id());
drop policy if exists p_supplies_staff_read on public.supplies;
create policy p_supplies_staff_read on public.supplies for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select, insert, update, delete on public.supplies to authenticated;

create table if not exists public.supply_moves (
  id         uuid primary key default gen_random_uuid(),
  salon_id   uuid not null references public.salons (id) on delete cascade,
  supply_id  uuid not null references public.supplies (id) on delete cascade,
  delta      numeric(10, 2) not null,
  kind       text not null check (kind in ('purchase', 'use', 'adjust')),
  cost       bigint,
  note       text not null default '',
  by_user    uuid,
  created_at timestamptz not null default now()
);
create index if not exists supply_moves_supply_idx on public.supply_moves (supply_id, created_at desc);
alter table public.supply_moves enable row level security;
drop policy if exists p_supply_moves_staff on public.supply_moves;
create policy p_supply_moves_staff on public.supply_moves for select
  using (public.is_staff() and salon_id = public.current_salon_id());
grant select on public.supply_moves to authenticated;

-- purchase (manager; booked as an expense), use (any staff), adjust (manager)
create or replace function public.supply_move(p_supply uuid, p_kind text, p_qty numeric, p_cost bigint default null, p_note text default '')
returns json
language plpgsql security definer set search_path = public as $fn$
declare s public.supplies; v_delta numeric;
begin
  if not public.is_staff() then return json_build_object('ok', false, 'error', 'دسترسی ندارید'); end if;
  if p_kind not in ('purchase', 'use', 'adjust') or (p_kind in ('purchase', 'adjust') and not public.is_manager()) then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  if p_qty is null or p_qty < 0 or p_qty > 100000 or (p_kind <> 'adjust' and p_qty = 0) then
    return json_build_object('ok', false, 'error', 'مقدار نامعتبر است');
  end if;
  select * into s from public.supplies where id = p_supply and salon_id = public.current_salon_id() for update;
  if s.id is null then return json_build_object('ok', false, 'error', 'قلم پیدا نشد'); end if;
  v_delta := case p_kind when 'purchase' then p_qty when 'use' then -p_qty else p_qty - s.qty end;
  if s.qty + v_delta < 0 then return json_build_object('ok', false, 'error', 'موجودی کافی نیست'); end if;
  update public.supplies set qty = qty + v_delta, updated_at = now() where id = s.id;
  insert into public.supply_moves (salon_id, supply_id, delta, kind, cost, note, by_user)
  values (s.salon_id, s.id, v_delta, p_kind, case when p_kind = 'purchase' then p_cost end, left(coalesce(p_note, ''), 200), auth.uid());
  if p_kind = 'purchase' and coalesce(p_cost, 0) > 0 then
    insert into public.expenses (id, salon_id, title, category, amount, date, note)
    values ('exp-' || substr(md5(gen_random_uuid()::text), 1, 12), s.salon_id, 'خرید ' || s.name, 'supplies', p_cost,
            public.salon_today(), public.fa_digits(trim(to_char(p_qty, 'FM999999990.##'))) || ' ' || s.unit);
  end if;
  return json_build_object('ok', true, 'qty', s.qty + v_delta, 'low', s.qty + v_delta <= s.low_at);
end;
$fn$;
grant execute on function public.supply_move(uuid, text, numeric, bigint, text) to authenticated;

-- ------------------------------------------------------------ 11. check-in --
alter table public.appointments add column if not exists checked_in_at timestamptz;

create or replace function public.check_in(p_code text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare a public.appointments; v_code text := coalesce(p_code, '');
begin
  if not public.is_staff() then return json_build_object('ok', false, 'error', 'دسترسی ندارید'); end if;
  -- a QR may carry a link (…?code=MN-12345); keep the code itself
  if v_code ~* '[?&]code=' then v_code := substring(v_code from '(?i)[?&]code=([^&#]+)'); end if;
  v_code := upper(regexp_replace(translate(v_code, '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '[^A-Za-z0-9-]', '', 'g'));
  select * into a from public.appointments
   where salon_id = public.current_salon_id() and upper(tracking_code) = v_code and date = public.salon_today()
     and status in ('pending', 'confirmed', 'rescheduled', 'awaiting_payment')
   order by start_min limit 1 for update;
  if a.id is null then
    return json_build_object('ok', false, 'error', 'نوبت امروز با این کد پیدا نشد');
  end if;
  update public.appointments
     set checked_in_at = coalesce(checked_in_at, now()),
         groom_stage = case when pet_name is not null and groom_stage is null then 'arrived' else groom_stage end,
         groom_stage_at = case when pet_name is not null and groom_stage is null then now() else groom_stage_at end
   where id = a.id;
  return json_build_object('ok', true, 'id', a.id, 'customer_name', a.customer_name, 'pet_name', a.pet_name,
                           'start_min', a.start_min, 'staff_id', a.staff_id, 'already', a.checked_in_at is not null);
end;
$fn$;
grant execute on function public.check_in(text) to authenticated;

-- ------------------------------------------------------------ 12. branches --
create table if not exists public.user_branches (
  user_id    uuid not null references public.users (id) on delete cascade,
  salon_id   uuid not null references public.salons (id) on delete cascade,
  role       text not null default 'owner' check (role in ('owner', 'manager')),
  created_at timestamptz not null default now(),
  primary key (user_id, salon_id)
);
alter table public.user_branches enable row level security;
drop policy if exists p_user_branches_self on public.user_branches;
create policy p_user_branches_self on public.user_branches for select using (user_id = auth.uid());
grant select on public.user_branches to authenticated;

-- Platform admin: give a salon's owner access to another salon as a branch.
create or replace function public.admin_link_branch(p_owner_phone text, p_branch_slug text)
returns json
language plpgsql security definer set search_path = public as $fn$
declare u public.users; v_branch uuid;
begin
  if not public.is_platform_admin() then return json_build_object('ok', false, 'error', 'دسترسی ندارید'); end if;
  select * into u from public.users where phone = p_owner_phone and role in ('owner', 'manager');
  if u.id is null then return json_build_object('ok', false, 'error', 'مدیری با این شماره پیدا نشد'); end if;
  select id into v_branch from public.salons where slug = lower(trim(p_branch_slug));
  if v_branch is null then return json_build_object('ok', false, 'error', 'سالن پیدا نشد'); end if;
  insert into public.user_branches (user_id, salon_id, role) values (u.id, u.salon_id, u.role) on conflict do nothing;
  insert into public.user_branches (user_id, salon_id, role) values (u.id, v_branch, 'owner') on conflict do nothing;
  return json_build_object('ok', true);
end;
$fn$;
grant execute on function public.admin_link_branch(text, text) to authenticated;

create or replace function public.my_branches()
returns json
language sql stable security definer set search_path = public as $fn$
  select coalesce(json_agg(json_build_object('salon_id', s.id, 'name', s.name, 'slug', s.slug,
                                             'current', s.id = (select salon_id from public.users where id = auth.uid()))
                           order by s.name), '[]'::json)
    from public.user_branches b join public.salons s on s.id = b.salon_id and s.active
   where b.user_id = auth.uid();
$fn$;
grant execute on function public.my_branches() to authenticated;

create or replace function public.switch_branch(p_salon uuid)
returns json
language plpgsql security definer set search_path = public as $fn$
declare b public.user_branches;
begin
  select * into b from public.user_branches where user_id = auth.uid() and salon_id = p_salon;
  if b.user_id is null or not exists (select 1 from public.salons where id = p_salon and active) then
    return json_build_object('ok', false, 'error', 'این شعبه در دسترس شما نیست');
  end if;
  update public.users set salon_id = p_salon, role = b.role, stylist_id = null where id = auth.uid();
  return json_build_object('ok', true, 'slug', (select slug from public.salons where id = p_salon));
end;
$fn$;
grant execute on function public.switch_branch(uuid) to authenticated;

-- One line per branch: today's bookings, this month's completed revenue.
create or replace function public.branches_summary()
returns json
language sql stable security definer set search_path = public as $fn$
  select coalesce(json_agg(json_build_object(
           'salon_id', s.id, 'name', s.name,
           'today', (select count(*) from public.appointments a where a.salon_id = s.id and a.date = public.salon_today()
                       and a.status not in ('cancelled', 'no_show')),
           'month_revenue', coalesce((select sum(a.final_price) from public.appointments a where a.salon_id = s.id
                                        and a.status = 'completed' and a.date >= date_trunc('month', public.salon_today())::date), 0),
           'month_orders', coalesce((select sum(o.total) from public.orders o where o.salon_id = s.id
                                       and o.status in ('pending', 'confirmed', 'ready', 'shipped', 'delivered')
                                       and o.created_at >= date_trunc('month', now())), 0))
         order by s.name), '[]'::json)
    from public.user_branches b join public.salons s on s.id = b.salon_id and s.active
   where b.user_id = auth.uid();
$fn$;
grant execute on function public.branches_summary() to authenticated;

-- ----------------------------------------------------- 13a. two-step login --
-- When a staff member has turned on a TOTP factor (Supabase Auth MFA), a
-- password-only session (aal1) no longer counts as staff anywhere.
create or replace function public.mfa_ok()
returns boolean
language plpgsql stable security definer set search_path = public as $fn$
declare n int;
begin
  if auth.uid() is null or to_regclass('auth.mfa_factors') is null then
    return true;
  end if;
  if coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2' then
    return true;
  end if;
  execute 'select count(*) from auth.mfa_factors where user_id = $1 and status = ''verified''' into n using auth.uid();
  return n = 0;
end;
$fn$;
grant execute on function public.mfa_ok() to anon, authenticated;

create or replace function public.my_role() returns text
language sql stable security definer set search_path = public as $fn$
  select role from public.users where id = auth.uid() and public.mfa_ok();
$fn$;

-- A signed-in caller with no staff row got NULL here, and `if not
-- public.is_manager()` (NOT NULL is not true) let them through. Signed-in
-- callers now always get true/false. Server-side jobs (no auth.uid())
-- keep the old behaviour that system maintenance relies on.
create or replace function public.is_manager() returns boolean
language sql stable security definer set search_path = public as $fn$
  select case when auth.uid() is null then public.my_role() in ('owner', 'manager')
              else coalesce(public.my_role() in ('owner', 'manager'), false) end;
$fn$;

create or replace function public.is_staff() returns boolean
language sql stable security definer set search_path = public as $fn$
  select coalesce((select active from public.users where id = auth.uid()), false) and public.mfa_ok();
$fn$;

-- --------------------------------------------------------- 13b. backups --
create table if not exists public.salon_backups (
  id         uuid primary key default gen_random_uuid(),
  salon_id   uuid not null references public.salons (id) on delete cascade,
  created_at timestamptz not null default now(),
  size_bytes int not null default 0,
  data       jsonb not null
);
create index if not exists salon_backups_salon_idx on public.salon_backups (salon_id, created_at desc);
alter table public.salon_backups enable row level security;
-- rows are read through my_backups()/get_backup() only (the data column is large)
revoke all on public.salon_backups from anon, authenticated;

create or replace function public.backup_salon(p_salon uuid)
returns uuid
language plpgsql security definer set search_path = public as $fn$
declare v_data jsonb := '{}'::jsonb; t text; v_rows jsonb; v_id uuid;
begin
  foreach t in array array['services', 'stylists', 'working_hours', 'customers', 'appointments', 'expenses', 'pets',
                           'products', 'orders', 'order_items', 'pet_packages', 'package_purchases', 'gift_cards',
                           'coupons', 'supplies', 'feedbacks', 'app_settings', 'shop_settings', 'salon_profiles'] loop
    if to_regclass('public.' || t) is not null then
      execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.salon_id = $1', t)
         into v_rows using p_salon;
      v_data := v_data || jsonb_build_object(t, v_rows);
    end if;
  end loop;
  v_data := v_data || jsonb_build_object('_meta', jsonb_build_object('salon_id', p_salon, 'created_at', now(), 'version', 'v2.51'));
  insert into public.salon_backups (salon_id, size_bytes, data) values (p_salon, octet_length(v_data::text), v_data)
  returning id into v_id;
  -- keep the newest 7
  delete from public.salon_backups where salon_id = p_salon and id not in (
    select id from public.salon_backups where salon_id = p_salon order by created_at desc limit 7);
  return v_id;
end;
$fn$;
revoke all on function public.backup_salon(uuid) from public, anon, authenticated;

create or replace function public.backup_all_salons()
returns int
language plpgsql security definer set search_path = public as $fn$
declare r record; n int := 0;
begin
  for r in select id from public.salons where active loop
    perform public.backup_salon(r.id);
    n := n + 1;
  end loop;
  return n;
end;
$fn$;
revoke all on function public.backup_all_salons() from public, anon, authenticated;
grant execute on function public.backup_all_salons() to service_role;

create or replace function public.my_backups()
returns json
language sql stable security definer set search_path = public as $fn$
  select coalesce(json_agg(json_build_object('id', id, 'created_at', created_at, 'size_bytes', size_bytes) order by created_at desc), '[]'::json)
    from public.salon_backups where salon_id = public.current_salon_id() and public.is_manager();
$fn$;
grant execute on function public.my_backups() to authenticated;

create or replace function public.backup_now()
returns json
language plpgsql security definer set search_path = public as $fn$
begin
  if not public.is_manager() then return json_build_object('ok', false, 'error', 'دسترسی ندارید'); end if;
  if exists (select 1 from public.salon_backups where salon_id = public.current_salon_id() and created_at > now() - interval '10 minutes') then
    return json_build_object('ok', false, 'error', 'نسخهٔ پشتیبان چند دقیقه پیش گرفته شده');
  end if;
  return json_build_object('ok', true, 'id', public.backup_salon(public.current_salon_id()));
end;
$fn$;
grant execute on function public.backup_now() to authenticated;

create or replace function public.get_backup(p_id uuid)
returns jsonb
language sql stable security definer set search_path = public as $fn$
  select data from public.salon_backups where id = p_id and salon_id = public.current_salon_id() and public.is_manager();
$fn$;
grant execute on function public.get_backup(uuid) to authenticated;


-- >>>>>>>>>> supabase/migrations/v2.52_beauty_suite.sql
-- =============================================================================
--  v2.52 — the men's / women's salon suite
--
--  1. Shop for beauty salons: products for men / women / everyone, and a
--     purchase cost per product (managers only) so the shop's gross profit
--     reaches accounting.
--  2. shop_analytics(): the shop's numbers for BI and accounting (revenue,
--     gross profit, average order, top products, categories, daily series,
--     and how many service customers also buy products).
--  3. Client record (the beauty-salon twin of the pet health record):
--     allergies, hair / skin type, colour formula, patch test date, notes.
--  4. Visit report (before / after photos + note + recommended products)
--     for any booking, not only pets — the SMS and page text follow the
--     salon type.
--  Idempotent; safe to run again.
-- =============================================================================

-- ------------------------------------------------------------- 1. shop ------
alter table public.products add column if not exists audience text not null default 'all';
alter table public.products drop constraint if exists products_audience_check;
alter table public.products add constraint products_audience_check check (audience in ('all', 'men', 'women'));

-- Purchase cost lives apart from products: staff (and get_shop) read products,
-- only managers see what the salon paid.
create table if not exists public.product_costs (
  product_id  uuid primary key references public.products (id) on delete cascade,
  salon_id    uuid not null references public.salons (id) on delete cascade default public.current_salon_id(),
  cost_price  bigint not null check (cost_price between 0 and 10000000000),
  updated_at  timestamptz not null default now()
);
alter table public.product_costs enable row level security;
drop policy if exists p_product_costs_mgr on public.product_costs;
create policy p_product_costs_mgr on public.product_costs for all
  using (public.is_manager() and salon_id = public.current_salon_id())
  with check (public.is_manager() and salon_id = public.current_salon_id()
              and exists (select 1 from public.products p where p.id = product_id and p.salon_id = public.current_salon_id()));
grant select, insert, update, delete on public.product_costs to authenticated;

create or replace function public.get_shop()
returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'enabled', coalesce(ss.enabled, false),
    'pickup', coalesce(ss.pickup_enabled, true) or not coalesce(ss.shipping_enabled, false),
    'pickup_address', coalesce(ss.pickup_address, ''),
    'shipping', coalesce(ss.shipping_enabled, false),
    'shipping_fee', coalesce(ss.shipping_fee, 0),
    'free_shipping_over', coalesce(ss.free_shipping_over, 0),
    'shipping_area', coalesce(ss.shipping_area, ''),
    'note', coalesce(ss.note, ''),
    'online', coalesce(pp.zarinpal_merchant_id, '') <> '',
    'cash', coalesce(ss.cash_enabled, false) or coalesce(pp.zarinpal_merchant_id, '') = '',
    'products', case when coalesce(ss.enabled, false) then coalesce((
      select json_agg(json_build_object(
               'id', p.id, 'name', p.name, 'description', p.description, 'category', p.category,
               'price', p.price, 'stock', p.stock, 'photo_path', p.photo_path,
               'variant_group', p.variant_group, 'variant_label', p.variant_label, 'audience', p.audience)
             order by p.sort_order, p.created_at)
        from public.products p where p.salon_id = c.salon_id and p.active), '[]'::json) else '[]'::json end
  )
  from (select public.current_salon_id() as salon_id) c
  left join public.shop_settings ss on ss.salon_id = c.salon_id
  left join public.salon_payment_settings pp on pp.salon_id = c.salon_id
  where c.salon_id is not null;
$fn$;
grant execute on function public.get_shop() to anon, authenticated;

-- --------------------------------------------------- 2. shop analytics -----
create or replace function public.shop_analytics(p_from date, p_to date)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare v_salon uuid := public.current_salon_id();
begin
  if not public.is_manager() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then
    return json_build_object('ok', false, 'error', 'بازهٔ نامعتبر');
  end if;
  return (
    with o as (
      select * from public.orders
       where salon_id = v_salon and status in ('pending', 'confirmed', 'ready', 'shipped', 'delivered')
         and (created_at at time zone coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran'))::date between p_from and p_to
    ), li as (
      select i.*, p.category, pc.cost_price
        from public.order_items i join o on o.id = i.order_id
        left join public.products p on p.id = i.product_id
        left join public.product_costs pc on pc.product_id = i.product_id
    ), visits as (
      select distinct customer_phone as phone from public.appointments
       where salon_id = v_salon and status = 'completed' and date between p_from and p_to
    ), buyers as (
      select distinct customer_phone as phone from o
    )
    select json_build_object(
      'ok', true,
      'orders', (select count(*) from o),
      'revenue', coalesce((select sum(subtotal - coupon_discount) from o), 0),
      'shipping', coalesce((select sum(shipping_fee) from o), 0),
      'discount', coalesce((select sum(coupon_discount) from o), 0),
      'items', coalesce((select sum(qty) from li), 0),
      'buyers', (select count(*) from buyers),
      'cogs', coalesce((select sum(qty * cost_price) from li where cost_price is not null), 0),
      'revenue_with_cost', coalesce((select sum(qty * unit_price) from li where cost_price is not null), 0),
      'items_revenue', coalesce((select sum(qty * unit_price) from li), 0),
      'visit_customers', (select count(*) from visits),
      'buyers_with_visit', (select count(*) from buyers b join visits v on v.phone = b.phone),
      'top_products', coalesce((
        select json_agg(t order by t.revenue desc) from (
          select name, sum(qty)::int as qty, sum(qty * unit_price) as revenue,
                 case when bool_and(cost_price is not null) then sum(qty * (unit_price - cost_price)) end as profit
            from li group by name order by 3 desc limit 8) t), '[]'::json),
      'by_category', coalesce((
        select json_agg(t order by t.revenue desc) from (
          select coalesce(nullif(category, ''), 'other') as category, sum(qty * unit_price) as revenue
            from li group by 1) t), '[]'::json),
      'daily', coalesce((
        select json_agg(t order by t.date) from (
          select (created_at at time zone coalesce(nullif(current_setting('app.timezone', true), ''), 'Asia/Tehran'))::date as date, sum(subtotal - coupon_discount) as revenue
            from o group by 1) t), '[]'::json)
    )
  );
end;
$fn$;
grant execute on function public.shop_analytics(date, date) to authenticated;

-- ------------------------------------------------------ 3. client record ----
create table if not exists public.client_records (
  salon_id       uuid not null references public.salons (id) on delete cascade default public.current_salon_id(),
  phone          text not null check (phone ~ '^09[0-9]{9}$'),
  allergies      text not null default '' check (length(allergies) <= 300),
  hair_type      text not null default '' check (length(hair_type) <= 60),
  skin_type      text not null default '' check (length(skin_type) <= 60),
  color_formula  text not null default '' check (length(color_formula) <= 400),
  patch_test_at  date,
  notes          text not null default '' check (length(notes) <= 600),
  updated_at     timestamptz not null default now(),
  updated_by     uuid,
  primary key (salon_id, phone)
);
alter table public.client_records enable row level security;
-- managers: every client; a stylist: clients who have booked with them
drop policy if exists p_client_records_staff on public.client_records;
create policy p_client_records_staff on public.client_records for all
  using (salon_id = public.current_salon_id() and public.is_staff()
         and (public.is_manager() or exists (select 1 from public.appointments a
                where a.salon_id = client_records.salon_id and a.customer_phone = client_records.phone
                  and a.staff_id = public.my_stylist_id())))
  with check (salon_id = public.current_salon_id() and public.is_staff()
         and (public.is_manager() or exists (select 1 from public.appointments a
                where a.salon_id = client_records.salon_id and a.customer_phone = client_records.phone
                  and a.staff_id = public.my_stylist_id())));
grant select, insert, update on public.client_records to authenticated;

create or replace function public.touch_client_record() returns trigger
language plpgsql set search_path = public as $fn$
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end;
$fn$;
drop trigger if exists trg_client_records_touch on public.client_records;
create trigger trg_client_records_touch before insert or update on public.client_records
  for each row execute function public.touch_client_record();

-- ------------------------------------------------------ 4. visit report -----
-- Same as v2.49, but the SMS names the client's visit when there is no pet.
create or replace function public.save_visit_report(
  p_appt text, p_checks jsonb, p_note text default '', p_photos text[] default '{}',
  p_product_ids uuid[] default '{}', p_send boolean default false
)
returns json
language plpgsql security definer set search_path = public as $fn$
declare a public.appointments; v_checks jsonb := '{}'::jsonb; k text; v_token text; v_link text; v_salon_name text;
        v_photos text[]; v_products uuid[]; v_already timestamptz; v_title text;
begin
  if not public.is_staff() then
    return json_build_object('ok', false, 'error', 'دسترسی ندارید');
  end if;
  select * into a from public.appointments where id = p_appt and salon_id = public.current_salon_id();
  if a.id is null or not (public.is_manager() or a.staff_id = public.my_stylist_id()) then
    return json_build_object('ok', false, 'error', 'نوبت پیدا نشد');
  end if;
  if a.pet_name is not null then
    foreach k in array array['fleas', 'ticks', 'skin', 'ears', 'eyes', 'teeth', 'matting', 'nails'] loop
      if coalesce(p_checks ->> k, '') = 'true' then v_checks := v_checks || jsonb_build_object(k, true); end if;
    end loop;
    if coalesce(p_checks ->> 'behavior', '') in ('calm', 'nervous', 'aggressive') then
      v_checks := v_checks || jsonb_build_object('behavior', p_checks ->> 'behavior');
    end if;
  end if;
  if length(coalesce(p_note, '')) > 600 then
    return json_build_object('ok', false, 'error', 'یادداشت طولانی است');
  end if;
  select coalesce(array_agg(x), '{}') into v_photos
    from unnest(coalesce(p_photos, '{}')) x
   where x ~ ('^' || a.salon_id || '/' || a.id || '/(before|after)-[a-z0-9-]{8,64}\.(jpg|jpeg|png|webp)$');
  if cardinality(v_photos) > 8 then
    return json_build_object('ok', false, 'error', 'حداکثر ۸ عکس');
  end if;
  select coalesce(array_agg(p.id), '{}') into v_products
    from public.products p where p.id = any (coalesce(p_product_ids, '{}')) and p.salon_id = a.salon_id and p.active;
  if cardinality(v_products) > 4 then
    return json_build_object('ok', false, 'error', 'حداکثر ۴ محصول پیشنهادی');
  end if;

  select sent_at into v_already from public.pet_visit_reports where appointment_id = a.id;
  insert into public.pet_visit_reports as r (appointment_id, salon_id, pet_id, checks, note, photos, product_ids)
  values (a.id, a.salon_id, a.pet_id, v_checks, trim(coalesce(p_note, '')), v_photos, v_products)
  on conflict (appointment_id) do update
     set checks = excluded.checks, note = excluded.note, photos = excluded.photos,
         product_ids = excluded.product_ids, updated_at = now();

  if a.pet_id is not null and v_checks ? 'behavior' then
    update public.pets set temperament = v_checks ->> 'behavior', updated_at = now() where id = a.pet_id;
  end if;

  if p_send and a.customer_phone ~ '^09[0-9]{9}$' then
    v_token := encode(gen_random_bytes(18), 'hex');
    update public.pet_visit_reports set token_hash = encode(digest(v_token, 'sha256'), 'hex'), sent_at = now()
     where appointment_id = a.id;
    v_link := public.public_link('/visit?token=' || v_token);
    select name into v_salon_name from public.salons where id = a.salon_id;
    v_title := case when a.pet_name is not null
                    then 'گزارش آرایش ' || coalesce(nullif(a.pet_name, ''), 'حیوان شما')
                    else coalesce(nullif(split_part(trim(a.customer_name), ' ', 1), '') || ' عزیز، گزارش', 'گزارش') || ' نوبت شما' end;
    if v_link is not null then
      insert into public.sms_messages (salon_id, to_phone, body, kind, status, scheduled_for)
      values (a.salon_id, a.customer_phone,
              v_title || ' در ' || v_salon_name
                || case when cardinality(v_photos) > 0 then ' (با عکس قبل و بعد)' else '' end
                || case when cardinality(v_products) > 0 then ' و محصولات پیشنهادی' else '' end || E':\n' || v_link,
              'pet_report', 'queued', now());
    end if;
    return json_build_object('ok', true, 'sent', v_link is not null, 'link', v_link, 'resent', v_already is not null);
  end if;
  return json_build_object('ok', true, 'sent', false);
end;
$fn$;
grant execute on function public.save_visit_report(text, jsonb, text, text[], uuid[], boolean) to authenticated;

create or replace function public.get_visit_report(p_token text)
returns json
language plpgsql stable security definer set search_path = public as $fn$
declare r public.pet_visit_reports; a public.appointments; v_found boolean;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{36}$' then
    return json_build_object('ok', false);
  end if;
  select * into r from public.pet_visit_reports where token_hash = encode(digest(p_token, 'sha256'), 'hex')
     and sent_at > now() - interval '180 days';
  if r.appointment_id is null then
    return json_build_object('ok', false);
  end if;
  select * into a from public.appointments where id = r.appointment_id;
  v_found := exists (select 1 from jsonb_object_keys(r.checks) k where k <> 'behavior');
  return json_build_object(
    'ok', true,
    'salon_name', (select name from public.salons where id = r.salon_id),
    'salon_slug', (select slug from public.salons where id = r.salon_id),
    'business_type', (select business_type from public.salons where id = r.salon_id),
    'pet_name', a.pet_name, 'customer_first_name', nullif(split_part(trim(a.customer_name), ' ', 1), ''),
    'date', a.date, 'services_label', a.services_label, 'staff_name', a.staff_name,
    'checks', r.checks, 'note', nullif(r.note, ''), 'photos', r.photos,
    'vet_partner', case when v_found then nullif((select pet_vet_partner from public.app_settings where salon_id = r.salon_id), '') end,
    'products', coalesce((select json_agg(json_build_object('id', p.id, 'name', p.name, 'price', p.price, 'photo_path', p.photo_path))
                            from public.products p
                            join public.shop_settings ss on ss.salon_id = p.salon_id and ss.enabled
                           where p.id = any (r.product_ids) and p.active), '[]'::json));
end;
$fn$;
grant execute on function public.get_visit_report(text) to anon, authenticated;

